def shell_quote(cmd):
    p = subprocess.run(cmd, capture_output=True)
    if p.returncode:
        raise RuntimeError(p.stderr.decode("utf-8", "replace")[-2000:])
    return p


# An ffprobe call costs a process start and, on an external volume, a
# seek out to the disc. Building the interface asks the same questions
# about the same file over and over -- timecode, length, channels,
# frame rate -- and one process each held the window thread until the
# disc answered.
_PROBE = {}


def file_stamp(path):
    """Identify a file by what changes when it is written to."""
    try:
        s = os.stat(path)
    except OSError:
        return None
    return (os.path.abspath(path), int(s.st_mtime_ns), int(s.st_size))


def probe_remember(name, path, work):
    """Return a measured property of a file, asking only once.

    Keyed on size and modification time: a file that has changed is
    measured again, an unchanged one is answered from memory. A file
    that cannot even be stat'ed is measured every time, because there
    is nothing to key on.
    """
    stamp = file_stamp(path)
    if stamp is None:
        return work()
    api_key = (name,) + stamp
    if api_key not in _PROBE:
        if len(_PROBE) > 4000:
            _PROBE.clear()
        _PROBE[api_key] = work()
    return _PROBE[api_key]


def probe_has(name, path):
    """Report whether this measurement of this file is already there."""
    stamp = file_stamp(path)
    return stamp is not None and (name,) + stamp in _PROBE


def _ffprobe_text(path):
    return subprocess.run(["ffprobe", "-v", "error", "-print_format", "json",
                           "-show_format", "-show_streams", path],
                          capture_output=True).stdout


def ffprobe_json(path):
    """Return what ffprobe says about a file.

    Parsed afresh from the remembered text each time, so a caller that
    changes the dictionary cannot affect the next one.
    """
    out = probe_remember("ffprobe", path, lambda: _ffprobe_text(path))
    return json.loads(out or b"{}")


def timecode_string(seconds, fps=30.0):
    if seconds < 0:
        seconds = 0.0
    f = int(round((seconds - int(seconds)) * fps))
    s = int(seconds)
    if f >= int(round(fps)):
        f, s = 0, s + 1
    return "%02d:%02d:%02d:%02d" % (s // 3600 % 24, s % 3600 // 60, s % 60, f)


def csv_line(values):
    """One row of a CSV file: comma separated, quoted where it matters.

    Comma and full stop, in every language. These files are read by other
    programs and compared across months; a separator that follows the
    language of the run would make two runs incomparable.
    """
    out = []
    for x in values:
        x = str(x)
        if any(c in x for c in ',";\r\n'):
            x = '"%s"' % x.replace('"', '""')
        out.append(x)
    return ",".join(out) + "\n"


def parse_timecode(s, fps=30.0):
    """Parse '6.4087', '0:06', '1:23:45' or '17:15:56:12' into seconds.

    Drop frame writes the last colon as a semicolon, '17:15:56;12'. That
    is the same value; how the frames are counted is a question for
    timecode_to_frames, not for a length in seconds.
    """
    t = str(s).strip().replace(";", ":")
    p = t.split(":")
    if len(p) == 4:
        return float(p[0]) * 3600 + float(p[1]) * 60 + float(p[2]) + float(p[3]) / fps
    if len(p) == 3:
        return float(p[0]) * 3600 + float(p[1]) * 60 + float(p[2])
    if len(p) == 2:
        return float(p[0]) * 60 + float(p[1])
    return float(t)


def frame_rate_fraction(fps):
    """Return a frame rate as a fraction: 29.97 -> 30000/1001.

    iXML requires a fraction rather than a decimal.
    """
    for whole, num, the_one in ((23.976, 24000, 1001), (29.97, 30000, 1001),
                           (47.952, 48000, 1001), (59.94, 60000, 1001),
                           (119.88, 120000, 1001)):
        if abs(fps - whole) < 0.02:
            return num, the_one
    return int(round(fps)), 1


def is_drop_frame(tc):
    """Report whether a timecode string is drop frame.

    The notation decides, not the frame rate: drop frame uses a semicolon
    before the frames. 29.97 exists in both flavours, so guessing from the
    rate is wrong half the time. No marker means non-drop.
    """
    return ";" in str(tc or "")


def build_ixml(name, tr, fps, bits=24, channels=1, df=False):
    """Build the iXML block for one track.

    Resolve is happy with bext alone, but Premiere and Media Composer fall
    back to iXML. Writing both costs nothing.
    """
    num, the_one = frame_rate_fraction(fps)
    ndf = not df
    tracks = "".join(
        "    <TRACK>\n      <CHANNEL_INDEX>%d</CHANNEL_INDEX>\n"
        "      <INTERLEAVE_INDEX>%d</INTERLEAVE_INDEX>\n"
        "      <NAME>%s</NAME>\n    </TRACK>\n" % (k, k, _xml_escape(name))
        for k in range(1, max(1, channels) + 1))
    return (
        '<?xml version="1.0" encoding="UTF-8"?>\n<BWFXML>\n'
        '  <IXML_VERSION>1.5</IXML_VERSION>\n'
        '  <PROJECT>%s</PROJECT>\n'
        '  <TAPE>%s</TAPE>\n'
        '  <TAKE>1</TAKE>\n'
        '  <SPEED>\n'
        '    <NOTE>videopodcast-magic</NOTE>\n'
        '    <MASTER_SPEED>%d/%d</MASTER_SPEED>\n'
        '    <CURRENT_SPEED>%d/%d</CURRENT_SPEED>\n'
        '    <TIMECODE_RATE>%d/%d</TIMECODE_RATE>\n'
        '    <TIMECODE_FLAG>%s</TIMECODE_FLAG>\n'
        '    <FILE_SAMPLE_RATE>%d</FILE_SAMPLE_RATE>\n'
        '    <AUDIO_BIT_DEPTH>%d</AUDIO_BIT_DEPTH>\n'
        '    <TIMESTAMP_SAMPLES_SINCE_MIDNIGHT_HI>%d'
        '</TIMESTAMP_SAMPLES_SINCE_MIDNIGHT_HI>\n'
        '    <TIMESTAMP_SAMPLES_SINCE_MIDNIGHT_LO>%d'
        '</TIMESTAMP_SAMPLES_SINCE_MIDNIGHT_LO>\n'
        '  </SPEED>\n'
        '  <TRACK_LIST>\n    <TRACK_COUNT>%d</TRACK_COUNT>\n%s'
        '  </TRACK_LIST>\n</BWFXML>\n'
        % (_xml_escape(name), _xml_escape(name), num, the_one, num, the_one, num, the_one,
           "NDF" if ndf else "DF", SR, bits,
           tr >> 32, tr & 0xFFFFFFFF, max(1, channels), tracks))


def _xml_escape(s):
    return (str(s).replace("&", "&amp;").replace("<", "&lt;")
            .replace(">", "&gt;"))


def append_ixml(file_path, xml):
    """Append the iXML block as a RIFF chunk and fix up the RIFF size."""
    payload = xml.encode("utf-8")
    if len(payload) % 2:
        payload += b"\x00"
    with open(file_path, "r+b") as f:
        f.seek(0, os.SEEK_END)
        end = f.tell()
        f.write(b"iXML" + struct.pack("<I", len(payload)) + payload)
        f.seek(4)
        f.write(struct.pack("<I", end + len(payload)))


def parse_time_point(s, fps=30.0):
    """Parse a --in-point/--out-point time.

    Returns (seconds, absolute). Absolute means wall clock since midnight,
    i.e. a timecode; everything else counts from the start of the window.

        17:20:14:00   absolute, with frames
        17:20:14      absolute
        +12:30        from window start, twelve and a half minutes
        12:30         same
        90            same, in seconds
        -30           measured back from the window end (--out-point only)
    """
    t = str(s).strip()
    if not t:
        return None, False
    minus = t.startswith("-")
    absolute = t.count(":") >= 2 and not t.startswith(("+", "-"))
    value = parse_timecode(t.lstrip("+-"), fps)
    return (-value if minus else value), absolute


def as_relative_time(seconds):
    """Format a position the way --in-point expects it."""
    ms = int(round(max(0.0, seconds) * 1000))
    s = ms // 1000
    return "+%d:%02d:%02d.%03d" % (s // 3600, s % 3600 // 60, s % 60,
                                   ms % 1000)


def as_hms(sec, mark=None):
    """Write a duration as h:mm:ss with milliseconds.

    *mark* overrides the decimal point. A file that other programs read
    passes ".", so what is in it does not depend on the language.
    """
    # Round to milliseconds first, then split -- otherwise 119.9995 s
    # comes out as "0:01:59.1000".
    ms = int(round(abs(sec) * 1000))
    s = ms // 1000
    return "%s%d:%02d:%02d%s%03d" % ("-" if sec < 0 else "", s // 3600,
                                     s % 3600 // 60, s % 60,
                                     T(".") if mark is None else mark,
                                     ms % 1000)


def sample_count(path):
    """Return the length of a file in samples at the working rate."""
    return probe_remember("samples", path, lambda: _sample_count(path))


def _sample_count(path):
    # Out of the one description of the file rather than a second call
    # of its own: duration_ts counts samples exactly, where a duration
    # in seconds has already been rounded.
    d = ffprobe_json(path)
    a = next((x for x in d.get("streams", [])
              if x.get("codec_type") == "audio"), {})
    try:
        n, sr = int(a["duration_ts"]), int(a.get("sample_rate") or SR)
        return int(round(n * SR / sr)) if sr and sr != SR else n
    except (KeyError, TypeError, ValueError):
        pass
    duration = float(a.get("duration") or d.get("format", {}).get("duration") or 0)
    return int(round(duration * SR))


def bext_time_reference(path):
    """Return TimeReference from the bext chunk in samples, or None."""
    return probe_remember("bext", path, lambda: _bext_time_reference(path))


def _bext_time_reference(path):
    try:
        f = open(path, "rb")
    except OSError:
        return None
    with f:
        if f.read(4) not in (b"RIFF", b"RF64"):
            return None
        f.seek(12)
        while True:
            h = f.read(8)
            if len(h) < 8:
                return None
            cid, sz = h[:4], struct.unpack("<I", h[4:8])[0]
            if cid == b"bext":
                b = f.read(sz)
                return struct.unpack("<Q", b[338:346])[0] if len(b) >= 346 else None
            f.seek(sz + (sz & 1), os.SEEK_CUR)


def file_timecode(path, fps=30.0):
    """Return the start time in seconds from bext or a timecode track."""
    tr = bext_time_reference(path)
    if tr is not None:
        return tr / float(SR)
    d = ffprobe_json(path)
    for source in [d.get("format", {}).get("tags", {})] +\
                  [s.get("tags", {}) or {} for s in d.get("streams", [])]:
        if source.get("timecode"):
            try:
                return parse_timecode(source["timecode"], fps)
            except Exception:
                pass
    return None


#------------------------------------------------------------ Processing

AUPHONIC = "https://auphonic.com"


def api_key_from_anywhere(args):
    """Return the API key.

    Checked in order: the command line argument, the environment, the OS
    credential store.
    """
    key = (args.auphonic_key or os.environ.get("AUPHONIC_TOKEN")
           or load_api_key())
    if not key:
        raise RuntimeError(T('No API key. Pass --auphonic-api-key KEY, set '
                             'AUPHONIC_TOKEN or have it remembered once in '
                             'the interface. The key is in the Auphonic '
                             'account settings.'))
    return key.strip()


def _curl_call(key, arguments, output_binary=False, progress=False):
    """Run curl with the key in a config file rather than in argv.

    In argv the key would be visible in the process list for the duration
    of the call.
    """
    fd, conf = tempfile.mkstemp(prefix="auph_", suffix=".conf")
    os.close(fd)
    leftovers = []
    closing, running = [], []
    try:
        # The one file that holds the key in plain text, and it is gone
        # again in the finally below whatever happened. mkstemp creates it
        # readable by its owner alone; the chmod says so again for the
        # reader. On Windows it only toggles the read-only bit, and the
        # protection there comes from the temporary directory.
        os.chmod(conf, 0o600)
        # curl reads this file as configuration, so the key goes in as a
        # value and not as more configuration: a quotation mark or a line
        # break inside it would otherwise start a directive of its own.
        # curl's own escaping inside a quoted value is a backslash.
        safe = (str(key).replace("\\", "\\\\").replace('"', '\\"')
                .replace("\r", "").replace("\n", ""))
        with open(conf, "w", encoding="utf-8") as f:
            f.write('header = "Authorization: bearer %s"\n' % safe)
        if progress:
            # The built-in curl bar has no percentage and cannot be indented.
            # The plain progress table is read instead and the usual bar drawn
            # from it.
            # The answer goes into a file, not into a pipe. The progress is
            # read from stderr until it ends; an unread stdout pipe would
            # fill up and curl would stop in the middle of the transfer.
            fd, body = tempfile.mkstemp(prefix="auph_", suffix=".out")
            os.close(fd)
            leftovers.append(body)
            answer_file = open(body, "wb")
            closing.append(answer_file)
            proc = subprocess.Popen(["curl", "-S", "-L", "--config", conf]
                                    + arguments,
                                    stdout=answer_file,
                                    stderr=subprocess.PIPE)
            running.append(proc)
            text = progress if isinstance(progress, str) else T('Transfer')
            rest, last_percent, last_time = "", -1, 0.0
            said = []            # everything that is not a progress line
            show_progress(text, 0.0)
            while True:
                piece = proc.stderr.read(64)
                if not piece:
                    break
                rest += piece.decode("utf-8", "replace")
                parts = re.split(r"[\r\n]", rest)
                rest = parts.pop()
                for line in parts:
                    m = re.match(r"\s*(\d{1,3})\s+\S+\s+\d", line)
                    if not m:
                        # curl -S says here why it gave up.
                        if line.strip():
                            said.append(line.strip())
                        continue
                    pct = min(100, int(m.group(1)))
                    now = time.time()
                    if pct != last_percent and now - last_time > 0.2:
                        show_progress(text, pct / 100.0)
                        last_percent, last_time = pct, now
            proc.wait()
            answer_file.close()
            with open(body, "rb") as fh:
                off = fh.read()
            try:
                os.unlink(body)
            except OSError:
                pass
            show_progress(text, 1.0)
            if OUTPUT_SINK:
                OUTPUT_SINK("\n")
            else:
                sys.stdout.write("\n")
            if rest.strip():
                said.append(rest.strip())
            p = subprocess.CompletedProcess(
                proc.args, proc.returncode, off,
                "\n".join(said[-20:]).encode("utf-8", "replace"))
        else:
            p = subprocess.run(["curl", "-sS", "-L", "--config", conf] + arguments,
                               capture_output=True)
    finally:
        # A transfer that was broken off leaves curl writing into a file
        # nobody reads any more. It is stopped here, or it would go on
        # downloading gigabytes for a call that has already failed.
        for child in running:
            if child.poll() is None:
                try:
                    child.kill()
                    child.wait(timeout=5)
                except Exception:
                    pass
        for handle in closing:
            try:
                handle.close()
            except Exception:
                pass
        # The config file holds the key, so it goes whatever happened --
        # and a failure to remove it must not replace the real error.
        # Where it cannot be removed it is overwritten first: a file that
        # stays behind should at least not still hold the key.
        for path in [conf] + leftovers:
            try:
                os.unlink(path)
            except OSError:
                try:
                    with open(path, "w", encoding="utf-8") as f:
                        f.write("\n")
                except OSError:
                    pass
    if p.returncode:
        error = (p.stderr or b"").decode("utf-8", "replace")[-800:]
        raise RuntimeError(error or T('curl ended with %d') % p.returncode)
    return p.stdout if output_binary else p.stdout.decode("utf-8", "replace")


def _parse_json(text):
    try:
        return json.loads(text)
    except ValueError:
        raise RuntimeError(T('Response was not JSON: %s') % text[:300])


def key_complaint(key):
    """What is wrong with this key before it is sent, or "".

    Only what can be told without asking anybody: whether there is one
    at all, and whether it looks like something that was pasted wrong.
    How long a real key is and which characters it uses is not written
    down here -- it has never been measured, and a guessed format would
    turn away a key that works. Whether a key is good is a question
    only auphonic.com can answer, and it is asked once, when somebody
    opens the preset list.
    """
    if not key:
        return T('There is no key.')
    if key != key.strip():
        return T('The key has a space or a line break at one end.')
    if any(c.isspace() for c in key):
        return T('The key is broken in the middle by a space or a line break.')
    if any(ord(c) < 32 or ord(c) == 127 for c in key):
        return T('The key has a character in it that cannot be typed.')
    return ""


def list_presets(key):
    """Fetch the stored presets."""
    d = _parse_json(_curl_call(key, [AUPHONIC + "/api/presets.json?limit=100"]))
    if d.get("status_code") not in (200, None):
        raise RuntimeError(T('Auphonic reports %s: %s')
                           % (d.get("status_code"), d.get("error_message")))
    items = []
    for p in (d.get("data") or []):
        items.append((p.get("preset_name") or p.get("name") or T('unnamed'),
                      p.get("uuid") or "",
                      bool(p.get("is_multitrack"))))
    return items


def presets_for_mode(key, multitrack):
    """Return only the presets that match the mode.

    A multitrack preset in a plain production (or the other way round)
    produces a production Auphonic refuses to start, so mismatched presets
    are never offered.
    """
    return [(n, u, m) for n, u, m in list_presets(key) if m == multitrack]


def print_presets(key, multitrack=False):
    items = presets_for_mode(key, multitrack)
    if not items:
        print(T('No %s preset found in the account.')
              % (T('multitrack') if multitrack else T('ordinary')))
        return 0
    print("Presets:")
    for i, (name, _, _) in enumerate(items, 1):
        print("  %2d  %s" % (i, name))
    return 0


def choose_preset(key, wanted, multitrack=False, lufs=None,
                   anyway=False):
    """Resolve a preset name to its UUID, asking if there is a choice.

    Both entry paths run through here, so this is where the preset is
    checked against the run. A mismatch raises before anything is uploaded.
    """
    items = presets_for_mode(key, multitrack)
    if not items:
        every = list_presets(key)
        if every:
            raise RuntimeError(
                T('No %s preset in the account. Only these: %s')
                % (T('multitrack') if multitrack else T('ordinary'),
                   ", ".join(n for n, _, _ in every)))
        raise RuntimeError(T('No presets stored in the account. One can be '
                             'created in the web interface.'))
    def done(uuid, name):
        if lufs is not None:
            findings = check_preset(key, uuid or name, name, lufs, multitrack)
            if report_findings(findings, T('does the preset fit the run?'),
                              anyway):
                raise RuntimeError(T('preset does not fit the run'))
        return uuid or name, name

    if wanted:
        for name, uuid, _ in items:
            if wanted.lower() in (name.lower(), uuid.lower()):
                return done(uuid, name)
        for name, uuid, m in list_presets(key):
            if wanted.lower() in (name.lower(), uuid.lower()):
                raise RuntimeError(
                    T('%r: %s preset, but %s is needed.')
                    % (name, T('multitrack') if m else T('ordinary'),
                       T('multitrack') if multitrack else T('an ordinary one')))
        print(T('No preset is called %r.') % wanted)
    print(T('Which Auphonic preset should process this file?'))
    for i, (name, uuid, _) in enumerate(items, 1):
        print("  %2d  %s" % (i, name))
    if not sys.stdin.isatty():
        raise RuntimeError(T('No preset given, no input possible. Choose '
                             'one of the above with --auphonic-preset NAME.'))
    while True:
        answer = input(T('  Number (empty = cancel): ')).strip()
        if not answer:
            raise RuntimeError(T('cancelled'))
        if answer.isdigit() and 1 <= int(answer) <= len(items):
            name, uuid, _ = items[int(answer) - 1]
            return done(uuid, name)
        print(T('  Please give a number between 1 and %d.') % len(items))


# What auphonic.com delivers once speech recognition has run: a
# machine readable transcript with times, a subtitle file, and one for
# reading. All three, because they cost nothing beyond the recognition.
TRANSCRIPT_OUTPUTS = ({"format": "speech", "ending": "json"},
                      {"format": "subtitle", "ending": "srt"},
                      {"format": "transcript", "ending": "txt"})

# Output files with these endings are text about the audio, not audio.
TRANSCRIPT_SUFFIXES = (".json", ".srt", ".vtt", ".txt", ".html", ".xml")

# What may be sent back when a production is updated. The answer to a
# query carries more than that -- size, checksum, download address --
# and sending those back would be describing a file that does not exist
# yet.
OUTPUT_FILE_KEYS = ("format", "ending", "bitrate", "mono_mixdown",
                    "split_on_chapters", "suffix", "filename",
                    "outgoing_services")


# The audio track tag and the recognition language are two different
# code systems. ffmpeg wants three letters after ISO 639-2/B, "ger" for
# German; auphonic.com wants the two letter code, "de". Only the ones
# that could plausibly be spoken into this program are listed -- for
# anything else the language stays empty and Whisper works it out from
# the audio.
SPEECH_CODES = {
    "ger": "de", "deu": "de", "eng": "en", "fra": "fr", "fre": "fr",
    "spa": "es", "ita": "it", "nld": "nl", "dut": "nl", "por": "pt",
    "pol": "pl", "rus": "ru", "swe": "sv", "dan": "da", "nor": "no",
    "fin": "fi", "ces": "cs", "cze": "cs", "tur": "tr", "ell": "el",
    "gre": "el", "jpn": "ja", "zho": "zh", "chi": "zh", "kor": "ko",
    "ara": "ar", "heb": "he", "hun": "hu", "ron": "ro", "rum": "ro",
    "ukr": "uk", "cat": "ca",
}


# What the interface offers. The tag is what ffmpeg wants on the audio
# track, three letters after ISO 639-2/B; speech_language_code turns it
# into the two letter code auphonic.com wants. Only languages with both
# are listed -- offering one whose recognition code is unknown would
# promise something the transcript cannot keep.
SPOKEN_LANGUAGES = (
    ("ger", "German"), ("eng", "English"), ("fra", "French"),
    ("spa", "Spanish"), ("ita", "Italian"), ("nld", "Dutch"),
    ("por", "Portuguese"), ("pol", "Polish"), ("rus", "Russian"),
    ("swe", "Swedish"), ("dan", "Danish"), ("nor", "Norwegian"),
    ("fin", "Finnish"), ("ces", "Czech"), ("tur", "Turkish"),
    ("ell", "Greek"), ("hun", "Hungarian"), ("ron", "Romanian"),
    ("ukr", "Ukrainian"), ("cat", "Catalan"), ("ara", "Arabic"),
    ("heb", "Hebrew"), ("jpn", "Japanese"), ("zho", "Chinese"),
    ("kor", "Korean"),
)


def spoken_language_choices():
    """Return [(tag, name)] for the language field, by name."""
    return sorted(((tag, T(name)) for tag, name in SPOKEN_LANGUAGES),
                  key=lambda x: x[1].lower())


def language_of_system():
    """Return the track tag the system language suggests, or "".

    Only a suggestion for the empty field: the operating system does not
    know what language was spoken in a recording.
    """
    # The locale is read directly, not through known_language: that
    # one answers which language the *interface* speaks and falls back
    # to English. A Spanish system would then suggest English, and the
    # recording would be tagged wrongly.
    head = (system_locale() or "").replace("_", "-").split("-")[0]
    head = head.strip().lower()
    if len(head) != 2:
        return ""
    for tag, _name in SPOKEN_LANGUAGES:
        if SPEECH_CODES.get(tag) == head:
            return tag
    return ""


def speech_language_code(tag):
    """Turn an audio track tag into a recognition language, or "".

    Empty rather than a guess: an unknown code sent to auphonic.com
    would either be refused or, worse, quietly transcribe the wrong
    language. Empty means Whisper decides.
    """
    tag = (tag or "").strip().replace("_", "-")
    if not tag:
        return ""
    if tag.lower() in SPEECH_CODES:
        return SPEECH_CODES[tag.lower()]
    # Already a two letter code, with or without a country: de, de-DE.
    # The country keeps its capitals -- that is how the code is written
    # and how auphonic.com expects it.
    parts = tag.split("-")
    if len(parts[0]) == 2 and parts[0].isalpha():
        return "-".join([parts[0].lower()] + [x.upper() for x in parts[1:]])
    return ""


def transcript_block(language=""):
    """The block that switches speech recognition on at auphonic.com.

    Without a service uuid Auphonic uses its own Whisper, which needs no
    account with anyone else. The language may stay empty -- Whisper
    works it out from the audio -- and shownotes stay off: a summary
    written by a machine is not what a transcript is wanted for here.
    """
    block = {"shownotes": False}
    if language:
        block["language"] = language
    return block


def transcript_outputs(already=()):
    """Return the output files to add for a transcript, minus duplicates."""
    have = set()
    for f in already or ():
        have.add((f.get("format"), f.get("ending")))
    return [dict(f) for f in TRANSCRIPT_OUTPUTS
            if (f["format"], f["ending"]) not in have]


def output_file_wish(f):
    """Reduce an output file entry to what may be asked for again."""
    return {k: f[k] for k in OUTPUT_FILE_KEYS if f.get(k) is not None}


def transcript_wish(already=(), language=""):
    """What a production needs so a transcript comes back with it.

    One place decides the shape of this, and both ways of creating a
    production -- the simple one for a single track and the json one
    for multitrack -- take it from here.
    """
    return {"speech_recognition": transcript_block(language),
            "output_files": transcript_outputs(already)}


def wishes_then_start(key, uuid, transcript=False, language="",
                      stereo=False):
    """Set what the simple API cannot, then start the production.

    The simple API takes a file and a preset and nothing else. Two things
    are not in it: speech recognition, and whether the result keeps two
    channels. Both are settled here in one call, and that call starts the
    production -- a production created without "action=start" waits for
    exactly this and would otherwise sit there until the time limit.

    The production's own output files are read and sent back with the new
    ones: posting only the new list would drop the audio the preset asks
    for.
    """
    if not transcript and not stereo:
        return
    d = _parse_json(_curl_call(
        key, [AUPHONIC + "/api/production/%s.json" % uuid]))
    already = ((d.get("data") or {}).get("output_files") or [])
    wish = [output_file_wish(f) for f in already]
    request = {}
    if transcript:
        block = transcript_wish(already, language)
        wish += block.pop("output_files")
        request.update(block)
    if stereo:
        # The preset decides whether the mixdown is folded to one channel.
        # With a stereo recording that fold cannot be undone afterwards, so
        # the flag is cleared on every output the preset asks for.
        for f in wish:
            if f.get("mono_mixdown"):
                f["mono_mixdown"] = False
    request["output_files"] = wish
    request["action"] = "start"
    fd, js = tempfile.mkstemp(suffix=".json")
    os.close(fd)
    try:
        with open(js, "w", encoding="utf-8") as f:
            json.dump(request, f, ensure_ascii=False)
        answer = _parse_json(_curl_call(
            key, ["-X", "POST", "-H", "Content-Type: application/json",
                  AUPHONIC + "/api/production/%s.json" % uuid, "-d", "@" + js]))
    finally:
        os.unlink(js)
    if answer.get("status_code") not in (200, 201, None):
        raise RuntimeError(T('Auphonic will not take the settings: '
                             '%s') % (answer.get("error_message")
                                      or answer.get("form_errors")))
    if transcript:
        print(T('  Transcript requested (speech recognition at '
                'auphonic.com)'))
    if stereo:
        print(T('  Two channels requested -- the recording is stereo'))


def run_single_production(audio, preset, presetname, key, target_folder, wait_s=7200,
                  dry_run=False, title=None, transcript=False, language=""):
    """Upload a file, start the production, wait, download the result."""
    title = title or os.path.splitext(os.path.basename(audio))[0]
    size = os.path.getsize(audio) / 1e6
    stereo = kept_channels(audio) == 2
    print(as_head(T('PROCESSING AT AUPHONIC.COM:')))
    print(T('  Preset:  %s') % presetname)
    print(T('  File:    %s (%s, %s)') % (os.path.basename(audio),
                              as_data_size(size),
                              channel_text(kept_channels(audio))))
    if dry_run:
        print(T('  (measuring only: nothing uploaded)\n'))
        return None
    # With a transcript or a stereo recording the production is created but
    # not started: recognition has to be switched on and the mono fold
    # switched off, and that is a second call. Without either it starts
    # straight away.
    later = transcript or stereo
    make = ["-X", "POST", AUPHONIC + "/api/simple/productions.json",
            "-F", "preset=%s" % preset,
            "-F", "title=%s" % title,
            "-F", "input_file=@%s" % audio]
    if not later:
        make.insert(-2, "-F")
        make.insert(-2, "action=start")
    answer = _curl_call(key, make,
                   progress=T('Uploading %s') % os.path.basename(audio))
    d = _parse_json(answer)
    if d.get("status_code") not in (200, 201, None):
        raise RuntimeError(T('Auphonic reports %s: %s')
                           % (d.get("status_code"), d.get("error_message") or
                              d.get("form_errors") or answer[:300]))
    data = d.get("data") or d
    uuid = data.get("uuid")
    if not uuid:
        raise RuntimeError(T('no production id in the response: %s') % answer[:300])
    wishes_then_start(key, uuid, transcript, language, stereo)
    print(T('  Production running (%s)') % uuid)

    started = time.time()
    last, horizon = None, 150.0        # a guess: two and a half minutes,
                                       # doubling from there
    end = started + wait_s
    print(T('  Time limit: %s') % as_hms(wait_s))
    while time.time() < end:
        d = _parse_json(_curl_call(key, [AUPHONIC + "/api/production/%s.json" % uuid]))
        p = d.get("data") or {}
        status, text = p.get("status"), p.get("status_string") or "?"
        if status == 3:
            break
        if status == 2:
            sys.stdout.write("\r" + " " * 78 + "\r")
            raise RuntimeError(T('Auphonic reports an error: %s')
                               % (p.get("error_message") or text))
        for _ in range(5):
            elapsed = time.time() - started
            # An expired estimate is doubled, so the bar drops back to half
            # instead of sticking at 100 %.
            while elapsed >= horizon:
                horizon *= 2
            share = min(0.99, elapsed / horizon)
            progress_bar = "#" * int(share * 30)
            sys.stdout.write("\r  [%-30s] %3.0f %%  %s  %s        "
                             % (progress_bar, share * 100, as_hms(elapsed), text))
            sys.stdout.flush()
            if time.time() >= end:
                break
            time.sleep(1)
        last = text
    else:
        sys.stdout.write("\r" + " " * 78 + "\r")
        raise RuntimeError(T('Time limit of %s reached, production still '
                             'running. Fetch the result later by hand: '
                             '%s/engine/status/%s')
                           % (as_hms(wait_s), AUPHONIC, uuid))
    sys.stdout.write(T('\r  [%-30s] 100 %%  %s  done%s\n')
                     % ("#" * 30, as_hms(time.time() - started), " " * 20))

    files = p.get("output_files") or []
    if not files:
        raise RuntimeError(T('production finished, but no output file'))
    def rank(f):
        # Lossless before lossy, in case the preset delivers several.
        nm = (f.get("filename") or "").lower()
        return {".wav": 1, ".flac": 2, ".aiff": 3}.get(os.path.splitext(nm)[1], 9)
    best = sorted(files, key=rank)[0]
    name = best.get("filename") or (title + ".wav")
    url = best.get("download_url")
    if not url:
        raise RuntimeError(T('no download address for %s') % name)
    os.makedirs(target_folder, exist_ok=True)
    target = os.path.join(target_folder, name)
    _curl_call(key, ["-o", target, url],
          progress=T('Downloading %s') % name)
    if os.path.getsize(target) < 1000:
        raise RuntimeError(T('downloaded file is only %d bytes')
                           % os.path.getsize(target))
    print(T('  Result: %s (%s) -- stays next to the video file\n')
          % (os.path.basename(target), as_data_size(os.path.getsize(target) / 1e6)))
    fetch_text_outputs(key, files, target_folder, skip=best)
    return target


def fetch_text_outputs(key, files, target_folder, skip=None):
    """Fetch what a production wrote about the audio, not the audio.

    Transcript, subtitles, chapter marks: paid for with the production
    either way, and useless if they stay on the server.
    """
    for f in files or []:
        if f is skip:
            continue
        name = f.get("filename") or ""
        url = f.get("download_url")
        if not name or not url:
            continue
        if not name.lower().endswith(TRANSCRIPT_SUFFIXES):
            continue
        target = os.path.join(target_folder, name)
        try:
            _curl_call(key, ["-o", target, url],
                       progress=T('Downloading %s') % name)
            print(T('  Also fetched: %s') % name)
        except Exception as e:
            print(T('  %s could not be fetched: %s') % (name, e))


def size_in_mb(file_path):
    try:
        return os.path.getsize(file_path) / 1e6
    except OSError:
        return 0.0


def as_data_size(mb_value):
    """Format a byte count for reading: 542 MB, 1,024 MB, 28.9 GB."""
    if mb_value >= 1000:
        return decimal_text("%.1f GB" % (mb_value / 1000.0))
    return "%s MB" % group_text(math.ceil(mb_value))


def audio_summary(file_path):
    """Return key facts about an audio file as (label, value) pairs."""
    d = ffprobe_json(file_path)
    a = next((x for x in d.get("streams", []) if x.get("codec_type") == "audio"), {})
    if str(a.get("sample_fmt", "")).startswith("flt"):
        depth = "32 bit float"
    else:
        depth = "%s bit" % (a.get("bits_per_raw_sample")
                            or a.get("bits_per_sample") or "?")
    channels = channel_text(a.get("channels"))
    tc = file_timecode(file_path)
    return [("Format", "%s, %s, %s Hz, %s" % (a.get("codec_name", "?"), depth,
                                              a.get("sample_rate", "?"), channels)),
            (T('Length'), "%s  (%s)  --  %s"
             % (as_hms(sample_count(file_path) / float(SR)), as_data_size(size_in_mb(file_path)),
                "Timecode %s" % timecode_string(tc) if tc is not None
                else T('no timecode')))]


MOV_CONTAINERS = (b"moov", b"trak", b"mdia", b"minf", b"stbl", b"wave")


def _mov_atoms(f, end):
    """Enumerate atoms between the current offset and end.

    Yields (kind, start of payload, end of atom) per atom.
    """
    while True:
        begin = f.tell()
        if begin + 8 > end:
            return
        head = f.read(8)
        if len(head) < 8:
            return
        size = struct.unpack(">I", head[:4])[0]
        kind = head[4:8]
        if size == 1:
            raw = f.read(8)
            if len(raw) < 8:
                return
            size = struct.unpack(">Q", raw)[0]
        elif size == 0:
            size = end - begin
        if size < 8:
            return
        stop = min(end, begin + size)
        yield kind, f.tell(), stop
        f.seek(stop)


def _read_colr_atom(f, end, depth=0):
    if depth > 8:
        return None
    for kind, content, stop in _mov_atoms(f, end):
        if kind == b"colr":
            f.seek(content)
            raw = f.read(min(19, stop - content))
            if len(raw) >= 10 and raw[:4] in (b"nclc", b"nclx"):
                prim, trc, mat = struct.unpack(">HHH", raw[4:10])
                full = (bool(raw[10] & 0x80)
                        if raw[:4] == b"nclx" and len(raw) >= 11 else None)
                return prim, trc, mat, full
            continue
        if kind in MOV_CONTAINERS:
            f.seek(content)
            hit = _read_colr_atom(f, stop, depth + 1)
            if hit:
                return hit
        elif kind == b"stsd":
            # Version, flags, count, then the entries.
            f.seek(content + 8)
            for _kind2, content2, end2 in _mov_atoms(f, stop):
                # Video entry: 78 bytes of fixed header, then sub-atoms.
                if end2 - content2 <= 78:
                    continue
                f.seek(content2 + 78)
                hit = _read_colr_atom(f, end2, depth + 1)
                if hit:
                    return hit
    return None


def colour_arguments(source, extend=False):
    """Pass the source colour tags through explicitly.

    With -c:v copy ffmpeg rewrites the colr box from its own values and
    replaces anything it does not know. Apple Log (transfer 21) becomes 18,
    and Resolve no longer recognises the input colour space. Written from
    the source numbers, the result matches the input.

    With fill_gaps=True one gap some cameras leave is closed: matrix set to
    BT.2020 with primaries "unspecified" makes the primaries BT.2020 too.
    Nothing is invented -- the information is already in the file, just in
    the other field.
    """
    values = mov_colour_tags(source)
    if not values:
        return []
    prim, trc, mat, full = values
    if extend and prim == 2 and mat == MATRIX_BT2020:
        prim = PRIMARIES_BT2020
    opts = ["-color_primaries", str(prim), "-color_trc", str(trc),
          "-colorspace", str(mat)]
    if full is not None:
        opts += ["-color_range", "pc" if full else "tv"]
    return opts


def camera_metadata(file_path):
    """Read the camera's QuickTime metadata keys.

    They name the device and app used -- com.apple.quicktime.model,
    com.blackmagic-design.camera.*. Resolve reads them; without them it
    cannot tell that an iPhone recorded in Apple Log, because the colr box
    of those files reports the transfer function as unspecified.
    """
    try:
        d = ffprobe_json(file_path)
    except Exception:
        return {}
    tags = ((d or {}).get("format") or {}).get("tags") or {}
    return {k: v for k, v in tags.items() if k.startswith("com.")}


def check_camera_metadata(source, target):
    """Report whether the camera metadata keys survived the copy."""
    a, b = camera_metadata(source), camera_metadata(target)
    if not a:
        return
    missing = [k for k in a if k not in b]
    if not missing:
        print(T('  Camera data:     %d keys carried over (%s)')
              % (len(a), a.get("com.apple.quicktime.model")
                 or a.get("com.apple.quicktime.software") or "..."))
    else:
        print(as_warn(T('  Camera data:     Caution, %d of %d keys are '
                        'missing in the new file.') % (len(missing), len(a))))
        print(T('                   Resolve may then not recognise the '
                'input colour space.'))


# Atoms in the sample description that ffmpeg drops when copying but
# Resolve reads. For iPhone recordings "logs" holds the recording
# curve, e.g. "com.apple.apple-wide-gamut.apple-log", which is how
# Resolve recognises Apple Log 2. The colr box says nothing about it.
ATOMS_TO_COPY = (b"logs",)


def _atom_boxes(data, start, end):
    """Return the boxes of one MOV level.

    Yields (start, size, kind, header length) per box.
    """
    i = start
    while i + 8 <= end:
        size = struct.unpack(">I", data[i:i + 4])[0]
        kind = data[i + 4:i + 8]
        head = 8
        if size == 1:
            if i + 16 > end:
                return
            size = struct.unpack(">Q", data[i + 8:i + 16])[0]
            head = 16
        elif size == 0:
            size = end - i
        if size < head or i + size > end:
            return
        yield i, size, kind, head
        i += size


def _find_atom(data, start, end, kind):
    for i, size, a, head in _atom_boxes(data, start, end):
        if a == kind:
            return i, size, head
    return None


def _video_track_chain(data, moov_i, moov_size, moov_head):
    """Return the video trak box and the chain down to its sample entry."""
    for t_i, t_size, t_kind, t_head in _atom_boxes(data, moov_i + moov_head,
                                           moov_i + moov_size):
        if t_kind != b"trak":
            continue
        mdia = _find_atom(data, t_i + t_head, t_i + t_size, b"mdia")
        if not mdia:
            continue
        hdlr = _find_atom(data, mdia[0] + mdia[2], mdia[0] + mdia[1],
                           b"hdlr")
        # hdlr: four bytes version and flags, four reserved, then the kind
        # of track.
        if not hdlr or data[hdlr[0] + hdlr[2] + 8:
                             hdlr[0] + hdlr[2] + 12] != b"vide":
            continue
        minf = _find_atom(data, mdia[0] + mdia[2], mdia[0] + mdia[1],
                           b"minf")
        if not minf:
            continue
        stbl = _find_atom(data, minf[0] + minf[2], minf[0] + minf[1],
                           b"stbl")
        if not stbl:
            continue
        stsd = _find_atom(data, stbl[0] + stbl[2], stbl[0] + stbl[1],
                           b"stsd")
        if not stsd:
            continue
        # In stsd: four bytes version/flags, four bytes count, then entries.
        entry = next(_atom_boxes(data, stsd[0] + stsd[2] + 8,
                              stsd[0] + stsd[1]), None)
        if not entry:
            continue
        return [(moov_i, moov_head), (t_i, t_head), (mdia[0], mdia[2]),
                (minf[0], minf[2]), (stbl[0], stbl[2]), (stsd[0], stsd[2]),
                (entry[0], entry[3])]
    return None


def _top_level_boxes(file_path):
    out = []
    total = os.path.getsize(file_path)
    with open(file_path, "rb") as f:
        pos = 0
        while pos < total - 8:
            f.seek(pos)
            head = f.read(8)
            if len(head) < 8:
                break
            size, kind = struct.unpack(">I4s", head)
            if size == 1:
                size = struct.unpack(">Q", f.read(8))[0]
            elif size == 0:
                size = total - pos
            if size < 8:
                break
            out.append((kind, pos, size))
            pos += size
    return out


# A sample description atom is an identifier, not a payload. Anything
# larger is left alone, because then the assumption no longer holds.
ATOM_LIMIT = 64 * 1024


def _verify_mov_after_edit(file_path, moov_pos, moov_old_size, above_before_value, for_it):
    """Verify the file survived the edit. An empty result means it did.

    Checked against the state before: same top level boxes at the same
    offsets, moov still last and reaching the end of file, the chain down to
    the video sample entry readable again, and the intended atoms present.
    """
    try:
        total = os.path.getsize(file_path)
        above = _top_level_boxes(file_path)
        if not above:
            return T('boxes no longer readable')
        if above[-1][0] != b"moov" or above[-1][1] != moov_pos:
            return T('moov is no longer in its place')
        if above[-1][1] + above[-1][2] != total:
            return T('moov no longer ends at the end of the file')
        if [(a, i, g) for a, i, g in above[:-1]] != \
                [(a, i, g) for a, i, g in above_before_value[:-1]]:
            return T('the media data is no longer where it was')
        if above[-1][2] <= moov_old_size:
            return T('moov has not grown')
        with open(file_path, "rb") as f:
            f.seek(above[-1][1])
            moov = f.read(above[-1][2])
        chain = _video_track_chain(moov, 0, len(moov), 8)
        if not chain:
            return T('the video track can no longer be found')
        e_i, e_head = chain[-1]
        e_size = struct.unpack(">I", moov[e_i:e_i + 4])[0]
        present = {bytes(a) for _i, _g, a, _k
                in _atom_boxes(moov, e_i + e_head + 78, e_i + e_size)}
        missing = [a.decode("latin1") for a in for_it if a not in present]
        if missing:
            return T('did not arrive: %s') % ", ".join(missing)
        # Every level has to fit exactly inside its parent, otherwise some
        # size field is wrong.
        for idx in range(len(chain) - 1):
            i, head = chain[idx]
            size = struct.unpack(">I", moov[i:i + 4])[0]
            kind_i, kind_head = chain[idx + 1]
            kind_size = struct.unpack(">I", moov[kind_i:kind_i + 4])[0]
            if not (i + head <= kind_i and kind_i + kind_size <= i + size):
                return T('a box no longer fits into its parent')
    except Exception as e:
        return T('cannot be read back (%s)') % str(e)[:60]
    return ""


def copy_mov_atoms(source, target, kinds=ATOMS_TO_COPY):
    """Copy sample description atoms from the source into the new file.

    Copied byte for byte, nothing synthesised. Only possible when moov sits
    at the end of the target: growing it then moves no media data and all
    offsets stay valid.

    The result is verified afterwards. On any mismatch the old moov is put
    back byte for byte -- better without the atom than with a file nothing
    will open.

    Returns the list of atoms copied, or [] if there were none or it could
    not be done.
    """
    # Folders, missing paths and empty names occur here, and copying
    # atoms is a side step: they end it quietly rather than raise.
    for file_path in (source, target):
        if not file_path or not os.path.isfile(file_path):
            return []
    absent = []
    src_top = _top_level_boxes(source)
    src_moov = next(((p, g) for a, p, g in src_top if a == b"moov"), None)
    if not src_moov:
        return []
    with open(source, "rb") as f:
        f.seek(src_moov[0])
        src = f.read(src_moov[1])
    chain = _video_track_chain(src, 0, len(src), 8)
    if not chain:
        return []
    e_i, e_head = chain[-1]
    e_size = struct.unpack(">I", src[e_i:e_i + 4])[0]
    src_kind = bytes(src[e_i + 4:e_i + 8])       # hvc1, avc1, apcn ...
    existing = {}
    # The sub-atoms sit behind the box header and 78 bytes of fixed
    # fields of the video entry.
    for i, size, kind, head in _atom_boxes(src, e_i + e_head + 78,
                                   e_i + e_size):
        if kind not in kinds:
            continue
        if size > ATOM_LIMIT:
            print(T('  Atom %s skipped: %d bytes are too much for it.')
                  % (kind.decode("latin1"), size))
            continue
        existing[kind] = src[i:i + size]
    if not existing:
        return []

    dst_top = _top_level_boxes(target)
    if not dst_top or dst_top[-1][0] != b"moov":
        print(T('  Cannot add atoms: moov is not at the end.'))
        return []
    dst_pos, dst_size = dst_top[-1][1], dst_top[-1][2]
    with open(target, "rb") as f:
        f.seek(dst_pos)
        dst = bytearray(f.read(dst_size))
    if len(dst) != dst_size:
        return []
    # The old moov stays in place: if the verification fails, it comes
    # back exactly as it was.
    old_moov = bytes(dst)
    chain = _video_track_chain(dst, 0, len(dst), 8)
    if not chain:
        return []
    e_i, e_head = chain[-1]
    e_size = struct.unpack(">I", dst[e_i:e_i + 4])[0]
    dst_kind = bytes(dst[e_i + 4:e_i + 8])
    if dst_kind != src_kind:
        # An atom from an HEVC description does not belong in an H.264 one.
        # The boxes fit, the contents do not.
        print(T('  Cannot add atoms: the source is %s, the target %s.') % (src_kind.decode("latin1", "replace"),
                       dst_kind.decode("latin1", "replace")))
        return []
    already = {bytes(kind) for _i, _g, kind, _k
             in _atom_boxes(dst, e_i + e_head + 78, e_i + e_size)}
    fresh = b"".join(v for k, v in existing.items() if k not in already)
    if not fresh:
        return []
    # Every box enclosing the entry grows.
    for i, _head in chain:
        size = struct.unpack(">I", dst[i:i + 4])[0]
        if size == 1:
            print(T('  Cannot add atoms: a 64 bit box is in the way.'))
            return []
        struct.pack_into(">I", dst, i, size + len(fresh))
    insert = e_i + e_size

    def moov_write(content):
        with open(target, "r+b") as f:
            f.seek(dst_pos)
            f.write(content)
            f.truncate(dst_pos + len(content))
            f.flush()
            os.fsync(f.fileno())

    for_it = [k for k in existing if k not in already]
    try:
        moov_write(bytes(dst[:insert]) + fresh + bytes(dst[insert:]))
        damage = _verify_mov_after_edit(target, dst_pos, dst_size, dst_top, for_it)
    except Exception as e:
        damage = T('while writing: %s') % str(e)[:60]
    if damage:
        try:
            moov_write(old_moov)
            back = T('the old moov is back in place')
        except Exception as e:
            back = T('ROLLBACK FAILED (%s)') % str(e)[:60]
        print(T('  Adding atoms taken back -- %s. %s')
              % (damage, back))
        return []
    return [k.decode("latin1") for k in for_it]


def _logs_atom_text(file_path):
    """Return the text of the video track logs atom, or ""."""
    try:
        above = _top_level_boxes(file_path)
        spot = next(((p, g) for a, p, g in above if a == b"moov"), None)
        if not spot:
            return ""
        with open(file_path, "rb") as f:
            f.seek(spot[0])
            moov = f.read(spot[1])
        chain = _video_track_chain(moov, 0, len(moov), 8)
        if not chain:
            return ""
        e_i, e_head = chain[-1]
        e_size = struct.unpack(">I", moov[e_i:e_i + 4])[0]
        for i, size, kind, head in _atom_boxes(moov, e_i + e_head + 78, e_i + e_size):
            if kind == b"logs":
                return moov[i + head:i + size].decode("latin1", "replace")
    except Exception:
        pass
    return ""


def log_curve_from_atom(text):
    """Return the recording curve named by the logs atom.

    The atom holds a reverse domain name such as
    "com.apple.apple-wide-gamut.apple-log". Known identifiers get a plain
    name, anything else is shown verbatim. Nothing is guessed: an unknown
    identifier is information, an invented name would not be.
    """
    raw = (text or "").replace("\x00", " ").strip()
    if not raw:
        return ""
    t = raw.lower()
    # Longer identifier first, or "apple-log" swallows the two.
    for piece, name in (("apple-log-2", "Apple Log 2"),
                         ("apple-log2", "Apple Log 2"),
                         ("applelog2", "Apple Log 2"),
                         ("apple-log", "Apple Log"),
                         ("applelog", "Apple Log")):
        if piece in t:
            return name
    return raw


def check_colour_survived(source, target, extend=False):
    """Report whether the written file carries the intended colour tags.

    Compared against the intended values, not against the source: missing
    primaries are filled in from the matrix, so the box is meant to differ.
    """
    a, b = mov_colour_tags(source), mov_colour_tags(target)
    if a is None and b is None:
        return
    want = a
    if a and extend and a[0] == 2 and a[2] == MATRIX_BT2020:
        want = (PRIMARIES_BT2020,) + tuple(a[1:])
    if b == want and want != a:
        print(T('  Colour:          %d/%d/%d -- primaries filled in from '
                'the matrix (source: %d)') % (want[0], want[1], want[2], a[0]))
        return
    if a == b:
        print(T('  Colour:          %d/%d/%d carried over') % a[:3])
        return
    print(as_warn(T('  Colour:          Caution, %s in the source, %s in '
                    'the new file') % (a[:3] if a else T('nothing'), b[:3] if b else T('nothing'))))
    print(T('                   Resolve may then not recognise the input '
            'colour space.'))


def mov_colour_tags(file_path):
    """Read the colr box of a MOV file.

    Returns (primaries, transfer, matrix, full range) or None.

    ffprobe is not used because it reports names rather than numbers, and
    names a wrong one for values it does not know -- Apple Log among them.
    The box itself does not lie.

    Only the atom tree is walked, so a 30 GB recording is skipped over
    rather than read.
    """
    try:
        size = os.path.getsize(file_path)
        with open(file_path, "rb") as f:
            return _read_colr_atom(f, size)
    except (OSError, struct.error):
        return None


def video_summary(file_path, info):
    v = info["video"]
    tags = info.get("tags") or {}
    # The nominal rate comes first: editors use it. The measured one
    # beside it where it differs -- frame count over track duration, so a
    # property of the container.
    label_text, measured = info.get("nominal") or info["fps"], info["fps"]
    lines = [("Video", "%s, %sx%s, %s fps%s"
               % (v.get("codec_name", "?"), v.get("width"), v.get("height"),
                  decimal_text("%.3f" % label_text),
                  "" if abs(measured - label_text) < 0.0005
                  else T('  (container; measured %s)')
                  % decimal_text("%.4f" % measured))),
              (T('Length'), "%s  (%s)  --  %s"
               % (as_hms(info["duration"]), as_data_size(size_in_mb(file_path)),
                  "Timecode %s" % info["tc"] if info["tc"]
                  else T('no timecode'))),
              (T('Colour'), colour_text(file_path, v, tags)),
              (T('Camera'), camera_text(tags))]
    if info["audio"]:
        a = info["audio"][0]
        channels = channel_text(a.get("channels"))
        count = len(info["audio"])
        lines.append((T('Camera audio'),
                      TN(count, '%d track, %s, %s Hz, %s',
                         '%d tracks, %s, %s Hz, %s')
                      % (count, a.get("codec_name", "?"),
                         a.get("sample_rate", "?"), channels)))
    else:
        lines.append((T('Camera audio'), T('no audio track present')))
    return lines


def print_key_values(lines, indent="  "):
    # The column follows the longest label, so it holds in every language.
    width = max([len(k) for k, _ in lines] or [9]) + 1
    for k, value in lines:
        print("%s%-*s %s" % (indent, width, k + ":", value))


def print_audio_details(file_path, indent="  "):
    print_key_values(audio_summary(file_path), indent)


def print_video_details(file_path, info, indent="  "):
    print_key_values(video_summary(file_path, info), indent)


def open_in_file_manager(file_path):
    """Show a folder in Finder, Explorer or the desktop file manager."""
    folder = file_path if os.path.isdir(file_path) else os.path.dirname(file_path)
    try:
        if sys.platform == "darwin":
            if os.path.isdir(file_path):
                subprocess.Popen(["open", folder])
            else:
                subprocess.Popen(["open", "-R", file_path])
        elif os.name == "nt":
            if os.path.isdir(file_path):
                os.startfile(folder)
            else:
                # The switch and the path have to be one single argument,
                # otherwise Explorer opens the documents folder.
                subprocess.Popen('explorer /select,"%s"'
                                 % os.path.normpath(file_path))
        else:
            subprocess.Popen(["xdg-open", folder])
        return True
    except Exception:
        return False


def report_timecode_check(audio_start, info, measured, indent="  "):
    """Compare what the timecode says with what can be heard."""
    if audio_start is None or not info["tc"]:
        return
    fps = max(1.0, info["fps"])
    loud_tc = parse_timecode(info["tc"], fps) - audio_start
    deviation = measured - loud_tc
    print(T('%sTimecode check of the audio file') % indent)
    if not GUI_RUNNING:
        print(T('%s  Audio starts per timecode at    %s')
              % (indent, timecode_string(audio_start, fps)))
        print(T('%s  Picture starts per timecode at  %s')
              % (indent, timecode_string(parse_timecode(info["tc"], fps), fps)))
    print(T('%s  Offset per timecode:            %s') % (indent, as_hms(loud_tc)))
    print(T('%s  Offset measured:                %s') % (indent, as_hms(measured)))
    if abs(deviation) > 60:
        print(T('%s  Deviation:                      %s') % (indent, as_hms(deviation)))
        print(T('%s  The audio timecode does not fit the picture at all -- '
                'probably a clock never set. The measurement is used.')
              % indent)
    elif abs(deviation) > 0.5 / fps:
        print(T('%s  Deviation:                      %s  (%.1f frames)')
              % (indent, as_hms(deviation), abs(deviation) * fps))
        print(T('%s  The timecode does not fit what is heard. The '
                'measurement is used.') % indent)
    else:
        print(T('%s  Deviation:                      %s  (%.1f frames) -- fits')
              % (indent, as_hms(deviation), abs(deviation) * fps))


#---------------------------------------------------------- Collecting files

# Date and time in a file name: "r_260808_185628" is the eighth of August
# 2026 at 18:56:28. Six digits for the date or eight, six for the time.
NAME_CLOCK = re.compile(r"(?<![0-9])([0-9]{6}|[0-9]{8})[_\-. ]([0-9]{6})"
                        r"(?![0-9])")
# How far the clock in the name may sit from where the previous block ends.
# Recorders write whole seconds, and the length of a block is rarely a
# whole one, so two seconds of slack are needed -- and two blocks that
# really follow one another are never further apart than that.
CLOCK_SLACK = 2.0
# What a track cut out of a multichannel file is called at the end. The
# search for continuation blocks has to leave those alone: the number in
# them is a channel, not a block.
SPLIT_MARK = re.compile(r"_Channel\d+(?:\+\d+)?$")


def clock_in_name(name):
    """Return the moment a file name carries: (seconds, before, after).

    Recorders that number their files leave a counter behind, and the
    search for continuations steps it by one. Mixers often write the date
    and the time of day instead. That is not a counter -- 185628 and
    185629 are two different seconds, not two blocks -- so it has to be
    read as a clock and held against the length of the block before it.

    *before* and *after* are the rest of the name, so only files built the
    same way are compared with each other. Returns None where there is no
    clock in the name.
    """
    m = NAME_CLOCK.search(name)
    if not m:
        return None
    day, clock = m.group(1), m.group(2)
    shape = "%y%m%d" if len(day) == 6 else "%Y%m%d"
    try:
        when = datetime.datetime.strptime(day + clock, shape + "%H%M%S")
    except ValueError:
        return None
    # Naive on purpose: both names come from the same recorder and the
    # same evening, and only their difference is used.
    return (when.replace(tzinfo=datetime.timezone.utc).timestamp(),
            name[:m.start()], name[m.end():])


def blocks_by_clock(file_path):
    """Find the blocks of one recording by the clock in their names.

    Only files built exactly the same way count: same folder, same
    extension, the same text before and after the clock. Of those, the
    one whose clock sits where the previous block ends is the
    continuation -- measured, not guessed, and the same test in both
    directions.
    """
    folder = os.path.dirname(file_path) or "."
    name, ext = os.path.splitext(os.path.basename(file_path))
    mine = clock_in_name(name)
    if not mine:
        return [file_path], []
    when, before, after = mine
    family = {}
    try:
        every = os.listdir(folder)
    except OSError:
        return [file_path], []
    doubled, both = set(), {}
    for f in sorted(every):
        stem, kind = os.path.splitext(f)
        if kind.lower() != ext.lower():
            continue
        other = clock_in_name(stem)
        if not other or other[1] != before or other[2] != after:
            continue
        if other[0] in family:
            # Two files claiming the same moment -- "260808" and
            # "20260808" spell the same day. Which one is meant cannot be
            # decided here, so neither is taken.
            doubled.add(other[0])
            both.setdefault(other[0],
                            [os.path.basename(family[other[0]])]).append(f)
            continue
        family[other[0]] = os.path.join(folder, f)
    said = []
    for moment in doubled:
        family.pop(moment, None)
        for name in both.get(moment, []):
            said.append((name, T('two file names for the same moment -- '
                                 'neither of them is taken')))
    if len(family) < 2 or when not in family:
        return [file_path], said
    row, discarded = [file_path], list(said)

    def follows(a, b):
        """Does the block at moment b start where the one at a ends?"""
        fits, _why = shapes_match(family[a], family[b])
        if not fits:
            return False
        length = sample_count(family[a]) / float(SR)
        return abs((a + length) - b) <= CLOCK_SLACK

    times = sorted(family)
    here = when
    while True:                                   # forwards
        later = [t for t in times if t > here]
        if not later:
            break
        step = later[0]
        if not follows(here, step):
            fits, why = shapes_match(family[here], family[step])
            discarded.append((os.path.basename(family[step]),
                              why if not fits else
                              T('does not start where the block before it '
                                'ends')))
            break
        row.append(family[step])
        here = step
    here = when
    while True:                                   # backwards
        earlier = [t for t in times if t < here]
        if not earlier:
            break
        step = earlier[-1]
        if not follows(step, here):
            fits, why = shapes_match(family[step], family[here])
            discarded.append((os.path.basename(family[step]),
                              why if not fits else
                              T('ends before the next block starts')))
            break
        row.insert(0, family[step])
        here = step
    return row, discarded


def _joins_seamlessly(before, after, row):
    """Report whether `after` continues `before` seamlessly.

    Returns (yes, reason). With timecode: the next block starts where the
    previous one ends. Without timecode only the block size is left -- a
    block short of full size is an end of recording, followed by a pause of
    unknown length.
    """
    fits, why = shapes_match(before, after)
    if not fits:
        return False, why
    t_before, t_after = file_timecode(before), file_timecode(after)
    if t_before is not None and t_after is not None:
        gap = t_after - (t_before + sample_count(before) / float(SR))
        # With timecode a pause is no problem: it is known and filled with
        # silence on assembly. Only an overlap would mean the blocks do not
        # belong together.
        return gap > -1.0, (T('overlap of %s per timecode')
                               % as_hms(abs(gap)))
    # The candidate belongs in the comparison, or the very first step
    # compares a block with itself and always says yes: a finished short
    # take before the real recording would be glued on.
    sizes = [os.path.getsize(p) for p in row]
    sizes += [os.path.getsize(before), os.path.getsize(after)]
    return (os.path.getsize(before) >= 0.98 * max(sizes),
            T('previous block is shorter than the rest'))


def find_continuation_files(file_path):
    """Find every block of the same recording, forwards and backwards.

    Only seamless continuations are appended, and the same test applies in
    both directions: an earlier take with the same naming pattern either has
    a timecode that does not fit or falls short of the full block size. So
    it makes no difference whether the first block or a middle one is
    picked.
    """
    folder = os.path.dirname(file_path) or "."
    name, ext = os.path.splitext(os.path.basename(file_path))
    # A track cut out of a multichannel file ends in a channel number,
    # and looking for the next number would find the next channel. Those
    # are not blocks of one recording, they are different microphones.
    if SPLIT_MARK.search(name):
        return [file_path], []
    # A clock in the name is the more specific reading and comes first:
    # where it is there, the trailing digits are a time of day and
    # stepping them by one would look for a file a second later.
    by_clock = None
    if clock_in_name(name):
        row, discarded = blocks_by_clock(file_path)
        if len(row) > 1:
            return row, discarded
        # Nothing joined by the clock. It may be the session start,
        # written into every block, with the real index in a counter
        # behind it -- "260808_000001" is such a name, and reading the
        # counter as a time of day makes the blocks look unrelated. So
        # the counter rule gets its turn; what the clock found is kept
        # in case the counter finds nothing either.
        by_clock = (row, discarded)
    m = TRAILING_NUMBER.match(name)
    if not m:
        return by_clock or ([file_path], [])
    stem, digits = m.group(1), m.group(2)
    width = len(digits)
    row, discarded = [file_path], []
    # Exactly as they are written, and only then case-blind: on a
    # case-sensitive disc REC0002.wav and rec0002.wav are two files, and
    # folding them into one key would put whichever came last into the
    # recording -- a different answer depending on the folder listing.
    every = os.listdir(folder)
    exact = {f: f for f in every}
    loosely = {}
    for f in every:
        loosely.setdefault(f.lower(), []).append(f)

    def neighbour(index_number):
        for b in (width, 0):
            nm = ("%s%0*d%s" % (stem, b, index_number, ext)) if b else\
                 ("%s%d%s" % (stem, index_number, ext))
            hit = exact.get(nm)
            if hit is None:
                same = loosely.get(nm.lower()) or []
                # Only where there is no doubt which file was meant.
                hit = same[0] if len(same) == 1 else None
            if hit:
                return os.path.join(folder, hit)
        return None

    index_number = int(digits)
    while True:                                   # forwards
        index_number += 1
        candidate = neighbour(index_number)
        if not candidate:
            break
        matches, reason = _joins_seamlessly(row[-1], candidate, row)
        if not matches:
            discarded.append((os.path.basename(candidate), reason))
            break
        row.append(candidate)

    index_number = int(digits)
    while index_number > 0:                             # backwards
        index_number -= 1
        candidate = neighbour(index_number)
        if not candidate:
            break
        matches, reason = _joins_seamlessly(candidate, row[0], row)
        if not matches:
            discarded.append((os.path.basename(candidate), reason))
            break
        row.insert(0, candidate)
    if len(row) == 1 and by_clock and by_clock[1]:
        # The counter found nothing either; then what the clock had to
        # say about the neighbours is the better answer.
        return by_clock
    return row, discarded


def track_order_for_camera(own, every):
    """Return the audio tracks for one camera, in order.

    Track 1 is always the finished mix of what belongs to this camera, so
    taking only the first track is correct without further work. Then the
    same speakers again individually, so each can be reached in the edit.
    Then the overall mix -- what the camera microphone would have heard,
    minus the crosstalk. Last the camera microphone itself.
    """
    sequence = []
    if own:
        sequence.append('Mix %s' % " + ".join(own)
                     if len(own) > 1 else own[0])
        if len(own) > 1:
            sequence += list(own)
    else:
        sequence.append("Full-Mix (%s)" % " + ".join(every))
    if every and own and set(own) != set(every):
        sequence.append("Full-Mix (%s)" % " + ".join(every))
    sequence.append("Camera Original")
    return sequence


# What must not go from a preset into a production: identifiers,
# times, states. Everything else is adopted, including fields
# Auphonic adds later, so nothing has to be maintained here.
PRESET_READ_ONLY = (
    "uuid", "preset_name", "creation_time", "change_time", "status",
    "status_string", "error_status", "error_message", "warning_status",
    "warning_message", "image", "thumbnail", "length", "length_timestring",
    "waveform_image", "status_page", "edit_page", "start_allowed",
    "change_allowed", "in_review", "chapters", "preset", "is_multitrack")


def read_preset(key, uuid):
    """Fetch one preset in full."""
    d = _parse_json(_curl_call(key, [AUPHONIC + "/api/preset/%s.json" % uuid]))
    if d.get("status_code") not in (200, None):
        raise RuntimeError(T('Preset not readable: %s') % d.get("error_message"))
    return d.get("data") or d


def find_output_format(key, find, avoid=()):
    """Find an Auphonic output format by its name.

    The identifiers are undocumented, so they are looked up rather than
    guessed: /api/info/output_files.json lists every output format with
    its identifier and name.
    """
    try:
        d = _parse_json(_curl_call(key, [AUPHONIC + "/api/info/output_files.json"]))
    except Exception:
        return None
    kinds = d.get("data")
    if isinstance(kinds, dict):
        kinds = [dict(v, format=k) for k, v in kinds.items()
                 if isinstance(v, dict)]
    if not isinstance(kinds, list):
        kinds = []
    for a in kinds:
        if not isinstance(a, dict):
            continue
        text = " ".join(str(a.get(f) or "")
                        for f in ("format", "string", "name")).lower()
        if all(word in text for word in find) and not any(word in text
                                                      for word in avoid):
            return {"format": a.get("format"),
                    "ending": a.get("ending") or ""}
    return None


def missing_outputs(existing, wanted):
    """Return the output formats still missing from a production.

    Auphonic appends rather than replaces on update: sending a format that
    already exists leaves it in the production twice, and it is billed and
    computed twice.
    """
    def fingerprint(e):
        return (str((e or {}).get("format") or "").lower(),
                str((e or {}).get("suffix") or "").lower(),
                bool((e or {}).get("mono_mixdown")))
    present = set()
    for e in (existing or []):
        if not isinstance(e, dict):
            continue
        present.add(fingerprint(e))
        # The response carries the format but no suffix; it does carry the
        # file name, and the suffix can be read from that. Where the
        # channel count is not stated -- the key missing, or there and
        # empty -- both readings count as present: an upload sent twice
        # is computed and billed twice, and that is the worse mistake.
        # Only a stated count narrows it to one, because a mixdown of one
        # channel is no yardstick for a mix of two.
        name = str(e.get("filename") or "")
        stem = os.path.splitext(name)[0]
        kind = str(e.get("format") or "").lower()
        said = e.get("mono_mixdown")
        both = (bool(said),) if said is not None else (True, False)
        if "_" in stem:
            suffix = "_" + stem.rsplit("_", 1)[1].lower()
            for mono in both:
                present.add((kind, suffix, mono))
        elif e.get("suffix"):
            # An output that is configured but not rendered yet has no
            # file name to read a suffix from. It carries its own.
            for mono in both:
                present.add((kind, str(e["suffix"]).lower(), mono))
    absent = []
    for e in wanted:
        if fingerprint(e) in present:
            continue
        present.add(fingerprint(e))
        absent.append(e)
    return absent


def master_output_format(key, stereo=False):
    """Request the finished mixdown as well -- 24 bit WAV.

    Auphonic mixes the tracks itself and masters the result to the preset
    target level. The file is not needed as audio but as a yardstick: it
    shows how loud our own mix of the same tracks should end up. It costs no
    extra credit, since the production is computed anyway.

    One channel is enough for a yardstick and half the download -- but only
    while every track is mono. As soon as one is stereo the mixdown has two
    channels, and a yardstick measured in one channel would sit about three
    decibels off the mix it is meant to measure.
    """
    kind = (find_output_format(key, ("wav-24bit",))
           or find_output_format(key, ("wav",), avoid=("zip", "tracks")))
    if not kind or not kind.get("format"):
        return None
    entry = {"format": kind["format"], "ending": kind.get("ending") or "wav",
               "mono_mixdown": not stereo, "suffix": "_master"}
    return entry


def build_multitrack_request(preset, title, names, base_name, key=None,
                             transcript=False, language="", stereo=False):
    """Build the production request from the preset that was read.

    The preset cannot simply be sent along: Auphonic then merges its tracks
    with ours and the production stays incomplete. So the preset is read and
    its contents adopted, except for what we set ourselves. The settings of
    the first preset track apply to every track of ours, which leaves the
    track count free.
    """
    request = {k: v for k, v in preset.items() if k not in PRESET_READ_ONLY}
    template = {}
    for track in (preset.get("multi_input_files") or []):
        template = dict(track.get("algorithms") or {})
        break
    request["is_multitrack"] = True
    request["multi_input_files"] = [
        {"type": "multitrack", "id": n, "algorithms": dict(template)}
        for n in names]
    # We choose the output ourselves: the single tracks only. The mixdown
    # is built from them afterwards to match the cameras.
    request["output_files"] = [{"format": "tracks", "ending": "wav.zip"}]
    if key:
        # The finished mixdown comes along as a yardstick: it shows how loud
        # our own mix should end up.
        mst = master_output_format(key, stereo)
        if mst:
            request["output_files"].append(mst)
            print(as_good(T('  Finished mixdown requested as the yardstick '
                            '(%s)')
                          % mst["format"]))
            if stereo:
                print(T('  Two channels, because one track is stereo'))
    if transcript:
        # Multitrack has the advantage that the transcript carries the
        # speaker names: each track is one person, and Auphonic knows
        # which is which.
        wish = transcript_wish(request["output_files"], language)
        request["output_files"] += wish.pop("output_files")
        request.update(wish)
        print(T('  Transcript requested (speech recognition at '
                'auphonic.com)'))
    request["metadata"] = dict(preset.get("metadata") or {})
    request["metadata"]["title"] = title
    request["output_basename"] = base_name
    return request


def find_production_by_title(key, title):
    """Return the Auphonic production with this title, or None."""
    d = _parse_json(_curl_call(key, [AUPHONIC + "/api/productions.json?limit=50"]))
    wanted_name = (title or "").strip().lower()
    for p in (d.get("data") or []):
        if ((p.get("metadata") or {}).get("title") or "").strip().lower()\
                == wanted_name:
            return p
    return None


def print_production(p):
    """Print what a production already contains."""
    tracks = p.get("multi_input_files") or []
    uploaded = [(x.get("id"), x.get("input_file")) for x in tracks]
    done = [f.get("filename") for f in (p.get("output_files") or [])
              if f.get("download_url")]
    print("  Status:      %s" % (p.get("status_string") or "?"))
    print(T('  Created:     %s') % (p.get("creation_time") or "?")[:19].replace(
        "T", " "))
    if uploaded:
        print(T('  Uploaded:'))
        for fingerprint, file in uploaded:
            print("    %-20s %s" % (fingerprint, file or T('-- nothing --')))
    if done:
        print(T('  Results:'))
        for n in done:
            small = (n or "").lower()
            if small.endswith(".zip"):
                what = T('the individual tracks, packed')
            elif small.endswith(".wav"):
                what = T('the finished mixdown')
            else:
                what = ""
            print("    %-46s %s" % (n, what))
    else:
        print(T('  Results:     none'))
    # Without the tracks nothing works, without the mixdown the loudness
    # has no yardstick. Left unsaid, a missing one turns "reuse" into a
    # dead end.
    small = [(n or "").lower() for n in done]
    has_zip = any(n.endswith(".zip") for n in small)
    has_master = any(n.endswith(".wav") for n in small)
    missing = []
    if not has_zip:
        missing.append(T('the individual tracks'))
    if not has_master:
        missing.append(T('the mixdown as the yardstick'))
    if missing:
        # Always the production at auphonic.com, not the local disk --
        # everything is downloaded again anyway.
        print(T('  Missing:     %s') % ", ".join(missing))
    return all(d for _, d in uploaded) and bool(uploaded), has_zip, missing


def update_production(key, uuid, request):
    """Bring an existing production's settings up to the preset.

    Uploaded files stay in place: Auphonic matches tracks by identifier and
    that does not change. Presets can therefore be tried out without
    uploading again -- only the upload costs credit, not the computation.
    """
    fd, js = tempfile.mkstemp(suffix=".json")
    os.close(fd)
    without_output = dict(request)
    try:
        with open(js, "w", encoding="utf-8") as f:
            json.dump(without_output, f, ensure_ascii=False)
        answer = _parse_json(_curl_call(key, ["-X", "POST", "-H",
                                    "Content-Type: application/json",
                                    AUPHONIC + "/api/production/%s.json" % uuid,
                                    "-d", "@" + js]))
    finally:
        os.unlink(js)
    if answer.get("status_code") not in (200, 201, None):
        raise RuntimeError(T('Change rejected: %s')
                           % (answer.get("error_message")
                              or answer.get("form_errors")))
    return answer.get("data") or {}


def read_production(key, uuid):
    """Fetch the current state of a production."""
    return (_parse_json(_curl_call(key, [AUPHONIC + "/api/production/%s.json" % uuid]))
            .get("data") or {})


def update_track(key, uuid, track_id, algorithms):
    """Change the settings of a single track.

    Auphonic only matches a track through its own URL. Sending the track
    list to the production appends instead of matching -- three tracks
    become six, the second three without a file.
    """
    fd, js = tempfile.mkstemp(suffix=".json")
    os.close(fd)
    try:
        with open(js, "w", encoding="utf-8") as f:
            json.dump({"id": track_id, "type": "multitrack",
                       "algorithms": algorithms}, f, ensure_ascii=False)
        answer = _parse_json(_curl_call(key, [
            "-X", "POST", "-H", "Content-Type: application/json",
            AUPHONIC + "/api/production/%s/multi_input_files/%s.json"
            % (uuid, track_id), "-d", "@" + js]))
    finally:
        os.unlink(js)
    if answer.get("status_code") not in (200, 201, None):
        return str(answer.get("error_message")
                   or answer.get("form_errors") or T('rejected'))
    return None


def update_all_tracks(key, uuid, wanted, existing):
    """Bring the tracks of an existing production up to the preset.

    *wanted* is the track list from our request: one identifier and the
    preset settings per track. Each track is addressed individually.
    Returns (changed, unchanged, errors).
    """
    present = dict((str(t.get("id")), t) for t in
              (existing.get("multi_input_files") or []))
    error, changed, same = [], [], []
    for entry in wanted:
        fingerprint = str(entry.get("id"))
        want = entry.get("algorithms") or {}
        old = present.get(fingerprint)
        if old is None:
            error.append(T('%s: not there') % fingerprint)
            continue
        if dict(old.get("algorithms") or {}) == dict(want):
            same.append(fingerprint)
            continue
        bad = update_track(key, uuid, fingerprint, want)
        if bad:
            error.append("%s: %s" % (fingerprint, bad))
        else:
            changed.append(fingerprint)
    return changed, same, error


def run_multitrack_production(key, preset_uuid, title, tracks, target_folder,
                        wait_s=7200, dry_run=False, carry_on=None,
                        transcript=False, language=""):
    """Create a multitrack production, upload, wait, fetch the tracks.

    Returns {speaker name: path of the processed file}.
    """
    step_begin("auphonic")
    names = [track["name"] for track in tracks]
    base = safe_filename(title)
    print(as_head(T('PROCESSING AT AUPHONIC.COM (MULTITRACK):')))
    print(T('  Production:  %s') % title)
    print(T('  Tracks:      %s') % ", ".join(names))
    total = sum(os.path.getsize(track["axis"]) for track in tracks) / 1e6
    print(T('  To upload:   %s') % as_data_size(total))
    if dry_run:
        print(T('  (measuring only: nothing uploaded)\n'))
        return {}

    preset = read_preset(key, preset_uuid)
    if not preset.get("is_multitrack"):
        raise RuntimeError(T('%r is not a Multitrack preset')
                           % preset.get("preset_name"))
    stereo = widest_track([track["axis"] for track in tracks]) == 2
    request = build_multitrack_request(preset, title, names, base, key,
                                       transcript, language, stereo)

    # --- does this production already exist?
    existing = find_production_by_title(key, title)
    if existing:
        return reuse_production(key, existing, request, preset,
                                          tracks, names, target_folder, base,
                                          wait_s, carry_on)
    fd, js = tempfile.mkstemp(suffix=".json")
    os.close(fd)
    try:
        with open(js, "w", encoding="utf-8") as f:
            json.dump(request, f, ensure_ascii=False)
        answer = _parse_json(_curl_call(key, ["-X", "POST", "-H",
                                    "Content-Type: application/json",
                                    AUPHONIC + "/api/productions.json",
                                    "-d", "@" + js]))
    finally:
        os.unlink(js)
    if answer.get("status_code") not in (200, 201, None):
        raise RuntimeError(T('Auphonic reports %s: %s')
                           % (answer.get("status_code"),
                              answer.get("error_message")
                              or answer.get("form_errors")))
    p = answer.get("data") or {}
    uuid = p.get("uuid")
    if not uuid:
        raise RuntimeError(T('no production id in the response'))
    created = [x.get("id") for x in (p.get("multi_input_files") or [])]
    if sorted(created) != sorted(names):
        raise RuntimeError(T('Auphonic created different tracks than '
                             'requested: %s instead of %s') % (created, names))
    print(T('  Production running (%s)') % uuid)

    upload_args = ["-X", "POST", AUPHONIC + "/api/production/%s/upload.json" % uuid]
    for track in tracks:
        upload_args += ["-F", "%s=@%s" % (track["name"], track["axis"])]
    d = _parse_json(_curl_call(key, upload_args, progress=T('Uploading %d tracks') % len(tracks)))
    absent = [x.get("id") for x in ((d.get("data") or {}).get(
        "multi_input_files") or []) if not x.get("input_file")]
    if absent:
        raise RuntimeError(T('These tracks got no file: %s')
                           % ", ".join(absent))

    _curl_call(key, ["-X", "POST",
                AUPHONIC + "/api/production/%s/start.json" % uuid])
    p = wait_for_production(key, uuid, wait_s)

    return download_results(key, p, names, target_folder, base)


def download_results(key, p, names, target_folder, base):
    """Download a finished production: the single tracks."""
    zip_file = None
    for f in (p.get("output_files") or []):
        if (f.get("filename") or "").lower().endswith(".zip"):
            zip_file = f
            break
    if not zip_file:
        raise RuntimeError(T('Production finished, but no ZIP with the '
                             'individual tracks'))
    cache = tracks_folder(target_folder)
    target = os.path.join(cache, zip_file.get("filename"))
    _curl_call(key, ["-o", target, zip_file.get("download_url")],
          progress=T('Downloading %s') % zip_file.get("filename"))
    # Whatever else the preset produces -- chapter marks, transcript,
    # analyses -- belongs here too. It is paid for either way.
    already = set()
    for f in (p.get("output_files") or []):
        name = f.get("filename") or ""
        if not name or not f.get("download_url") or f is zip_file:
            continue
        if name.lower() in already:
            # Two output kinds with the same file name: the second would only
            # overwrite the first. Once is enough.
            print(T('  %s is in the production twice -- fetched once.')
                  % name)
            continue
        already.add(name.lower())
        extra_file = os.path.join(cache, name)
        try:
            _curl_call(key, ["-o", extra_file, f["download_url"]],
                  progress=T('Downloading %s') % name)
        except Exception as e:
            print(T('  %s could not be fetched: %s') % (name, e))
    return match_zip_entries_to_tracks(target, names, target_folder)


def find_pauses(tracks):
    """Merge all speech blocks and return the gaps between them."""
    every = sorted((a, b) for _, segs in tracks for a, b in segs)
    merged = []
    for a, b in every:
        if merged and a <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], b)
        else:
            merged.append([a, b])
    pauses = [(merged[i][1], merged[i + 1][0])
              for i in range(len(merged) - 1)]
    entries_in = {n: sorted(a for a, _ in segs) for n, segs in tracks}
    return pauses, entries_in


# =====================================================================
#  What the cut is decided by
#  --------------------------
#  On top of "whoever speaks is on screen" sit the rules a human
#  editor follows. Every number below was measured against a hand-made
#  edit of the same material, and every one of them is adjustable.
# =====================================================================

# A speaker has to hold the floor this long before the camera follows.
# Half a second of "yes" used to draw the camera over, and the minimum
# edit duration then held it on the wrong person for seconds.
MIN_SPEECH_TO_SWITCH_S = 1.5

# A label that is not a person: its segments average shorter than this
# and it holds less than this share of the recognised speech. Over six
# recordings that found 5 of 5 real ones with no false alarm. A
# threshold on total duration does not work -- the largest such heap
# runs longer than a host does elsewhere.
STRAY_MEAN_S = 1.5
STRAY_SHARE = 0.10

# Restlessness: this many entries inside this window mean the
# recognition is fraying, not that people are talking fast. On correct
# recognition it fires next to never.
UNREST_STARTS = 7
UNREST_WINDOW_S = 12.0

# The listener only earns the picture when somebody on that camera was
# heard within this stretch. Without the condition the picture goes to
# someone who has said nothing for minutes.
LISTENER_MEMORY_S = 20.0

# Where a cut may sit: a sentence beginning first, a clause break
# second, near before far. Beyond four seconds nothing changes any
# more, so five is room at no cost. Both directions -- searching
# forwards only finds half as many.
BOUNDARY_NEAR_S = 2.0
BOUNDARY_FAR_S = 5.0

# The exact point comes from the sound, not from the text: over 2798
# sentence ends the dip lands in a real speech pause 98 % of the time
# against 42 to 46 % for the word boundary of the recognition.
DIP_NEAR_S = 0.5
DIP_FAR_S = 1.0
DIP_STEP_S = 0.010
# The threshold is a share of the dynamic range of the window itself.
# A fixed level in dB misses entirely on quiet material, where the
# whole file spans twenty dB and the threshold lands below the noise.
DIP_LEVEL_SHARE = 0.30


def merged_spans(spans, join=0.0):
    """Merge overlapping spans; *join* closes gaps up to that long."""
    out = []
    for a, b in sorted(spans):
        if out and a - out[-1][1] <= join:
            out[-1][1] = max(out[-1][1], b)
        else:
            out.append([a, b])
    return [(a, b) for a, b in out]


def span_finder(spans):
    """Return a function saying whether a time falls inside a span.

    The starts are sorted once and searched by halving. The caller asks
    this for every block of the cut against every camera, and a linear
    scan there turned the preview into a wait.
    """
    ordered = merged_spans(spans)
    starts = [a for a, _b in ordered]

    def inside(t):
        i = bisect.bisect_right(starts, t) - 1
        return i >= 0 and t < ordered[i][1]
    return inside


def stray_labels(tracks, mean_s=STRAY_MEAN_S, share=STRAY_SHARE):
    """Return the labels that are a leftover heap rather than a person.

    Speaker recognition leaves small mixed heaps behind: many very
    short segments, little total time. They mark the places where it
    did not know, and giving them a camera shows the wrong person. The
    label with the most speech time is never one of them.
    """
    total = sum(b - a for _n, segs in tracks for a, b in segs)
    if total <= 0 or len(tracks) < 2:
        return set()
    held = {n: sum(b - a for a, b in segs) for n, segs in tracks}
    biggest = max(held, key=held.get)
    out = set()
    for name, segs in tracks:
        if name == biggest or not segs:
            continue
        if held[name] / total >= share:
            continue
        if held[name] / len(segs) < mean_s:
            out.add(name)
    return out


def unrest_spans(tracks, camera_of, starts_needed=UNREST_STARTS,
                 window=UNREST_WINDOW_S):
    """Return the stretches where the speaker recognition frays.

    Counted per camera: two people on one camera taking turns are one
    picture and not two, so their alternation is not restlessness.
    What is counted is how often the picture would have to change --
    two entries in a row on the same camera are one entry.
    """
    need = max(2, int(starts_needed))
    starts, last = [], None
    for a, camera in sorted(
            (a, cam) for cam, segs
            in segments_per_camera(tracks, camera_of) for a, _b in segs):
        if camera != last:
            starts.append(a)
            last = camera
    out = []
    for i in range(len(starts) - need + 1):
        if starts[i + need - 1] - starts[i] <= window:
            out.append((starts[i], starts[i + need - 1]))
    return merged_spans(out)


def next_speaker_camera(t, per_camera, not_this,
                        memory=LISTENER_MEMORY_S):
    """Return the camera of whoever speaks next, if they are there.

    "There" means somebody on that camera was audible within the last
    *memory* seconds. At an insertion point the presumed listener has
    on average been silent for a minute, in the worst case for
    nineteen -- and a camera nobody has reacted on shows a person
    scratching, drinking or looking at a phone.
    """
    best, when = None, None
    for camera, segs in per_camera:
        if camera == not_this:
            continue
        for a, _b in segs:
            if a >= t and (when is None or a < when):
                best, when = camera, a
            if a >= t:
                break
    if best is None:
        return None
    for camera, segs in per_camera:
        if camera != best:
            continue
        if any(b > t - memory and a <= t for a, b in segs):
            return best
    return None


def boundary_near(target, sentences, clauses, near=BOUNDARY_NEAR_S,
                  far=BOUNDARY_FAR_S):
    """Return the sentence or clause boundary a cut should aim at.

    Four steps: a sentence beginning close by, then a clause break
    close by, then the same two further out. In German two thirds of
    the clause breaks carry no pause at all, so punctuation is a
    signal of its own and not the pauses over again.
    """
    for times, radius in ((sentences, near), (clauses, near),
                          (sentences, far), (clauses, far)):
        best = None
        for t in times or ():
            if abs(t - target) <= radius and (
                    best is None or abs(t - target) < abs(best - target)):
                best = t
        if best is not None:
            return best
    return None


def sound_dip(levels, step, target, radius=DIP_NEAR_S,
              share=DIP_LEVEL_SHARE):
    """Return the middle of the quietest stretch around *target*.

    Among the stretches under the threshold the widest wins, less half
    its distance: width alone picks a far one, nearness alone picks a
    narrow one. Returns None where there is nothing to measure.
    """
    if not levels or step <= 0 or radius <= 0:
        return None
    first = max(0, int((target - radius) / step))
    last = min(len(levels), int((target + radius) / step) + 1)
    window = levels[first:last]
    if len(window) < 3:
        return None
    ordered = sorted(window)
    low = ordered[int(0.05 * (len(ordered) - 1))]
    high = ordered[int(0.95 * (len(ordered) - 1))]
    if high <= low:
        return None
    limit = low + share * (high - low)
    best, score, i = None, None, 0
    while i < len(window):
        if window[i] > limit:
            i += 1
            continue
        j = i
        while j < len(window) and window[j] <= limit:
            j += 1
        middle = (first + (i + j) / 2.0) * step
        value = (j - i) * step - 0.5 * abs(middle - target)
        if score is None or value > score:
            best, score = middle, value
        i = j
    return best


def cut_point(target, sentences=(), clauses=(), levels=(),
              step=DIP_STEP_S):
    """Return where a cut aimed at *target* should really sit.

    The text says roughly where -- a sentence beginning or a clause
    break -- and the sound says exactly where. Without either the aim
    comes back unchanged.
    """
    aim = boundary_near(target, sentences, clauses)
    if aim is None:
        aim = target
    for radius in (DIP_NEAR_S, DIP_FAR_S):
        found = sound_dip(levels, step, aim, radius)
        if found is not None:
            return found
    return aim


def wide_shot_length(start, room, sentences=(), clauses=(), holds=5.0,
                     most=15.0):
    """Return how long an inserted wide shot stands.

    At least *holds* seconds, then to the end of the sentence. Where
    that would run past *most*, the last clause break at or below it
    ends the shot instead of a hard cap -- so no wide shot ends in the
    middle of a sentence.
    """
    room = max(0.0, room)
    if room <= 0:
        return 0.0
    floor_t = start + min(holds, room)
    ceiling = start + min(max(holds, most), room)
    for t in sorted(sentences or ()):
        if t >= floor_t:
            if t <= ceiling:
                return t - start
            break
    breaks = [t for t in (clauses or ()) if floor_t <= t <= ceiling]
    if breaks:
        return max(breaks) - start
    return min(holds, room)


_LEVELS = {}


def sound_levels(path, step=DIP_STEP_S):
    """Return the loudness of every ten milliseconds of a recording.

    ffmpeg does the work: the signal is brought down to 8000 Hz,
    rectified and resampled to one value per step, which is the
    envelope. Two seconds for an hour of audio, and it is kept for as
    long as the program runs -- the preview asks for the same recording
    on every keystroke.

    An empty list means the file could not be read. Every caller then
    falls back to the boundary in the text, so nothing depends on this
    succeeding.
    """
    if not path or step <= 0:
        return []
    try:
        key = (os.path.abspath(path), os.path.getmtime(path),
               os.path.getsize(path), round(step, 4))
    except OSError:
        return []
    if key in _LEVELS:
        return _LEVELS[key]
    rate = int(round(1.0 / step))
    try:
        p = subprocess.run(
            ["ffmpeg", "-v", "error", "-i", path, "-map", "a:0", "-af",
             "aresample=8000,aeval=abs(val(0)):c=same,aresample=%d" % rate,
             "-ac", "1", "-f", "s16le", "-"], capture_output=True)
    except OSError:
        return []
    data = p.stdout or b""
    if p.returncode or len(data) < 4:
        _LEVELS[key] = []
        return []
    out = list(struct.unpack("<%dh" % (len(data) // 2),
                             data[:len(data) // 2 * 2]))
    _LEVELS[key] = out
    return out


def sound_levels_for(d):
    """Return the level envelope belonging to a handover file.

    Only a recording as long as the programme itself can be used: the
    stored single tracks start where the programme starts, and a file
    of a different length would put every dip at the wrong second. The
    length is measured, not assumed.
    """
    files = (d or {}).get("audio_files") or {}
    length = float((d or {}).get("length_s") or 0.0)
    if not files or length <= 0:
        return []
    for name in sorted(files, key=lambda n: (n != "Full-Mix", n)):
        path = files[name]
        if not path or not os.path.exists(path):
            continue
        try:
            seconds = sample_count(path) / float(SR)
        except Exception:
            continue
        if abs(seconds - length) > 2.0:
            continue
        return sound_levels(path)
    return []


def reaction_cuts(tracks, words, camera_of, gap=3.0, holds=0.7,
                  over=10.0):
    """Return {when the answer begins: who answers} for every question.

    After a question the picture belongs to whoever answers: they draw
    breath, look up and start. The question mark raises the chance of
    a change of speaker to three or four times the normal, and the
    question is almost always the last thing the asker says.

    It fires only where the asker is not the main speaker, somebody
    else starts within *gap* seconds and holds *holds* of the next
    *over* seconds. Where both sit on the same camera nothing happens:
    the cut would be a jump onto the same picture.
    """
    out = {}
    if not words or not tracks:
        return out
    held = {n: sum(b - a for a, b in segs) for n, segs in tracks}
    if len(held) < 2:
        return out
    main = max(held, key=held.get)
    entries = sorted((a, n) for n, segs in tracks for a, _b in segs)

    def talking_at(t):
        for name, segs in tracks:
            for a, b in segs:
                if a <= t < b:
                    return name
        return None

    for group in sentences_of(words):
        last = group[-1]
        text = (last.get("word") or "").strip().rstrip(CLOSING_MARKS)
        if not text.endswith("?"):
            continue
        end = last["end"]
        asker = talking_at((group[0]["start"] + end) / 2.0)
        if asker is None or asker == main:
            continue
        answer = None
        for a, n in entries:
            if a < end:
                continue
            if a > end + gap:
                break
            if n != asker:
                answer = (a, n)
                break
        if not answer:
            continue
        when, who = answer
        spoken = sum(max(0.0, min(b, when + over) - max(a, when))
                     for n, segs in tracks if n == who for a, b in segs)
        if over > 0 and spoken < holds * over:
            continue
        if camera_of.get(who) and camera_of.get(who) == camera_of.get(asker):
            continue
        out[when] = who
    return out


def cut_rules(**over):
    """Return the settings the cut rules read, with their defaults.

    One dict rather than a dozen parameters: the same seven rules are
    read in three places, and a keyword is all it takes to override
    one of them.
    """
    out = {"min_speech": MIN_SPEECH_TO_SWITCH_S,
           "on_monologue": SHOT_ALTERNATE,
           "on_together": SHOT_WIDE,
           "on_uncertain": SHOT_WIDE,
           "on_question": SHOT_ANSWER,
           "reaction_lead": 1.5,
           "reaction_gap": 3.0,
           "reaction_hold": 0.7,
           "reaction_over": 10.0,
           # None means: whatever the caller passed as the length of an
           # inserted wide shot. Two ways of saying the same number
           # would let the preview and the run disagree.
           "wide_holds": None,
           "wide_most": 15.0,
           "words": (),
           "levels": (),
           "level_step": DIP_STEP_S}
    out.update(over)
    return out


def rules_from_settings(args):
    """Read the cut rules out of the command line settings.

    The four choices come out of CUT_CHOICES rather than being named
    again here: two lists of the same four names drift apart.
    """
    picked = {}
    for switch, _caption, default_value, _values, _k, _l in CUT_CHOICES:
        field = switch.replace("-", "_")
        picked[field] = getattr(args, field, None) or default_value
    return cut_rules(
        min_speech=float(getattr(args, "min_speech_to_switch",
                                 MIN_SPEECH_TO_SWITCH_S)),
        reaction_lead=float(getattr(args, "reaction_lead", 1.5)),
        reaction_gap=float(getattr(args, "reaction_gap", 3.0)),
        reaction_hold=float(getattr(args, "reaction_hold", 0.7)),
        wide_holds=float(getattr(args, "wide_length", 5.0)),
        wide_most=float(getattr(args, "wide_most", 15.0)),
        **picked)


def insert_wide_shots(cut, tracks, wide_shot, after=40.0, duration=5.0,
                      min_len=1.2, at_latest=120.0, camera_of=None,
                      rules=None):
    """Break up long shots by leaving the speaker for a while.

    A shot that holds longer than *after* is opened at a sentence
    boundary nearby -- a sentence beginning within two seconds, else a
    clause break, else the same two within five. The exact point comes
    from the sound. What is shown there is the "Long monologue"
    choice: the wide shot, the listener, the two by turns, or nothing
    at all.

    The shot then stands at least *duration* seconds and runs to the
    end of the sentence. Where no sentence boundary is known at all,
    the longest speech pause nearby takes its place, and *at_latest*
    forces a cut where there is not even one: a cut at a mediocre spot
    beats two minutes of stasis.
    """
    rules = rules or cut_rules()
    words = rules.get("words") or ()
    sentences = sentence_start_times(words) if words else []
    clauses = clause_break_times(words) if words else []
    levels = rules.get("levels") or ()
    step = rules.get("level_step") or DIP_STEP_S
    holds = float(rules.get("wide_holds") or duration)
    most = float(rules.get("wide_most") or 15.0)
    show = rules.get("on_monologue") or SHOT_WIDE
    if show == SHOT_HOLD:
        return list(cut)
    per_camera = segments_per_camera(tracks, camera_of or {})
    pauses, _entries = find_pauses(tracks)

    def picture(t, who, shown):
        """Return which camera the break shows, and remember it."""
        listener = (next_speaker_camera(t, per_camera, who)
                    if show in (SHOT_LISTENER, SHOT_ALTERNATE) else None)
        if show == SHOT_LISTENER:
            choice = listener or wide_shot
        elif show == SHOT_ALTERNATE:
            # Alternating needs a memory: without it the same camera
            # comes up again by chance and it is not alternation.
            turns = [wide_shot] + ([listener] if listener else [])
            choice = turns[len(shown) % len(turns)]
        else:
            choice = wide_shot
        shown.append(choice)
        return choice

    def split_up(a, b, who, shown, depth=0):
        if depth > 12 or b - a <= after:
            return [(a, b, who)]
        first, last = a + min_len, b - min_len - holds
        if last <= first:
            return [(a, b, who)]
        wanted = a + min(after, (b - a) / 2.0)
        t = None
        if sentences or clauses:
            aim = cut_point(wanted, sentences, clauses, levels, step)
            if first <= aim <= last:
                t = aim
        if t is None:
            # No usable boundary: the longest speech pause nearby, and
            # without one of those the clock.
            points = [(p[0] + min(0.3, (p[1] - p[0]) / 2.0), p[1] - p[0])
                      for p in pauses if p[0] >= a and p[1] <= b]
            points = [(x, g) for x, g in points if first <= x <= last]
            if not points and b - a > at_latest:
                parts = int((b - a) // at_latest) + 1
                stride = (b - a) / parts
                points = [(a + stride * i, 0.0) for i in range(1, parts)]
                points = [(x, g) for x, g in points if first <= x <= last]
            if not points:
                return [(a, b, who)]
            t = max(points, key=lambda xg: (
                3.0 * min(xg[1], 2.0)
                - abs(xg[0] - wanted) / max(1.0, after) * 1.5))[0]
            t = cut_point(t, (), (), levels, step)
            t = min(max(t, first), last)
        length = wide_shot_length(t, b - min_len - t, sentences, clauses,
                                  holds, most)
        if length <= 0:
            return [(a, b, who)]
        seen = picture(t, who, shown)
        if seen == who:
            return [(a, b, who)]
        return (split_up(a, t, who, shown, depth + 1)
                + [(t, t + length, seen)]
                + split_up(t + length, b, who, shown, depth + 1))

    result = []
    for a, b, who in cut:
        if who == wide_shot or b - a <= after:
            result.append((a, b, who))
        else:
            result += split_up(a, b, who, [])
    return merge_adjacent(result)


def merge_adjacent(cut):
    """Merge two identical consecutive shots into one."""
    extra = []
    for a, b, who in cut:
        if extra and extra[-1][2] == who:
            extra[-1] = (extra[-1][0], b, who)
        else:
            extra.append((a, b, who))
    return [tuple(x) for x in extra]


# How long somebody may pause and still be holding the floor. Below
# this a gap is a breath, above it the next person may come in. It is
# what makes the opening independent of how finely a source cuts its
# segments: a recogniser that chops one long introduction into ten
# pieces must not read as ten handovers.
FLOOR_HOLD_GAP_S = 2.0


def floor_handovers(tracks, main_speaker, min_len_speech,
                    gap=FLOOR_HOLD_GAP_S):
    """Return where somebody other than the main speaker holds the floor.

    A single speech block is not a handover: one block says only that
    the source drew a boundary there. A handover is somebody speaking
    on, through their own breaths, and being the one heard while they
    do it -- so the blocks of one person are chained across short
    gaps, and the chain counts only where its speaker holds more of
    its own window than everybody else together.

    Returns [(from, to), ...] in time order.
    """
    own = {}
    for n, segs in tracks:
        own.setdefault(n, []).extend(segs)
    out = []
    for n, segs in own.items():
        if n == main_speaker:
            continue
        chains = []
        for a, b in sorted(segs):
            if chains and a - chains[-1][1] <= gap:
                chains[-1][1] = max(chains[-1][1], b)
                chains[-1][2] += b - a
            else:
                chains.append([a, b, b - a])
        for a, b, spoke in chains:
            spoke = min(spoke, b - a)
            if spoke < min_len_speech:
                continue
            rivals = sum(max(0.0, min(b, y) - max(a, x))
                         for other_name, parts in own.items()
                         if other_name != n for x, y in parts)
            if rivals >= spoke:
                continue
            out.append((a, b))
    return sorted(out)


def wide_shot_at_edges(cut, tracks, wide_shot, min_len_speech=4.0,
                   faint=False):
    """Hold the wide shot while the round is introduced and closed.

    Someone introduces the participants at the start and says goodbye at the
    end; both belong in the wide frame. The opening ends where the floor
    first changes hands away from the main speaker, and the same rule runs
    backwards from the end. Resolve calls this "use wide angle for
    intro and outro".

    The rule stops at the recognition: it reads who speaks when, and a
    voice the separation never hears cannot end the opening.
    """
    if not cut:
        return cut
    speech_time = {n: sum(b - a for a, b in segs) for n, segs in tracks}
    if len(speech_time) < 2:
        return cut
    main_speaker = max(speech_time, key=speech_time.get)
    other = floor_handovers(tracks, main_speaker, min_len_speech)
    if not other:
        return cut
    begin, end = cut[0][0], cut[-1][1]
    until, from_s = other[0][1], other[-1][0]
    if until - begin > (end - begin) / 3.0 or end - from_s > (end - begin) / 3.0:
        # A third would no longer be a greeting but a conversation.
        if not faint:
            print(T('  Wide shot at the edges: skipped -- the first or '
                    'last announcement\n  would be too long for a greeting.'))
        return cut
    out = []
    for a, b, who in cut:
        if b <= until or a >= from_s:
            out.append((a, b, wide_shot))
        elif a < until < b:
            out += [(a, until, wide_shot), (until, b, who)]
        elif a < from_s < b:
            out += [(a, from_s, who), (from_s, b, wide_shot)]
        else:
            out.append((a, b, who))
    if not faint:
        print(T('  Wide shot at the edges: until %s and from %s') % (as_hms(until - begin),
                                                      as_hms(from_s - begin)))
    return merge_adjacent(out)


def metrics_sentence(numbers, colours, minutes_fn):
    """Build the summary line under the preview.

    How much speech time lands on the speaker's own camera, how much on the
    wide shot, and how much goes to the wrong camera. The last number
    matters most, so it is shown in the warning colour.
    """
    return (T("<span style='color:%(t)s'><b>%(n)d shots</b>, median "
              '%(med).1f s, shortest %(short).1f s, longest camera '
              '%(long).0f s</span>. Speech time: <b>%(own).1f %%</b> on '
              'their own camera (%(own_t)s), %(wide).1f %% on the wide '
              "shot (%(wide_t)s), <span style='color:%(warn)s'>at "
              "%(off).1f %% (%(off_t)s) the speaker's camera is not "
              'active</span>')
            % {"t": colours["heading"], "warn": colours["warning"],
               "n": numbers["shots"], "med": numbers["median"],
               "short": numbers["shortest"], "long": numbers["longest_camera"],
               "own": numbers["in_frame"], "own_t": minutes_fn(numbers["in_frame_s"]),
               "wide": numbers["on_wide"], "wide_t": minutes_fn(numbers["on_wide_s"]),
               "off": numbers["off_camera"],
               "off_t": minutes_fn(numbers["off_camera_s"])})


def speech_heading(own_measure_measured, total_sum=""):
    """Return the heading for the speech segment table.

    Levels measured against each other are coarser than voices taken
    apart; whoever judges the preview needs to know which of the two
    they see.
    """
    source_text = (T('Speakers, self-measured from the tracks')
                   if own_measure_measured
                   else T('Speakers, separated by voice'))
    return "%s -- %s" % (source_text, total_sum) if total_sum else source_text


def format_complaint(d):
    """Say why a stored file cannot be used, or return "".

    The file carries the number of the naming it was written with. Where
    that differs, the keys inside mean something else -- reading it anyway
    would look like it worked and quietly assign the wrong things.
    """
    if not isinstance(d, dict):
        return T("This is not a file of this program.")
    present = int(d.get("format") or 1)
    if present == FILE_FORMAT:
        return ""
    return T("This file was written by version %s in format %d; this one "
             "writes format %d. The names inside have changed since, so it "
             "cannot be read. Please set the run up again.",
             d.get("version") or "?", present, FILE_FORMAT)


def find_project_file(file_path):
    """Find the project file for whatever was pointed at.

    Pointing at the folder, or at the wrong file in it, should not produce
    an error message, so the neighbourhood is searched too. A project file
    is a dict containing "files" -- the name alone is not enough, since
    plenty of files end in json.

    Returns (contents, path) or (None, "").
    """
    if not file_path:
        return None, ""
    folder = file_path if os.path.isdir(file_path) else os.path.dirname(file_path)
    attempts = [] if os.path.isdir(file_path) else [file_path]
    try:
        attempts += sorted(os.path.join(folder, n) for n in os.listdir(folder)
                           if n.startswith(PROJECT_PREFIX)
                           and n.lower().endswith(".json"))
    except OSError:
        pass
    for attempt in attempts:
        try:
            with open(attempt, encoding="utf-8") as f:
                loaded = json.load(f)
        except (OSError, ValueError):
            continue
        if isinstance(loaded, dict) and "files" in loaded:
            return loaded, attempt
    return None, ""


def project_files(d):
    """Split the project's file list into what is still there and what is not.

    Returns ([(path, kind), ...], [missing names]). Vanished files are named
    rather than silently dropped.
    """
    present, missing = [], []
    for entry in ((d or {}).get("files") or []):
        file_path = entry.get("path")
        if not file_path:
            continue
        if os.path.exists(file_path):
            present.append((file_path, entry.get("kind") or "audio"))
        else:
            missing.append(os.path.basename(file_path))
    return present, missing


def choose_zero_point(audio_origin=(), camera_origin=()):
    """Return where programme time starts on the clock.

    Speaker segments count from the start of the material that was
    processed, and that is the audio recordings, not the cameras. Nothing is
    guessed: without a known audio start the earliest camera start applies,
    and without that either the result is None.
    """
    audio_files = [float(t) for t in audio_origin if t is not None]
    if audio_files:
        return min(audio_files)
    videos = [float(t) for t in camera_origin if t is not None]
    return min(videos) if videos else None


def build_handover(segment_list, length, assignment, cameras, audio_origin=(),
                    camera_origin=(), places=()):
    """Build the handover from segments and the assignment.

    This is the deciding part of the preview -- no window, no file: parsed
    segments and the assignment go in, the same handover the run writes comes
    out.

      segments      [(name, [(from, to), ...]), ...]
      length        programme length in seconds
      assignment    {speaker name: camera file (basename)}
      cameras       [{"track", "file", "start_s"}, ...] in display order
      audio_origin  known audio starts on the clock, None skipped
      camera_origin the same for cameras, used only as a fallback
      places        where the statistics were searched, for the message

    Returns (handover, "") or (None, reason). A preview that stays silently
    empty helps nobody, so every no comes with a sentence.
    """
    if not segment_list or not length or length <= 0:
        return None, (T('No speakers known yet -- nothing measured, '
                        'nothing separated, and no handover file of an '
                        'earlier run in %s or its subfolders.')
                      % (T(' and ').join([x for x in places if x])
                         or T('no folder')))
    if not cameras:
        return None, (T('No cameras assigned yet -- switch Multitrack on '
                        'to do that.'))
    out = []
    for cam in cameras:
        short = os.path.basename(cam.get("file") or "")
        # The camera audio has its own row in the upper table, so it arrives
        # through the assignment already.
        out.append({"track": cam.get("track"), "file": cam.get("file"),
                     "speakers": [n for n, target in assignment.items()
                                  if target == short],
                     "start_s": cam.get("start_s")})
    return ({"speakers": [{"name": n,
                           "sections": [list(x) for x in segs]}
                          for n, segs in segment_list],
             "cameras": out, "length_s": length,
             "start_s": choose_zero_point(audio_origin, camera_origin)}, "")


def apply_time_window(d, in_point, out_point):
    """Apply the In point and the Out point to an already written handover.

    The speaker times in it count from the start of the window in force at
    the time; start_s says where that was. A new setting can be converted
    from that without measuring anything again.

    Returns (handover, complaint). With a complaint the handover comes back
    untrimmed: silently ignoring the window would show a cut the run then
    refuses to make.
    """
    if not (in_point or "").strip() and not (out_point or "").strip():
        return d, ""
    length = float(d.get("length_s") or 0.0)
    origin = d.get("start_s")
    fps = max(1.0, float(d.get("fps") or 30.0))

    def compute(value_text, from_the_end):
        value, absolute = parse_time_point(value_text, fps)
        if value is None:
            return None
        if absolute:
            if origin is None:
                return None
            return value - float(origin)
        if value < 0 and not from_the_end:
            raise ValueError(value_text)
        return (length + value) if value < 0 else value

    try:
        from_s = compute(in_point, False) if (in_point or "").strip() else 0.0
        until = compute(out_point, True) if (out_point or "").strip() else length
    except ValueError as e:
        # The same rule as in the run: a negative value counts from the end
        # and only works for Out point. Anything else is not a time at all.
        text = str(e)
        if text == (in_point or "").strip():
            return d, T('%r counts from the end -- that only works '
                        'for Out point.') % text
        return d, T('In point or Out point cannot be read here.')
    if from_s is None or until is None:
        return d, T('In point or Out point cannot be read here.')
    if until - from_s < 5:
        return d, T('Out point lies less than 5 seconds after In point.')
    from_s, until = max(0.0, from_s), min(length, until)
    fresh = dict(d)
    fresh["length_s"] = round(until - from_s, 3)
    # The origin moves along. start_s means "where programme time starts
    # on the clock" everywhere, and after trimming that is In point. Leaving
    # the old value made the player show a wall clock time off by the
    # length of the removed head.
    if origin is not None:
        fresh["start_s"] = round(float(origin) + from_s, 3)
    fresh["speakers"] = [
        {"name": s.get("name"),
         "sections": [[max(0.0, a - from_s), min(until, b) - from_s]
                        for a, b in (s.get("sections") or [])
                        if b > from_s and a < until]}
        for s in (d.get("speakers") or [])]
    # The words move with them. Left where they were, every sentence
    # boundary would sit as far out as the removed head is long, and
    # the cut points would follow them there.
    if d.get("words"):
        fresh["words"] = [[a - from_s, b - from_s, text]
                          for a, b, text in d["words"]
                          if b > from_s and a < until]
    return fresh, ""


def as_minutes(seconds):
    """Format seconds as "3:34 min", short enough to sit inside a sentence.

    Only ever shown on screen, never written into a file, so it may be
    translated.
    """
    s = int(round(max(0.0, seconds)))
    return T("%d:%02d min") % (s // 60, s % 60)


def speaker_statistics(d):
    """Return who speaks how much and how often.

    Same source as the cut: the handover file or the Auphonic statistics.
    Without these numbers a cut result cannot be judged -- 12 percent wide
    shot means something else when one person speaks 70 percent of the
    time.
    """
    out, total = [], 0.0
    for speaker in (d.get("speakers") or []):
        segs = [tuple(x) for x in (speaker.get("sections") or [])]
        total_sum = sum(b - a for a, b in segs)
        total += total_sum
        out.append({"name": speaker.get("name") or T('Track'), "seconds": total_sum,
                     "blocks": len(segs),
                     "mean": (total_sum / len(segs)) if segs else 0.0,
                     "longest_one": max((b - a for a, b in segs), default=0.0)})
    for e in out:
        e["share"] = 100.0 * e["seconds"] / (total or 1.0)
    out.sort(key=lambda e: -e["seconds"])
    # Silence: whatever is left when the speech blocks of all speakers are
    # laid on top of each other. Where two speak at once the time counts
    # twice above, but not here.
    every = sorted((a, b) for speaker in (d.get("speakers") or [])
                  for a, b in (speaker.get("sections") or []))
    merged = []
    for a, b in every:
        if merged and a <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], b)
        else:
            merged.append([a, b])
    spoken = sum(b - a for a, b in merged)
    length = float(d.get("length_s") or 0.0) or (merged[-1][1]
                                                 if merged else 0.0)
    return out, total, max(0.0, length - spoken), length


def coupling_matrix(power, speech, faint=6.0, loud=10.0, at_least=3):
    """Return how loudly each voice arrives in the other microphones.

    ``c[i][j]`` is the power gain with which speaker j appears in
    microphone i. It is measured where j speaks and nobody else does, so
    whatever else is on i's track at that moment came from j. The diagonal
    is 1: a speaker arrives in their own microphone unchanged.

    Nothing is assumed about the distance between the microphones. Where a
    pair offers no such moment, the entry stays 0 -- no bleed known, none
    subtracted.

      *power*   [track][block] mean square per block, on a common axis
      *speech*  the speech level per track, as amplitude
    """
    n = len(power)
    c = np.eye(n)
    for j in range(n):
        # j speaks, everyone else is quiet against their own speech level.
        alone = power[j] > (speech[j] * (10 ** (-loud / 20.0))) ** 2
        for other in range(n):
            if other != j:
                alone &= power[other] < (speech[other]
                                         * (10 ** (-faint / 20.0))) ** 2
        blocks = np.where(alone)[0]
        if len(blocks) < at_least:
            continue
        for i in range(n):
            if i == j:
                continue
            own = power[j][blocks]
            c[i][j] = float(np.median(power[i][blocks] / np.maximum(own,
                                                                    1e-20)))
    return c


def unmix_levels(power, c, at_most=30.0):
    """Take the bleed out of the measured levels.

    What a microphone hears is its own speaker plus a share of every other
    one: ``observed = c @ own``. With the coupling measured, the own share
    follows from solving that, once for all blocks at a time.

    Returns (own, reason). Where the coupling is too strong to invert --
    microphones side by side -- the levels come back unchanged and the
    reason says why. Better an unseparated measurement than an invented
    one.
    """
    if len(power) < 2:
        return power, ""
    highest = float(max(c[i][j] for i in range(len(c))
                        for j in range(len(c)) if i != j) if len(c) > 1
                    else 0.0)
    if highest >= 0.9:
        return power, T('the microphones hear each other almost as loudly '
                        'as their own speaker')
    try:
        if float(np.linalg.cond(c)) > at_most:
            return power, T('the tracks are too much alike to separate')
        own = np.linalg.solve(c, power)
    except np.linalg.LinAlgError as e:
        return power, str(e)
    return np.maximum(own, 0.0), ""


def speakers_from_tracks(tracks, block=0.1, rate=8000, over_db=10.0,
                        gap=0.35, min_len=0.4, report=None, separate=True,
                        note=None):
    """Derive speech segments from the separate tracks.

    Each block is measured against the track's own noise floor, because a
    fixed threshold fails when recorders are set to different gains.

    With *separate* the bleed is taken out first. Without it every voice
    loud enough in a neighbouring microphone counts as that neighbour
    speaking -- and where all tracks report speech at once, no camera shows
    exactly those speakers and the cut stays on the wide shot for the whole
    recording. The coupling is measured, not assumed, so it also works
    where the microphones are less than the 3:1 rule apart.

    *tracks* is [(name, path, offset)]; the offset moves the segments onto
    the common time axis. *note* is called with one line about the
    separation. Returns [(name, [(a, b), ...])].
    """
    names, levels, shifts = [], [], []
    # Read a handful at a time, not all at once: an hour of audio is a
    # couple of hundred megabytes per track.
    step = max(2, min(4, how_many_processors()))
    read = {}
    for i, (name, file_path, offset) in enumerate(tracks):
        if i % step == 0:
            read = {}
            group = tracks[i:i + step]
            for entry, x in zip(group, parallel_map(
                    group, lambda t: decode_audio(t[1], rate=rate))):
                read[entry[1]] = x
        if report:
            report(T('Measuring %s (%d of %d)') % (name, i + 1, len(tracks)))
        x = read.pop(file_path, None)
        if x is None:
            x = decode_audio(file_path, rate=rate)
        nb = max(1, int(block * rate))
        count = len(x) // nb
        names.append(name)
        shifts.append(int(round(offset / block)))
        if count < 2:
            levels.append(np.zeros(0))
            continue
        levels.append(np.sqrt((x[:count * nb].reshape(count, nb).astype(
            np.float64) ** 2).mean(axis=1)))

    # One grid for all of them: only on a shared time axis does it mean
    # anything that one track is louder than another at this moment.
    begin = min(shifts) if shifts else 0
    end = max((s + len(v) for s, v in zip(shifts, levels)), default=0)
    width = max(0, end - begin)
    level = np.zeros((len(levels), width))
    for i, (s, v) in enumerate(zip(shifts, levels)):
        if len(v):
            level[i][s - begin:s - begin + len(v)] = v
    speech = np.array([float(np.percentile(v[v > 0], 90))
                       if len(v) and len(v[v > 0]) else 0.0 for v in levels])

    power = level ** 2
    reason = ""
    if separate and len(levels) > 1 and width:
        c = coupling_matrix(power, speech)
        power, reason = unmix_levels(power, c)
        if note:
            # c is a ratio of powers, so ten times the logarithm -- the
            # same figure the 3:1 check reports for amplitudes.
            far = [(10.0 * math.log10(1.0 / max(c[i][j], 1e-9)), names[j],
                    names[i]) for i in range(len(c)) for j in range(len(c))
                   if i != j and c[i][j] > 0]
            if reason:
                note(T('  Bleed not separable: %s') % reason)
            elif far:
                worst = min(far)
                note(T('  Bleed measured, %s in %s only %.1f dB quieter '
                       '-- taken out of the speech detection')
                     % (worst[1], worst[2], worst[0]))
                # Where a pair offers no moment of one voice alone, its
                # entry stays 0 and that much bleed is left in. The
                # separation still happens -- half a model beats none --
                # but silence here would look like a clean measurement.
                # Below about 5 dB this is where it starts to slip.
                pairs = len(c) * (len(c) - 1)
                if len(far) < pairs:
                    note(T('  Caution: only %d of %d pairs measurable. For '
                           'the rest no moment was found where exactly one '
                           'person speaks, so their bleed stays in -- the '
                           'speaker detection is unreliable here.')
                         % (len(far), pairs))
            else:
                note(T('  No moment found where exactly one person speaks '
                       '-- the bleed stays in the speech detection.'))
    level = np.sqrt(power)

    out = []
    for i, name in enumerate(names):
        row = level[i]
        present = row[row > 0]
        if not len(present):
            out.append((name, []))
            continue
        # Noise floor: the lowest fifth of the blocks. Above it counts as
        # speech.
        floor = float(np.percentile(present, 20))
        threshold = max(floor * (10.0 ** (over_db / 20.0)),
                       float(np.percentile(present, 90)) * 0.08)
        loud = row > threshold
        segments, first = [], None
        for j, on in enumerate(loud):
            if on and first is None:
                first = j
            elif not on and first is not None:
                segments.append([first * block, j * block])
                first = None
        if first is not None:
            segments.append([first * block, len(row) * block])
        # Short pauses inside a sentence are not speaker changes.
        joined = []
        for a, b in segments:
            if joined and a - joined[-1][1] <= gap:
                joined[-1][1] = b
            else:
                joined.append([a, b])
        shift = begin * block
        out.append((name, [(round(a + shift, 2), round(b + shift, 2))
                            for a, b in joined if b - a >= min_len]))
    return out


def camera_cut(tracks, length, camera_of, wide_shot,
               min_len=MIN_EDIT_DURATION_S,
               delay=0.3, after=40.0, holds=5.0, at_latest=120.0,
               edge=True, rules=None, faint=True):
    """Build the whole camera cut, in the order the rules apply.

    The preview and the run both come through here. Two copies of this
    order drift apart, and then the same material yields a different
    cut depending on which of the two produced it.
    """
    rules = rules or cut_rules()
    cut = build_camera_cut(tracks, length, camera_of, wide_shot,
                           min_len, -delay, rules)
    if edge:
        cut = wide_shot_at_edges(cut, tracks, wide_shot, faint=faint)
        cut = merge_short_shots(cut, min_len)
    if after > 0:
        cut = insert_wide_shots(cut, tracks, wide_shot, after, holds,
                                min_len, at_latest, camera_of, rules)
    return cut


def cut_statistics(d, min_len=MIN_EDIT_DURATION_S, delay=0.3, after=40.0,
                       holds=5.0, at_latest=120.0, edge=True,
                       rules=None):
    """Compute the camera cut without writing anything.

    *d* is a parsed handover file (..._resolve.json). Returns the numbers
    worth seeing while adjusting: how many shots, how long they stand, who
    is on screen how often, and above all how much speech time lands on a
    camera the speaker is not in.
    """
    tracks = [(s["name"], [tuple(x) for x in (s.get("sections") or [])])
              for s in (d.get("speakers") or [])]
    cameras = d.get("cameras") or []
    if not tracks or not cameras:
        return None
    camera_of = {}
    for cam in cameras:
        for n in (cam.get("speakers") or []):
            camera_of[n] = cam.get("track")
    taken = set(camera_of.values())
    free = [cam.get("track") for cam in cameras if cam.get("track") not in taken]
    wide_shot = free[0] if free else cameras[0].get("track")
    length = float(d.get("length_s") or 0.0)
    if length <= 0:
        length = max((b for _, segs in tracks for _, b in segs), default=0.0)
    if length <= 0:
        return None

    # What was said and the sound itself come out of the handover file:
    # the caller sets the numbers, not the material.
    rules = dict(rules or cut_rules())
    if not rules.get("words"):
        rules["words"] = words_from_handover(d)
    if not rules.get("levels"):
        rules["levels"] = sound_levels_for(d)
    cut = camera_cut(tracks, length, camera_of, wide_shot, min_len,
                     delay, after, holds, at_latest, edge, rules)
    if not cut:
        return None

    blocks = sorted(b - a for _, segs in tracks for a, b in segs)
    takes = sorted(b - a for a, b, _ in cut)
    share, how_often = {}, {}
    for a, b, who in cut:
        share[who] = share.get(who, 0.0) + (b - a)
        how_often[who] = how_often.get(who, 0) + 1
    total = sum(share.values()) or 1.0

    # How much speech time runs past the wrong camera? Checked in tenth of
    # a second steps -- finer would be effort without insight.
    step = 0.1
    in_frame = off_camera = on_wide_shot = 0
    i = 0
    # Sorted by time only: a speaker without a camera has None in third
    # place, and comparing that with a camera name would raise.
    speech = sorted(((a, b, camera_of.get(n))
                     for n, segs in tracks for a, b in segs),
                    key=lambda x: (x[0], x[1]))
    limits = [(a, b, who) for a, b, who in cut]
    for a, b, shot_cam in speech:
        if shot_cam is None:
            continue
        t = a
        while t < b:
            while i < len(limits) - 1 and limits[i][1] <= t:
                i += 1
            while i > 0 and limits[i][0] > t:
                i -= 1
            shown = limits[i][2]
            if shown == shot_cam:
                in_frame += 1
            elif shown == wide_shot:
                on_wide_shot += 1
            else:
                off_camera += 1
            t += step
    speech_time = (in_frame + off_camera + on_wide_shot) or 1
    # The same colour assignment as in Resolve, so the band in the
    # interface and the clips in the edit window look alike.
    colour_cameras = [{"track": cam.get("track"), "wide": cam.get("track") == wide_shot}
                    for cam in cameras]
    assigned, _duplicate = colour_per_camera(colour_cameras, list(CLIP_COLOURS))
    return {
        "cut": cut,
        "colours": {track: clip_colour_rgb(name) for track, name in assigned.items()},
        "shots": len(cut),
        "median": takes[len(takes) // 2],
        "shortest": takes[0],
        "longest": takes[-1],
        "longest_camera": max((b - a for a, b, who in cut if who != wide_shot),
                               default=0.0),
        "wides": sum(1 for _, _, who in cut if who == wide_shot),
        "shares": [(who, 100.0 * v / total, v, how_often.get(who, 0)) for who, v in
                    sorted(share.items(), key=lambda x: -x[1])],
        "wide": wide_shot,
        "in_frame": 100.0 * in_frame / speech_time,
        "on_wide": 100.0 * on_wide_shot / speech_time,
        "off_camera": 100.0 * off_camera / speech_time,
        "in_frame_s": in_frame * step,
        "on_wide_s": on_wide_shot * step,
        "off_camera_s": off_camera * step,
        "speech_time_s": speech_time * step,
        "shortest_block": blocks[0] if blocks else 0.0,
    }


def build_camera_cut(tracks, length, camera_of, wide_shot,
                     min_len=MIN_EDIT_DURATION_S, lead_in=-0.3,
                     rules=None):
    """Return the camera cut as [(from, to, camera)].

    The same list camera_cut_detail builds, without who was speaking.
    """
    return [(a, b, who) for a, b, who, _speaking
            in camera_cut_detail(tracks, length, camera_of, wide_shot,
                                 min_len, lead_in, rules)]


def camera_cut_detail(tracks, length, camera_of, wide_shot,
                      min_len=MIN_EDIT_DURATION_S, lead_in=-0.3,
                      rules=None):
    """Turn speaker segments into a camera cut list.

    Returns [(from, to, camera, speakers)]; *speakers* is who talks in
    that shot, empty during silence.

    The rules are the ones a human editor follows:

      * Whoever speaks alone gets their camera, once they have held the
        floor for the minimum speaking time.
      * When several speak at once, a camera showing exactly those
        speakers is preferred -- one covering both hosts, say. Where no
        camera covers them, the "Several speak at once" choice decides.
      * Where the recognition frays or leaves a heap of scraps behind,
        the "Recognition uncertain" choice decides.
      * Silence stays on the wide shot unless someone is about to speak,
        in which case it switches early by the lead-in.
      * After a question the picture may go to the answer before it
        starts -- the "Question" choice.

    Everything is judged per camera, never per speaker: two people on one
    camera are one condition, and a change of speaker between them is a
    jump onto the same picture, so nothing is cut there.
    """
    rules = rules or cut_rules()
    long = [(n, list(segs)) for n, segs in tracks]
    edges = sorted({t for _, segs in long for s in segs for t in s}
                    | {0.0, length})
    # Which camera shows whom is already in the assignment: several
    # speakers on the same camera means it shows both.
    coverage = {}
    for name, camera in (camera_of or {}).items():
        if camera:
            coverage.setdefault(camera, set()).add(name)

    def common_camera(active):
        """Return the camera showing exactly these speakers, or all of them.

        Exact match first. Otherwise the smallest camera that contains them
        all: a three-shot beats the wide shot when only two of them speak.
        None if nothing fits.
        """
        wanted_name = set(active)
        for camera, who in coverage.items():
            if who == wanted_name:
                return camera
        matching = [(len(who), camera) for camera, who in coverage.items()
                   if wanted_name <= who]
        return min(matching)[1] if matching else None

    per_camera = segments_per_camera(long, camera_of or {})
    words = rules.get("words") or ()
    sentences = sentence_start_times(words) if words else []
    clauses = clause_break_times(words) if words else []
    levels = rules.get("levels") or ()
    step = rules.get("level_step") or DIP_STEP_S
    # Too short to move the camera, judged per camera: what counts is
    # that one of the people on it was speaking, not which of them.
    min_speech = float(rules.get("min_speech") or 0.0)
    too_short = {}
    for camera, segs in per_camera:
        too_short[camera] = span_finder(
            [(a, b) for a, b in segs if b - a < min_speech])
    stray = stray_labels(long)
    restless = span_finder(unrest_spans(long, camera_of or {}))
    turns = []

    def unsure_picture(t, active):
        """Return what to show where the cut does not know whom."""
        want = rules.get("on_uncertain") or SHOT_WIDE
        if want == SHOT_HOLD:
            return None
        if want in (SHOT_LISTENER, SHOT_ALTERNATE):
            here = {camera_of.get(n) for n in active}
            listener = next_speaker_camera(
                t, per_camera, next(iter(here)) if len(here) == 1 else None)
            if want == SHOT_LISTENER:
                return listener or wide_shot
            row = [wide_shot] + ([listener] if listener else [])
            choice = row[len(turns) % len(row)]
            turns.append(choice)
            return choice
        return wide_shot

    def together_picture(t, active):
        """Return what to show where several speak and no camera fits."""
        want = rules.get("on_together") or SHOT_WIDE
        if want == SHOT_HOLD:
            return None
        if want == SHOT_LISTENER:
            return next_speaker_camera(t, per_camera, None) or wide_shot
        if want == SHOT_ALTERNATE:
            row = sorted({camera_of.get(n) for n in active
                          if camera_of.get(n)}) or [wide_shot]
            choice = row[len(turns) % len(row)]
            turns.append(choice)
            return choice
        return wide_shot

    raw = []
    for a, b in zip(edges, edges[1:]):
        if b - a <= 1e-6:
            continue
        middle = (a + b) / 2.0
        active = [n for n, segs in long for s0, s1 in segs if s0 <= middle < s1]
        heap = [n for n in active if n in stray]
        strong = [n for n in active if n not in stray
                  and not too_short.get(camera_of.get(n), lambda _t: False)(
                      middle)]
        if not active:
            who = wide_shot          # silence -> wide shot
        elif restless(middle) or (heap and not strong):
            who = unsure_picture(middle, active)
        elif not strong:
            who = None               # nobody held the floor long enough
        elif len(strong) == 1:
            who = camera_of.get(strong[0]) or wide_shot
        else:
            who = common_camera(strong) or together_picture(middle, strong)
        raw.append([a, b, who, tuple(sorted(active))])

    # "Hold" means the picture does not change, so the block takes the
    # camera of the one before it -- or of the one after, at the start.
    for i in range(len(raw)):
        if raw[i][2] is None:
            raw[i][2] = raw[i - 1][2] if i else None
    for i in range(len(raw) - 1, -1, -1):
        if raw[i][2] is None:
            raw[i][2] = raw[i + 1][2] if i + 1 < len(raw) else wide_shot

    # Lead-in: switch to the coming camera shortly before the entry. Given
    # as a negative value it becomes a lag, and the cut arrives after the
    # audio. Resolve does it that way ("Edit Change Delay", default
    # 0.30 s); the craft rule says the opposite, hence adjustable.
    #
    # The edge moves, not the shot: both edges of a shot move by the same
    # amount, otherwise shifting would shorten it.
    answers = {}
    if (rules.get("on_question") or SHOT_OFF) != SHOT_OFF and words:
        answers = reaction_cuts(
            long, words, camera_of or {},
            float(rules.get("reaction_gap") or 3.0),
            float(rules.get("reaction_hold") or 0.0),
            float(rules.get("reaction_over") or 0.0))
    lead = float(rules.get("reaction_lead") or 0.0)
    if (lead_in or answers) and raw:
        limits = [r[0] for r in raw] + [raw[-1][1]]
        end = limits[-1]
        brought = []
        for i in range(1, len(raw)):
            if raw[i][2] == raw[i - 1][2]:
                continue
            who = answers.get(round(raw[i][0], 6))
            if who is None:
                for when in answers:
                    if abs(when - raw[i][0]) < 1e-6:
                        who = answers[when]
                        break
            early = (who is not None and lead > 0
                     and raw[i][2] == (camera_of or {}).get(who))
            if early and (rules.get("on_question") == SHOT_LISTENER
                          and not next_speaker_camera(
                              raw[i][0] - lead, per_camera, raw[i - 1][2])):
                early = False
            if early:
                # The point comes from the sound alone: the target sits
                # inside the breath after the question, not on a
                # boundary in the text. And the edge is set here, so the
                # Edit Change Delay is not added to it a second time.
                limits[i] = min(end, max(0.0, cut_point(
                    raw[i][0] - lead, (), (), levels, step)))
                brought.append(i)
            elif lead_in:
                limits[i] = min(end, limits[i] - lead_in)
        # A reaction cut reaches back over the pause after the question,
        # and the wide shot standing in that pause goes with it -- else
        # the edge before it would push the reaction back where it was.
        for i in brought:
            for j in range(i - 1, 0, -1):
                if limits[j] <= limits[i]:
                    break
                limits[j] = limits[i]
        # No edge may end up before the previous one.
        for i in range(1, len(limits)):
            if limits[i] < limits[i - 1]:
                limits[i] = limits[i - 1]
        for i in range(len(raw)):
            raw[i][0], raw[i][1] = limits[i], limits[i + 1]
        raw = [r for r in raw if r[1] - r[0] > 1e-6]

    # A short silence between two identical shots is not noticeable.
    extra = []
    for r in raw:
        if extra and extra[-1][2] == r[2]:
            extra[-1][1] = r[1]
        else:
            extra.append(list(r))

    return [tuple(r) for r in merge_short_shots(extra, min_len)]


def shot_key(row):
    """What makes two neighbouring shots the same shot: the camera."""
    return row[2]


def split_shots_by_speaker(cut, tracks, min_len=MIN_EDIT_DURATION_S):
    """Cut every shot again where the speech changes hands.

    For the case where one camera shows everybody: the camera cut is
    then one long shot, and Resolve gets a single clip that cannot be
    grouped, coloured or zoomed per speaker. The picture does not
    change -- the same camera runs throughout -- only the shot
    boundaries now sit where the speaker changes, and each piece
    carries the name of whoever is talking.

    Returns [(from, to, camera, speakers)]. Pieces shorter than
    *min_len* are merged back, so an interjection makes no shot.
    """
    if not cut:
        return []
    edges = sorted({t for _n, segs in tracks for s in segs for t in s})
    key = lambda r: (r[2], r[3])
    out = []
    for a, b, who in cut:
        # Merged inside this shot and not across it: the camera edges
        # were placed by the Edit Change Delay, and a piece pulled over
        # one of them would move the picture as well as the name.
        pieces = []
        inside = [t for t in edges if a < t < b]
        for x, y in zip([a] + inside, inside + [b]):
            if y - x <= 1e-6:
                continue
            middle = (x + y) / 2.0
            talking = tuple(sorted(
                n for n, segs in tracks
                for s0, s1 in segs if s0 <= middle < s1))
            if pieces and pieces[-1][3] == talking:
                pieces[-1][1] = y
            else:
                pieces.append([x, y, who, talking])
        out += merge_short_shots(pieces, min_len, key)
    joined = []
    for r in out:
        if joined and key(joined[-1]) == key(r):
            joined[-1][1] = r[1]
        else:
            joined.append(list(r))
    return [tuple(r) for r in joined]


def one_camera_only(camera_of):
    """Report whether every speaker sits on the same camera.

    Then the camera says nothing about who is talking, and the cut has
    to come from the speech instead.
    """
    seen = {c for c in (camera_of or {}).values() if c}
    return len(seen) <= 1


def merge_short_shots(cut, min_len, key=shot_key):
    """Merge shots below the minimum duration into the following one.

    Same rule as Resolve's Minimum Edit Duration. It has to run again
    after every other step, because the wide shot at the edges and the
    inserted wide shots can both leave short remnants.

    Forwards, not backwards: merging back gives the time to whoever has
    just finished, merging forward to whoever is about to speak. Where
    the recognition is finely chopped the second one is nearly always
    right -- measured against a hand-made edit, wrong picture time falls
    by a factor of five to eight, and it falls just as far when the
    truth itself goes in. The last shot has nothing after it and falls
    back into the one before.

    *key* says when two neighbours are the same shot. By default that is
    the camera; where one camera shows everybody it is the camera and
    the speaker together, so the cut stays at the change of speaker.
    """
    if min_len <= 0 or not cut:
        return list(cut)
    extra = [list(x) for x in cut]
    i = 0
    while i < len(extra) and len(extra) > 1:
        if extra[i][1] - extra[i][0] >= min_len:
            i += 1
            continue
        if i + 1 < len(extra):
            extra[i + 1][0] = extra[i][0]
            del extra[i]
        else:
            extra[i - 1][1] = extra[i][1]
            del extra[i]
            i -= 1
        # The neighbours may now be the same shot, and two of those in a
        # row would leave a cut where the picture does not change.
        j = max(0, i - 1)
        while j + 1 < len(extra) and key(extra[j]) == key(extra[j + 1]):
            extra[j][1] = extra[j + 1][1]
            del extra[j + 1]
        i = max(0, i - 1)
    return extra


def write_edl(file_path, title, segments, tc0, fps):
    """Write segments as an EDL; Resolve imports it as timeline markers."""
    with open(file_path, "w", encoding="utf-8") as f:
        f.write("TITLE: %s\nFCM: NON-DROP FRAME\n\n" % title)
        for i, (a, b, name) in enumerate(segments, 1):
            t0, t1 = timecode_string(tc0 + a, fps), timecode_string(tc0 + b, fps)
            f.write("%03d  AX       A     C        %s %s %s %s\n"
                    % (i, t0, t1, t0, t1))
            f.write("* FROM CLIP NAME: %s\n\n" % name)


ASK_SINK = None   # set by the GUI: callable(options, title) -> key


def ask_choice(possible, heading, title=T('Question'), default_value=None,
               switch="--auphonic-resume"):
    """Ask a question -- in the terminal, in the GUI or via a switch.

    *options* is a list of (key, text) and the key is returned. *switch* is
    the command line switch that preselects the answer; it appears in the
    error message when nobody is there to answer.
    """
    print("\n  %s" % heading)
    for i, (_, text) in enumerate(possible, 1):
        print("    %d  %s" % (i, text))
    api_key = [k for k, _ in possible]

    def write_out(label, choice):
        """Show the visible text rather than the internal key."""
        for i, (k, text) in enumerate(possible, 1):
            if k == choice:
                print("  %s: %d  %s" % (label, i, text.split("\n")[0]))
                return
        print("  %s: %s" % (label, choice))

    if default_value in api_key:
        write_out(T('Given'), default_value)
        return default_value
    if ASK_SINK is not None:
        choice = ASK_SINK(possible, title)
        write_out(T('Chosen'), choice)
        return choice
    if not sys.stdin.isatty():
        raise RuntimeError(
            T('No input possible. Use %s %s to set what should happen.') % (switch, "|".join(api_key)))
    while True:
        answer = input(T('  Number: ')).strip()
        if answer.isdigit() and 1 <= int(answer) <= len(possible):
            write_out(T('Chosen'), possible[int(answer) - 1][0])
            return possible[int(answer) - 1][0]
        print(T('  Please give a number between 1 and %d.') % len(possible))


def ask_reuse_production(complete, has_result, default_value=None, missing=()):
    """Ask what should happen to the existing production."""
    possible = []
    # Reuse is only offered where everything needed is there: without
    # the statistics there would be no camera cut.
    if has_result and not missing:
        possible.append(("result", T('take the existing result (nothing '
                                     'computed, nothing paid)')))
    if complete:
        possible.append(("rerun", T('recompute with the chosen preset -- '
                                    'the files stay\n       where they are, '
                                    'costs no credit')))
    possible.append(("upload", T('upload everything again and recompute -- '
                                 'this costs credit')))
    possible.append(("abort", T('cancel')))
    return ask_choice(possible, T('What should happen with it?'),
                      T('This production already exists'), default_value)


def rename_tracks(tracks, names, request, new_one):
    """Rename the speakers to the track names used by the production.

    Matching goes by position. The rename applies everywhere: to the tracks
    themselves -- which later drive file names, statistics and camera
    assignment -- and to the request sent to Auphonic.
    """
    for track, old, fresh in zip(tracks, list(names), new_one):
        print("    %-22s -> %s" % (old, fresh))
        track["name"] = fresh
    names[:] = list(new_one)
    for entry, fresh in zip(request.get("multi_input_files") or [], new_one):
        entry["id"] = fresh


def ask_track_names(old, fresh, default_value=None):
    """Ask what to do when the production uses different track names."""
    print(T('\n  The tracks are named differently there:'))
    for i, name in enumerate(fresh, 1):
        print(T('    Track %d  %-22s (here: %s)')
              % (i, name, old[i - 1] if i <= len(old) else "--"))
    if len(old) != len(fresh):
        print(T('  There are %d tracks there and %d here -- that does not '
                'match.') % (len(fresh), len(old)))
        possible = [("upload", T('upload everything again and recompute -- '
                                 'this costs credit')),
                    ("abort", T('cancel'))]
    else:
        possible = [("adopt", T('take the names from there and carry on '
                                'with them --\n       no upload, costs '
                                'nothing')),
                    ("upload", T('keep our names and upload everything '
                                 'again -- this costs\n       credit')),
                    ("abort", T('cancel'))]
    return ask_choice(possible, T('What should happen with it?'),
                      T('Different track names'), default_value)


def reuse_production(key, existing, request, preset, tracks,
                               names, target_folder, base, wait_s, carry_on):
    """Reuse a production that already exists.

    Only the upload costs credit, not the computation. Trying different
    presets therefore means leaving the files in place and recomputing.
    """
    print(T('\n  THERE IS ALREADY A PRODUCTION WITH THIS NAME'))
    complete, has_result, missing = print_production(existing)
    # "reuse" answers the second question; for the first it means
    # "recompute, upload nothing".
    choice = ask_reuse_production(complete, has_result,
                            "rerun" if carry_on == "adopt" else carry_on,
                            missing)
    uuid = existing.get("uuid")
    if choice == "abort":
        raise RuntimeError(
            T('Stopped. Choose another production name -- then a new '
              'production\n  is created -- or pick one of the other options.'))

    if choice == "rerun" and not complete:
        raise RuntimeError(
            T('Files are missing there -- without a new upload nothing can '
              'be computed.\n  With --auphonic-resume upload the script '
              'uploads again; this costs credit.'))
    upload_again = (choice == "upload")
    if not upload_again:
        # There the tracks are named as they were on upload, the result files
        # in the ZIP are named after that, and Auphonic matches the files
        # through it. Where the names differ we either adopt theirs, which
        # costs nothing, or upload again. We never upload unasked.
        there = [x.get("id") for x in
                (existing.get("multi_input_files") or [])]
        if sorted(there) != sorted(names):
            second = ask_track_names(list(names), there, carry_on)
            if second == "abort":
                raise RuntimeError(
                    T('Stopped. Nothing was uploaded and nothing computed.'))
            if second == "adopt":
                print(T('  The names from there are adopted:'))
                rename_tracks(tracks, names, request, there)
            else:
                upload_again = True
                choice = "upload"

    if choice == "result":
        if not has_result:
            raise RuntimeError(T('This production has no result yet.'))
        if missing:
            raise RuntimeError(
                T('The existing result is unusable: %s is missing there. '
                  'With --auphonic-resume rerun it can be recomputed '
                  'without uploading anything.') % T(' and ').join(missing))
        print(T('  Existing result adopted -- nothing computed, nothing paid.'))
        p = (_parse_json(_curl_call(key, [AUPHONIC + "/api/production/%s.json" % uuid]))
             .get("data") or {})
        return download_results(key, p, names, target_folder, base)

    if not upload_again:
        print(T('  Note: this computes with the files uploaded at the '
                'time. They carry\n  the time window and the alignment of '
                'that day. Where the In point, the Out point\n  or the '
                'measured '
                'position differ now, the return check measures the\n  '
                'difference and moves the tracks into place.'))
    print(T('  Settings brought to preset %r')
          % (preset.get("preset_name") or "?"))
    change = dict(request)
    if not upload_again:
        # The track list stays out here. Auphonic appends it on update instead
        # of matching it -- three tracks became six, the second three without
        # a file. The tracks follow individually in a moment, each through its
        # own URL; only that way are they matched.
        change.pop("multi_input_files", None)
        change.pop("is_multitrack", None)
        # The same goes for the output files: what is already there must not
        # come along again, or Auphonic computes it twice.
        absent_ones = missing_outputs(existing.get("output_files"),
                                     request.get("output_files") or [])
        if absent_ones:
            change["output_files"] = absent_ones
            print(T('  Added: %s')
                  % ", ".join(str(e.get("format")) for e in absent_ones))
        else:
            change.pop("output_files", None)
            print(T('  All needed output files already exist.'))
        left_over = [t.get("id") for t in (existing.get("multi_input_files")
                                        or []) if t.get("id") not in names]
        if left_over:
            print(as_warn(T('  Caution: the production holds further '
                            'tracks (%s). They go into the\n  mix -- please '
                            'delete them at auphonic.com.') % ", ".join(str(u) for u in left_over)))
    update_production(key, uuid, change)
    if not upload_again:
        # The track list could not go above, since the production appends it.
        # Each track through its own URL does work.
        changed, same, bad = update_all_tracks(
            key, uuid, request.get("multi_input_files") or [], existing)
        parts = []
        if changed:
            parts.append(T('%d brought to the preset') % len(changed))
        if same:
            parts.append(T('%d were already right') % len(same))
        print(T('  Tracks: %s') % (", ".join(parts) or T('nothing to do')))
        for line in bad:
            print(as_warn(T('  Caution: track %s -- it keeps its settings.') % line))
        after = read_production(key, uuid)
        now = after.get("multi_input_files") or []
        if len(now) > len(existing.get("multi_input_files") or []):
            raise RuntimeError(
                T('Tracks were added while changing (now %d). That makes '
                  'the mix\n  wrong. Please delete the tracks without a '
                  'file at auphonic.com.') % len(now))
    if upload_again:
        print(T('  The files are uploaded again -- this costs credit.'))
        upload_args = ["-X", "POST",
                AUPHONIC + "/api/production/%s/upload.json" % uuid]
        for track in tracks:
            upload_args += ["-F", "%s=@%s" % (track["name"], track["axis"])]
        d = _parse_json(_curl_call(key, upload_args,
                        progress=T('Uploading %d tracks') % len(tracks)))
        absent = [x.get("id") for x in ((d.get("data") or {}).get(
            "multi_input_files") or []) if not x.get("input_file")]
        if absent:
            raise RuntimeError(T('These tracks got no file: %s')
                               % ", ".join(absent))
    else:
        print(T('  The existing files are reused -- recomputing costs nothing.'))
    _curl_call(key, ["-X", "POST",
                AUPHONIC + "/api/production/%s/start.json" % uuid])
    p = wait_for_production(key, uuid, wait_s)
    return download_results(key, p, names, target_folder, base)


def wait_for_production(key, uuid, wait_s):
    """Wait for the production to finish, with a progress bar and a timeout."""
    started = time.time()
    end = started + wait_s
    horizon = 150.0
    print(T('  Time limit: %s') % as_hms(wait_s))
    while time.time() < end:
        d = _parse_json(_curl_call(key, [AUPHONIC + "/api/production/%s.json" % uuid]))
        p = d.get("data") or {}
        status, text = p.get("status"), p.get("status_string") or "?"
        if status == 3:
            sys.stdout.write(T('\r  [%-30s] 100 %%  %s  done%s\n')
                             % ("#" * 30, as_hms(time.time() - started), " " * 20))
            return p
        if status == 2:
            raise RuntimeError(T('Auphonic reports an error: %s')
                               % (p.get("error_message") or text))
        for _ in range(5):
            elapsed = time.time() - started
            while elapsed >= horizon:
                horizon *= 2
            share = min(0.99, elapsed / horizon)
            sys.stdout.write("\r  [%-30s] %3.0f %%  %s  %s        "
                             % ("#" * int(share * 30), share * 100,
                                as_hms(elapsed), text))
            sys.stdout.flush()
            if time.time() >= end:
                break
            time.sleep(2)
    raise RuntimeError(T('Time limit of %s reached, production still '
                         'running: %s/engine/status/%s') % (as_hms(wait_s), AUPHONIC, uuid))


def tracks_folder(folder, create=True):
    """Return the folder with the tracks and everything else from Auphonic."""
    target = os.path.join(folder, "auphonic-tracks")
    if create:
        os.makedirs(target, exist_ok=True)
    return target


def match_zip_entries_to_tracks(zip_file_path, names, target_folder):
    """Unpack the ZIP and match its files to the track names.

    Auphonic does not guarantee how it names the files in the ZIP, so no
    name is assumed; the closest match is used.
    """
    import zipfile
    folder = tracks_folder(target_folder)
    with zipfile.ZipFile(zip_file_path) as zf:
        files = [n for n in zf.namelist()
                   if not n.endswith("/") and not os.path.basename(n).startswith(".")]
        zf.extractall(folder)
    assignment, pending = {}, list(files)
    print(T('  In the archive: %s') % ", ".join(os.path.basename(d) for d in files))
    try:
        # Once unpacked the ZIP is no longer needed.
        os.unlink(zip_file_path)
    except OSError:
        pass
    for name in names:
        if not pending:
            break
        best = max(pending, key=lambda d: similarity(name,
                                                  os.path.splitext(
                                                      os.path.basename(d))[0]))
        quality = similarity(name, os.path.splitext(os.path.basename(best))[0])
        if name.lower() in os.path.basename(best).lower() or quality > 0.4:
            assignment[name] = os.path.join(folder, best)
            pending.remove(best)
            print("    %-20s <- %s" % (name, os.path.basename(best)))
        else:
            print(T('    %-20s <- nothing suitable found') % name)
    return assignment


def write_camera_file(video, info, audio_tracks, target, a, b, drift, args,
                 head_s=0, tail_s=0):
    """Write a new video file carrying several audio tracks.

    *audio_tracks* is a list of (name, path). They all sit on the same axis
    and therefore get the same offset and clock correction, so they stay as
    precisely aligned to each other as they were.

    *head_s* and *tail_s* trim samples from the front and back before the
    offset is applied; the simple path needs this when the audio runs past
    the video.
    """
    n_video = int(round(info["duration"] * SR))
    if drift and abs(b - 1.0) > 1e-7:
        intro = rate_filter_chain(b) + ","
        k = int(round(a / b * SR))
    else:
        intro, k = "", int(round(a * SR))
    cut = ("atrim=start_sample=%d,asetpts=N/SR/TB," % k) if k > 0 else\
              ("adelay=delays=%dS:all=1," % (-k)) if k < 0 else ""
    cmd = ["ffmpeg", "-v", "warning", "-nostats", "-i", video]
    chains, map_args = [], ["-map", "0:v"]
    for i, (_, file_path) in enumerate(audio_tracks):
        cmd += ["-i", file_path]
        edge = ""
        if head_s or tail_s:
            edge = ("atrim=start_sample=%d:end_sample=%d,asetpts=N/SR/TB,"
                    % (head_s, sample_count(file_path) - tail_s))
        chains.append("[%d:a]%s%s%sapad=whole_len=%d,atrim=end_sample=%d,"
                      "asetpts=N/SR/TB[t%d]"
                      % (i + 1, edge, intro, cut, n_video, n_video, i))
        map_args += ["-map", "[t%d]" % i]
    n_camera = 0
    if not args.no_camera_audio:
        for i in range(len(info["audio"])):
            map_args += ["-map", "0:a:%d" % i]
        n_camera = len(info["audio"])
    cmd += ["-filter_complex", ";".join(chains)] + map_args
    # write_colr:        without it ffmpeg writes no colr box at all and
    #                    the values live only in the bitstream.
    # use_metadata_tags: keep the QuickTime keys of the camera
    #                    (com.apple.*, com.blackmagic-design.*). Resolve
    #                    reads device and input colour space from them.
    cmd += ["-c:v", "copy"] + colour_arguments(video)
    cmd += ["-map_metadata", "0",
            "-movflags", "+write_colr+use_metadata_tags"]
    for i in range(len(audio_tracks)):
        cmd += ["-c:a:%d" % i, "pcm_s24le"]
    for i in range(n_camera):
        cmd += ["-c:a:%d" % (len(audio_tracks) + i), "copy"]
    for i, (name, _) in enumerate(audio_tracks):
        cmd += ["-metadata:s:a:%d" % i, "title=%s" % name,
                "-metadata:s:a:%d" % i, "handler_name=%s" % name,
                "-disposition:a:%d" % i, "default" if i == 0 else "0"]
        if args.speech_language:
            cmd += ["-metadata:s:a:%d" % i, "language=%s" % args.speech_language]
    for i in range(n_camera):
        nm = args.name_camera if n_camera == 1 else "%s %d" % (args.name_camera,
                                                               i + 1)
        j = len(audio_tracks) + i
        cmd += ["-metadata:s:a:%d" % j, "title=%s" % nm,
                "-metadata:s:a:%d" % j, "handler_name=%s" % nm,
                "-disposition:a:%d" % j, "0"]
        if args.speech_language_camera:
            cmd += ["-metadata:s:a:%d" % j, "language=%s" % args.speech_language_camera]
    if info["tc"]:
        cmd += ["-timecode", info["tc"]]
    cmd += ["-y", target]
    run_ffmpeg_with_progress(cmd, info["duration"],
                              T('Writing %s') % os.path.basename(target))


def measure_loudness(file_path, duration=None, text_progress_bar=None):
    """Measure programme loudness and true peak to EBU R128.

    Over an hour of audio this takes a while, so it runs with a progress
    bar.
    """
    cmd = ["ffmpeg", "-nostats", "-i", file_path, "-af", "ebur128=peak=true",
           "-f", "null", "-"]
    if not text_progress_bar:
        p = subprocess.run(cmd, capture_output=True)
        text = p.stderr.decode("utf-8", "replace")
    else:
        # ebur128 writes one line per second to stderr. Reading stdout line by
        # line and stderr only afterwards fills its buffer and both wait for
        # each other, so stderr goes to a file rather than a pipe.
        cmd = cmd[:1] + ["-progress", "pipe:1"] + cmd[1:]
        fd, log = tempfile.mkstemp(suffix=".txt")
        os.close(fd)
        try:
            with open(log, "wb") as f:
                proc = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=f)
                show_progress(text_progress_bar, 0.0)
                for line in proc.stdout:
                    share = progress_from_line(line, duration)
                    if share is not None:
                        show_progress(text_progress_bar, share)
                proc.wait()
            with open(log, "r", encoding="utf-8", errors="replace") as f:
                text = f.read()
        finally:
            try:
                os.unlink(log)
            except OSError:
                pass
        show_progress(text_progress_bar, 1.0)
        if OUTPUT_SINK:
            OUTPUT_SINK("\n")
        else:
            sys.stdout.write("\n")
    def get(label):
        hit = re.findall(label + r":\s*(-?\d+(?:\.\d+)?)", text)
        return float(hit[-1]) if hit else None
    # LRA comes from the same pass: the loudness range says how far quiet and
    # loud passages lie apart. For speech 3 to 7 LU is usual; below that it
    # sounds squashed.
    return get(r"I"), get(r"Peak"), get(r"LRA")


def remove_slow_level_drift(env, window=600):
    """Remove slow level changes from an envelope.

    Auphonic's adaptive leveler does what it is there for: it changes
    loudness over time. Comparing envelopes from before and after therefore
    looks like a different signal even though the onsets sit in the same
    places. Subtracting the moving average leaves the onsets and drops the
    level shaping. 600 steps is three seconds at a 5 ms grid.
    """
    if len(env) < window * 2:
        return env
    kernel = np.ones(window) / window
    return env - np.convolve(env, kernel, mode="same")


def refine_offset(axis, done, a, b, rate=16000, how_many=9):
    """Measure the remaining offset between upload and returned file.

    Envelopes bring the two together to within a few milliseconds; a 5 ms
    grid gives no more, and with few usable sample points it scatters into
    double digits. Here the same voice is compared directly in both files,
    which is accurate to a fraction of a sample.

    Where to measure is decided by level: the runtime is split into
    sections and the loudest second of each is used. Fixed positions do not
    work -- someone speaking five percent of the time is silent at almost
    any fixed spot.

    Returns how many milliseconds later the returned file sits, or None if
    nothing reliable could be measured.
    """
    try:
        coarse = np.asarray(decode_audio(axis, rate=4000), dtype=np.float64)
    except Exception:
        return None
    nb = 4000
    count = len(coarse) // nb
    if count < how_many:
        return None
    level = np.array([float(np.sqrt((coarse[k * nb:(k + 1) * nb] ** 2).mean()))
                      for k in range(count)])
    loud = float(np.percentile(level[level > 0], 90)) if (level > 0).any() \
        else 0.0
    if loud <= 0:
        return None
    spots = []
    for k in range(how_many):
        begins, until = count * k // how_many, count * (k + 1) // how_many
        if until <= begins:
            continue
        best = begins + int(np.argmax(level[begins:until]))
        if level[best] > loud * 0.3:
            spots.append(best)
    values = []
    for t in spots:
        try:
            x = decode_audio(axis, rate=rate, ss=max(0.0, t - 0.5), duration=2.0)
            y = decode_audio(done, rate=rate,
                           duration=2.0, ss=max(0.0, a + b * (t - 0.5)))
        except Exception:
            continue
        n = min(len(x), len(y))
        if n < rate:
            continue
        x = np.asarray(x[:n], dtype=np.float64)
        y = np.asarray(y[:n], dtype=np.float64)
        ms, sharpness = gcc_phat_offset(x, y, rate)
        if sharpness >= 10:
            values.append(ms)
    if len(values) < 3:
        return None
    return float(np.median(values))


def verify_returned_tracks(tracks, window_length2, tmpdir):   # noqa: C901
    """Check what Auphonic returns against what was uploaded.

    The service can prepend material -- a jingle on the free tier -- and
    change the length. Either would shift the tracks against each other and
    undo the alignment.

    Two things make this comparison harder than the others: de-bleeding
    removes the other speakers, and the leveler bends the levels. So the
    sample points are picked on the processed track, the envelopes are
    flattened first, and the estimate uses the median rather than a
    regression line, so one outlier cannot shift a whole track.
    """
    print(as_head(T('\nCHECK THE RETURN')))
    HOP, rate = 5.0, 4000
    shaky = []
    # A stereo track that comes back with one channel has been folded at
    # auphonic.com, and no later step can undo that. It is not an error --
    # the run carries on -- but it has to be said, because the difference
    # between the two microphones is then gone from the mix.
    folded = [track["name"] for track in tracks
              if track.get("done") and kept_channels(track["axis"]) == 2
              and kept_channels(track["done"]) == 1]
    if folded:
        print(as_warn(TN(len(folded),
                         '  %s went up in stereo and came back in one '
                         'channel.',
                         '  %s went up in stereo and came back in one '
                         'channel each.') % ", ".join(folded)))
        print(T('  auphonic.com folded them. The mix keeps the two '
                'channels; what is gone is the\n  difference between the '
                'two microphones of that track.'))
    for track in tracks:
        done = track.get("done")
        if not done:
            continue
        n_fresh = sample_count(done) / float(SR)
        try:
            env_old = remove_slow_level_drift(envelope(decode_audio(track["axis"], rate=rate),
                                         HOP, rate))
            env_fresh = remove_slow_level_drift(envelope(decode_audio(done, rate=rate),
                                         HOP, rate))
            # Pick the sample points on the processed track, not on the
            # uploaded one: after de-bleeding only one speaker is left, and
            # only where they speak is there anything to compare. One
            # comparison over the whole length would be dominated by the long
            # passages where the track is now empty.
            density = int(max(20, min(120, len(env_fresh) * HOP / 1000.0 / 30.0)))
            a_corr, b_corr, st = align_envelopes(env_old, env_fresh, HOP,
                                                sample_points=density,
                                                distance_s=30.0,
                                                points_off="audio")
        except Exception as e:
            print(T('  %-20s not measurable: %s') % (track["name"], e))
            if track.get("edge"):
                # Without a measurement only the computed edge is left.
                target = os.path.join(tmpdir,
                                    "ready_%s.wav" % safe_filename(track["name"]))
                track["ready"] = place_track_on_axis(done, target, track["edge"], 1.0,
                                              0.0, window_length2, drift=False)
            else:
                track["ready"] = done
            continue
        # Median rather than a regression line: Auphonic shifts a track as a
        # whole or not at all, so there is no slope to estimate here.
        offsets = st.get("offsets") or []
        times = st.get("times") or []
        clock_drift, clock_drift_ppm = 1.0, 0.0
        if offsets:
            v = np.array(offsets)
            a_corr = -float(np.median(v))
            spread = float(np.median(np.abs(v - np.median(v))) * 1000)
            # A returned file drifting against the uploaded one carries clock
            # drift. That happens when an older production is reused whose
            # tracks came from a run without drift correction, or with a
            # different one. A fixed offset is then not enough -- the tracks
            # drift apart, and towards the end the crossing voice is audible as
            # a second one.
            if len(v) >= 20 and len(times) == len(v):
                t = np.array(times)
                slope, axis = np.polyfit(t, v, 1)
                rest = v - (axis + slope * t)
                if (abs(slope) * 1e6 > 2.0
                        and float(np.std(rest) * 1000) < 30.0):
                    clock_drift = 1.0 / (1.0 + slope)
                    clock_drift_ppm = (clock_drift - 1.0) * 1e6
                    a_corr = -axis / (1.0 + slope)
                    spread = float(np.median(np.abs(rest)) * 1000)
        else:
            spread = st.get("spread_ms", 0.0)
        # Where the file was coarsely trimmed to a window set later, there is
        # deliberate slack at both ends, and the offset should be exactly that
        # slack. Measured again here on the voice itself rather than on the
        # envelope: envelopes get within a few milliseconds, which is too
        # coarse between tracks, where a second voice becomes audible from
        # about 20 ms.
        fine = refine_offset(track["axis"], done, a_corr, clock_drift)
        if fine is not None and abs(fine) < 500.0:
            a_corr += fine / 1000.0
        edge = track.get("edge", 0.0)
        ms = (a_corr - edge) * 1000.0
        # Record what was measured here for the metrics.
        track["drift_ppm"] = clock_drift_ppm
        track["offset_ms"] = ms
        track["residual_ms"] = spread
        length = n_fresh - 2 * edge - window_length2
        remark = ""
        if edge or abs(ms) > 5 or abs(length) > 0.05 or clock_drift_ppm:
            target = os.path.join(tmpdir, "ready_%s.wav" % safe_filename(track["name"]))
            place_track_on_axis(done, target, a_corr, clock_drift, 0.0, window_length2,
                           drift=bool(clock_drift_ppm))
            track["ready"] = target
            remark = (T('  -->  aligned, clock drift %+.1f ppm taken out') % clock_drift_ppm) if clock_drift_ppm \
                else T('  -->  aligned')
        else:
            track["ready"] = done
        uncertain = st.get("points", 0) < 5 or spread > 150.0
        line = (T('  %-20s offset %+.1f ms%s, length %+.3f s, spread %.0f '
                  'ms, %d of %d points%s%s')
                % (track["name"], ms,
                   "" if fine is None else T(' (fine: %+.1f ms)') % fine,
                   length, spread, st.get("points", 0),
                   st.get("candidates", 0), remark,
                   T('   Caution: measurement unusable') if uncertain else ""))
        print(as_warn(line) if uncertain else line)
        if uncertain:
            shaky.append(track["name"])
    if shaky:
        print(T('\n  For %s it could not be established whether the return '
                'matches the\n  upload. Better to stop than to write '
                'something wrong.') % ", ".join(shaky))
        return False
    return True


def find_master_file(*places):
    """Find the finished mixdown from auphonic.com, if it came along."""
    for place in places:
        if not place:
            continue
        for folder in (tracks_folder(place, create=False), place):
            try:
                names = sorted(os.listdir(folder))
            except OSError:
                continue
            for n in names:
                small = n.lower()
                if ("master" in small and small.endswith(".wav")
                        and not small.startswith("final_")):
                    return os.path.join(folder, n)
    return None


def normalise_loudness(tracks, target_lufs, tmpdir, master=None, channels=1):
    """Compute one common gain for all tracks.

    The sum is measured, not the single track, because only the sum is
    heard. The same gain goes on every track so the speakers keep the
    balance Auphonic set.

    If the finished mixdown from auphonic.com is present it is the yardstick:
    it is mixed from the same tracks and mastered to the preset target. Then
    the loudness of our own mix need not be guessed -- it matches that one.
    """
    print(as_head(T('\nNORMALISE')))
    after_yardstick = False
    if master and os.path.exists(master):
        m_have, m_peak, _m_lra = measure_loudness(master, None, T('Measuring the '
                                                                  'yardstick'))
        if m_have is not None:
            after_yardstick = True
            print(T('  Mixdown from auphonic.com: %.1f LUFS, peak %.1f '
                    'dBTP (%s)') % (m_have, m_peak if m_peak is not None else 0.0,
                            os.path.basename(master)))
            target_lufs = m_have
    total_sum = os.path.join(tmpdir, "measure_sum.wav")
    ready = [track["ready"] for track in tracks]
    # Measured in the form it is delivered in: a two channel mix sits a good
    # three decibels above the same mix as one track. A stereo track raises
    # the count on its own -- the mix it goes into has two channels, so the
    # measurement has to have them too.
    channels = max(channels, widest_track(ready))
    parts, chains, markers = [], [], []
    for i, path in enumerate(ready):
        parts += ["-i", path]
        chains.append("[%d:a]%s[m%d]"
                      % (i, channel_filter(kept_channels(path), channels), i))
        markers.append("[m%d]" % i)
    fc = ";".join(chains) + ";" + "".join(markers) +\
        "amix=inputs=%d:normalize=0[out]" % len(markers)
    duration = sample_count(tracks[0]["ready"]) / float(SR)
    run_ffmpeg_with_progress(
        ["ffmpeg", "-v", "error"] + parts + ["-filter_complex", fc,
         "-map", "[out]", "-c:a", "pcm_s24le", "-y", total_sum],
        duration, T('Building the sum'))
    have, peak, lra_range = measure_loudness(total_sum, duration, T('Measuring loudness'))
    if have is None:
        print(T('  Loudness not measurable -- it stays as it is.'))
        return 0.0, None
    gain = target_lufs - have
    print(T('  Sum of tracks:     %.1f LUFS, peak %.1f dBTP%s')
          % (have, peak if peak is not None else 0.0,
             T(', range %.1f LU') % lra_range if lra_range is not None else ""))
    print(T('  Target:            %.1f LUFS  ->  %+.1f dB on every track')
          % (target_lufs, gain))
    # Without a ceiling the gain would have to drop far enough for the loudest
    # peak to fit -- a single scraping chair can cost eight decibels. So the
    # gain stays and a limiter catches the peaks.
    if peak is not None and gain > CEILING_DBTP - peak:
        print(T('  Peaks:             %+.1f dB above %.1f dBTP -- the '
                'limiter catches them')
              % (peak + gain - CEILING_DBTP, CEILING_DBTP))
    # How much the limiter would have to take off is only known once the curve
    # is computed. Taking off more than a handful of decibels means not that
    # the peak does not fit the target but that the target does not fit the
    # material; then quieter beats squashed.
    curve, gone = limiter_curve(total_sum, tmpdir, gain)
    # With the finished mixdown from auphonic.com beside it the question is
    # answered: that is how much limiting auphonic.com itself needed to reach
    # this loudness from the same tracks, so nothing needs capping.
    limit = 12.0 if after_yardstick else LIMIT_MAX_DB
    if gone > limit + 0.05:
        back = gone - limit
        print(T('  Too much:          the limiter would have to take %.1f '
                'dB away. More than %.0f dB\n                     sounds '
                'squashed -- %.1f dB less gain.') % (gone, limit, back))
        gain -= back
        curve, gone = limiter_curve(total_sum, tmpdir, gain)
        print(T('  Remains:           %+.1f dB on every track, that is '
                '%.1f LUFS instead of %.1f') % (gain, have + gain,
                                   target_lufs))
    if gone > 0.05:
        print(T('  Limiter:           at most %.1f dB, the same curve on '
                'every track%s')
              % (gone, T(' (auphonic.com takes the same amount)')
                 if after_yardstick else ""))
    # For checking in the editor. -16 LUFS is the figure for web and podcast;
    # broadcast measures against -23, where the meter reads correspondingly
    # higher.
    print(T('  Result:            about %.1f LUFS, peak %.1f dBTP')
          % (have + gain, CEILING_DBTP if gone > 0.05
             else min(CEILING_DBTP, (peak or 0.0) + gain)))
    # The loudness range measures whether any dynamics are left. A limiter that
    # only catches peaks leaves it almost untouched; where it gets small,
    # something was squashed -- and then not by the limiter but by whatever was
    # done before.
    if lra_range is not None:
        if lra_range < 2.0:
            print(as_warn(T('  Caution: range      only %.1f LU -- very '
                            'tight. Speech is usually 3 to 7 LU;\n          '
                            '           below that it sounds squashed. '
                            'Check how strongly the leveler\n               '
                            '      is set at auphonic.com.') % lra_range))
        else:
            print(T('  Range:             %.1f LU (speech is usually 3 to '
                    '7 LU)') % lra_range)
    try:
        os.unlink(total_sum)
    except OSError:
        pass
    return gain, curve


def limiter_curve(total_sum, tmpdir, gain, ceiling=CEILING_DBTP):
    """Compute the limiter gain curve once, on the sum.

    The same curve is then applied to every single track. Only that way do
    the single tracks add up to exactly the mix again, since (a+b)*g equals
    a*g + b*g. A limiter per track would not: it follows its own level and
    would clamp the loud track harder than the quiet ones.

    Computed block by block: the peak of each 256 samples gives the gain
    that still fits under the ceiling. One block of lookahead applies it
    before the peak arrives, after which it returns with a time constant.
    Blocks are cross-faded linearly, otherwise it clicks. The audio streams
    through, so even an hour never has to fit in memory.

    Returns (path of the curve, maximum reduction in dB).
    """
    if np is None:
        return None, 0.0
    channels = max(1, channel_count(total_sum))
    limit = 10.0 ** (ceiling / 20.0)
    BLOCK = 256                       # 5.3 ms at 48 kHz
    RECOVERY = math.exp(-BLOCK / (SR * 0.050))    # 50 ms back up
    source = subprocess.Popen(
        ["ffmpeg", "-v", "error", "-i", total_sum,
         "-af", "volume=%.3fdB" % gain,
         "-f", "f32le", "-ac", str(channels), "-ar", str(SR), "-"],
        stdout=subprocess.PIPE)
    raw = os.path.join(tmpdir, "level_curve.raw")
    target = os.path.join(tmpdir, "level_curve.wav")
    smallest, status, rest, done = 1.0, 1.0, b"", False
    frame_bytes = 4 * channels
    try:
        with open(raw, "wb") as f:
            while not done:
                chunk = source.stdout.read(1 << 20)
                done = not chunk
                data = rest + chunk
                whole_blocks = len(data) // (frame_bytes * BLOCK)
                if not done:
                    # The last block waits for the next chunk: without it there
                    # would be no lookahead there and the peak would come
                    # through a tenth of a second early.
                    whole_blocks = max(0, whole_blocks - 1)
                    full = whole_blocks * frame_bytes * BLOCK
                else:
                    full = len(data) - len(data) % frame_bytes
                rest = data[full:]
                if full <= 0:
                    continue
                frames = np.frombuffer(data[:full],
                                       dtype="<f4").reshape(-1, channels)
                count = int(math.ceil(frames.shape[0] / float(BLOCK)))
                needed = np.ones(count, dtype=np.float64)
                for k in range(count):
                    piece = frames[k * BLOCK:(k + 1) * BLOCK]
                    peak = (float(np.max(np.abs(piece)))
                              if piece.size else 0.0)
                    if peak > limit:
                        needed[k] = limit / peak
                # One block of lookahead: the reduction is in place before the
                # peak.
                before = np.minimum(needed, np.roll(needed, -1))
                before[-1] = needed[-1]
                g = np.empty(frames.shape[0], dtype=np.float32)
                for k in range(count):
                    want = before[k]
                    if want > status:      # back up, but slowly
                        want = min(want, status * RECOVERY + (1.0 - RECOVERY))
                    a0 = k * BLOCK
                    a1 = min(frames.shape[0], a0 + BLOCK)
                    g[a0:a1] = np.linspace(status, want, a1 - a0,
                                           endpoint=False)
                    status = want
                    smallest = min(smallest, want)
                f.write((np.repeat(g, channels) if channels > 1 else g)
                        .astype("<f4").tobytes())
    except Exception as e:
        print(T('  Level curve not possible (%s) -- without limiter') % e)
        return None, 0.0
    finally:
        try:
            source.stdout.close()
            source.wait(timeout=30)
        except Exception:
            pass
    gone = -20.0 * math.log10(max(1e-6, smallest))
    if gone <= 0.001:
        try:
            os.unlink(raw)
        except OSError:
            pass
        return None, 0.0
    try:
        subprocess.run(["ffmpeg", "-v", "error", "-f", "f32le",
                        "-ar", str(SR), "-ac", str(channels), "-i", raw,
                        "-c:a", "pcm_f32le", "-y", target], check=True)
        os.unlink(raw)
    except Exception as e:
        print(T('  Level curve not possible (%s) -- without limiter') % e)
        return None, 0.0
    return target, gone


def channel_count(file_path):
    """Return the channel count of a file."""
    return probe_remember("channels", file_path,
                          lambda: _channel_count(file_path))


def kept_channels(file_path):
    """How many channels a track keeps on its way through: one or two.

    A stereo track is stereo because two microphones stand apart, and that
    difference is the whole point of it. Folding it to one channel throws
    the difference away, and no later step can put it back. So the rule is
    "keep what the source has" rather than "make everything mono".

    More than two channels is not a track but a recorder file. Those are cut
    into tracks before they get here; anything that still arrives with more
    is folded rather than passed on, because a video track with six channels
    helps nobody.
    """
    try:
        return 2 if channel_count(file_path) == 2 else 1
    except Exception:
        return 1


def channel_filter(have, want):
    """The filter that brings *have* channels to *want*, without a level jump.

    Both directions are written out rather than left to ffmpeg, because
    ffmpeg's own conversion uses an equal-power law: measured on a signal at
    -24.08 dB, one channel to two comes out at -27.09, and two channels to
    one at -21.07. Three decibels down or three decibels up, inaudible in a
    single listen and wrong in every meter.

    Worse, the second one depends on the output format. Writing integers,
    ffmpeg scales the matrix down so the sum cannot clip and the level comes
    out right after all; writing floats -- which is what happens inside a
    filter graph -- it does not. So the same call is correct in one place
    and 3 dB out in the next, which is exactly the kind of thing that is
    never noticed.

    Here one channel to two is a copy, and two to one is a half-and-half
    sum. Both keep the level of a centred signal exactly, in every format.
    """
    if have == want:
        return "anull"
    if want == 2:
        return "pan=stereo|c0=c0|c1=c0"
    return "pan=mono|c0=0.5*c0+0.5*c1"


def widest_track(paths):
    """Two if any of these files is stereo, otherwise one."""
    return max([1] + [kept_channels(p) for p in paths])


def _channel_count(file_path):
    try:
        a = next((x for x in ffprobe_json(file_path).get("streams", [])
                  if x.get("codec_type") == "audio"), {})
        return int(a.get("channels") or 1)
    except Exception:
        return 1


def how_many_processors():
    """How many processors this process may actually use.

    os.cpu_count() counts what the machine has, which is not the same
    thing: a container or a taskset can hold the process to two of
    thirty-two, and sizing a pool by the thirty-two means thirty threads
    taking turns. process_cpu_count answers the real question and
    arrived in Python 3.13, so the older one stays as the fallback.
    """
    ask = getattr(os, "process_cpu_count", None) or os.cpu_count
    try:
        return max(1, int(ask() or 2))
    except Exception:
        return 2


def python_note():
    """One line about the Python this is running on, for the log.

    Said rather than assumed: a report that opens with the version it ran
    under saves the first three questions when something behaves oddly.
    """
    now = "%d.%d.%d" % sys.version_info[:3]
    if now == LIKES_PYTHON:
        return "Python %s" % now
    return "Python %s  (recommended version %s)" % (now, LIKES_PYTHON)


def prework_weight(file_path, task):
    """How much of the bar a piece of prework is worth.

    Pulling the audio out of an hour of 4K and reading a wav file are
    one step each. Giving them the same share would make the bar say
    nothing: it would stand still through the long one and jump through
    the short ones.
    """
    video = os.path.splitext(file_path)[1].lower() in VIDEO_SUFFIXES
    if task == "audio":
        return 8.0 if video else 2.0
    if task == "channels":
        return 6.0 if video else 1.5
    if task == "split":
        return 4.0 if video else 2.0
    return 6.0 if video else 1.0


def parallel_map(items, work, workers=None):
    """Run *work* over all *items* at once; answers come back in order.

    Threads rather than processes: everything this is used for waits on
    ffmpeg or on numpy, and both let other threads run while they do.
    Where a thread cannot be started the rest is worked through here --
    failing to parallelise then costs speed and nothing else.

    An error inside the work is raised after all of it is done, so one
    unreadable file does not leave threads running behind a traceback.
    """
    items = list(items)
    if len(items) < 2:
        return [work(x) for x in items]
    if workers is None:
        workers = max(2, min(8, how_many_processors()))
    out = [None] * len(items)
    todo = list(range(len(items)))
    trouble = []

    def work_loop():
        while True:
            try:
                i = todo.pop()
            except IndexError:
                return
            try:
                out[i] = work(items[i])
            except BaseException as e:      # noqa: BLE001 -- passed on below
                trouble.append(e)

    threads = []
    for _ in range(max(1, min(workers, len(items)))):
        thread = threading.Thread(target=work_loop, daemon=True)
        try:
            thread.start()
        except Exception:
            break
        threads.append(thread)
    for thread in threads:
        try:
            thread.join()
        except Exception:
            pass
    work_loop()             # whatever no thread got to
    if trouble:
        raise trouble[0]
    return out


def probe_warm(paths, workers=None):
    """Ask about several files at once, so the answers are there later.

    Everything the interface wants to know about a file before it can
    draw a row -- length, timecode, channels, frame rate -- is measured
    here in parallel. Afterwards the rows are built from memory. Asked
    one after another on an external volume this is the difference
    between a window that stands still for minutes and one that does
    not.
    """
    todo = [p for p in dict.fromkeys(paths) if p and os.path.exists(p)]
    if len(todo) < 2:
        return

    def one(file_path):
        work = [lambda: ffprobe_json(file_path),
                lambda: channel_count(file_path)]
        if os.path.splitext(file_path)[1].lower() in AUDIO_SUFFIXES:
            work += [lambda: sample_count(file_path),
                     lambda: bext_time_reference(file_path)]
        for task in work:
            try:
                task()
            except Exception:
                # A file that cannot be measured is reported where its
                # row is drawn. Here it must not stop the rest.
                pass

    parallel_map(todo, one, workers)


# A channel counts as silent when it stays this far under the loudest
# channel of the same file. A recorder writes four channels whether or
# not anything was plugged in, and an empty one must not become a
# speaker.
SILENT_BELOW_DB = 45.0
# Absolute floor for a channel that carries anything at all. Under this
# there is only the noise floor of the converter. Found by measuring: two
# excerpts of the same recording read the same pairs differently, because
# at -85 dBFS the judgement was comparing dither.
QUIET_BELOW_DBFS = -70.0

# Two channels count as the same signal from here up. Mono panned to
# both sides gives exactly 1.0; a hair less allows for lossy coding.
SAME_SIGNAL = 0.999

# How far off zero a shared sound may arrive and still count as coming
# through one pair of microphones. Sound travels 34 cm in a
# millisecond, so this covers every usual stereo spacing: coincident
# X-Y gives 0, ORTF at 17 cm gives 0.5 ms, a 30 cm pair 0.87 ms. Two
# clip-on microphones on two people half a metre apart already give
# 1.2 ms, at a metre 2.9 ms.
PAIR_DELAY_MS = 1.0

# This much of the strongest common component has to sit inside that
# window for the two channels to be one pair. Measured on built cases:
# every stereo technique up to 30 cm scores 1.00, two clip-ons score
# 0.10 to 0.17. Nothing lands near the middle.
PAIR_AT_ZERO = 0.5

# Two more legs under the same judgement, both added after a measurement
# on a 32-channel drum recording where the share alone said "stereo"
# eight times and was wrong every time.
#
# The share says the two channels hear the same thing at the same
# moment. In one room, every microphone does that -- they all hear the
# same drum. So the share alone cannot tell a pair from a neighbour.
#
# First leg: the spacing that comes out of the same measurement has to
# be small. A pair measured 4 m apart is not a stereo pair, whatever the
# share says; that was the plainest contradiction in the log.
PAIR_APART_METRES = 0.3

# Second leg: a pair has to stand out from the two pairs that share a
# channel with it. On that recording the offset pairs -- the ones that
# run across every pair boundary -- scored as high as the pairs
# themselves (4+5 at 0.78 against 3+4 at 0.68). A real pair beats its
# neighbours; where nothing stands out, nothing is proposed.
PAIR_STANDS_OUT = 0.15

# The delay is measured on this many places spread over the file. More
# does not change the figure; on an hour of audio it would only cost
# time while somebody waits for the file list.
PAIR_PLACES = 120


def channel_rate(file_path, channels, want=16000):
    """Pick a working rate that fits the file in memory.

    16 kHz gives the delay measurement a resolution of a sixteenth of a
    millisecond, which is what it wants. An hour of four channels at
    that rate is a gigabyte, though, so a long or wide file is read
    more coarsely. Halving the rate halves the resolution; at 8 kHz a
    millisecond is still eight samples.
    """
    try:
        seconds = float(ffprobe_json(file_path).get("format", {})
                        .get("duration") or 0.0)
    except Exception:
        seconds = 0.0
    while want > 4000 and seconds * max(1, channels) * want > 6e8:
        want //= 2
    return want


def channel_levels(file_path, rate=16000, stream=0):
    """Return each audio channel of one file on its own.

    One pass through ffmpeg, taken apart here. Asking per channel with a
    pan filter meant decoding the whole file again for every channel: a
    32 channel recording was read 32 times over. Whatever the file was --
    24 bit, float, some codec numpy has never heard of -- what comes out
    of ffmpeg is 32 bit floats, and nothing measured here needs more
    digits than that.

    Empty rows come back where ffmpeg failed: half a file read would be
    judged as if it were whole, and the answer is cached.
    """
    n = max(1, channel_count(file_path))
    # One pass, not one per channel. Asking ffmpeg for channel k with a
    # pan filter means decoding the whole file again for every channel:
    # a 32 channel recording was read 32 times over, and on a mixer file
    # that is most of the waiting. Everything comes out interleaved in
    # one pass and is taken apart here -- ffmpeg has already made it
    # f32le by then, whatever the file was.
    p = subprocess.Popen(
        ["ffmpeg", "-v", "error", "-i", file_path,
         "-map", "0:a:%d" % stream, "-ar", str(rate), "-f", "f32le", "-"],
        stdout=subprocess.PIPE, stderr=subprocess.DEVNULL)
    parts = [[] for _ in range(n)]
    rest = b""
    frame = 4 * n
    try:
        while True:
            # A block of whole frames at a time. Reading the lot into one
            # array first would double the memory of a long wide file.
            raw = p.stdout.read(frame * 65536)
            if not raw:
                break
            raw = rest + raw
            keep = len(raw) - (len(raw) % frame)
            rest = raw[keep:]
            if not keep:
                continue
            block = np.frombuffer(raw[:keep], dtype=np.float32).reshape(-1, n)
            for k in range(n):
                parts[k].append(np.ascontiguousarray(block[:, k]))
    finally:
        try:
            p.stdout.close()
        except OSError:
            pass
        # A reader that stopped early leaves ffmpeg writing into a pipe
        # nobody empties, and it would sit there for ever.
        try:
            p.wait(timeout=20)
        except Exception:
            p.kill()
            p.wait()
    if p.returncode:
        # Half a file read is worse than none: the judgement would be
        # made on the part that arrived and then stored under the file's
        # size and time, so it would never be measured again.
        return [np.zeros(0, dtype=np.float32) for _ in range(n)]
    # Joined one channel at a time, and each list of pieces dropped as
    # soon as it has been joined. Building them all first would hold the
    # whole recording twice -- which is what the chunked read is for.
    out = []
    for k in range(n):
        out.append(np.concatenate(parts[k]) if parts[k]
                   else np.zeros(0, dtype=np.float32))
        parts[k] = None
    return out


def channel_at_zero(first, second, rate, most=PAIR_PLACES, window=2048):
    """How much of what two channels share arrives at the same time.

    Two microphones on two people hear each other, but late: the
    neighbour's voice travels the distance between them first. One pair
    of microphones hears everything at nearly the same moment, whatever
    the level difference. So the question is not how alike the channels
    are but *when* what they have in common arrives.

    Returns (share, places, apart). *share* is the height of the
    correlation inside the zero window against its highest point
    anywhere, taken as the median over the places measured. 1.0 means
    everything shared arrives together, near 0 means the strongest
    thing they share is delayed. *places* says how many were usable;
    below a handful the figure means nothing. *apart* is the median
    delay in milliseconds where the peak lies outside the window, which
    is what says how far apart the two microphones stand.

    Plain correlation, not PHAT: with speech both channels fall silent
    together, and dividing by the magnitude turns those moments into a
    spike at zero delay that swamps the real peak.
    """
    width = min(len(first), len(second))
    if width < window * 2:
        return 0.0, 0, 0.0
    reach = max(4, int(0.020 * rate))
    close = max(1, int(PAIR_DELAY_MS * rate / 1000.0))
    top = max(float(np.abs(first).max()), float(np.abs(second).max()))
    if top <= 0:
        return 0.0, 0, 0.0
    gate = top * 10 ** (-30.0 / 20.0)
    n = 1 << int(math.ceil(math.log(window * 2, 2)))
    # Below this the two channels share nothing worth reading a delay
    # out of, and the highest point of the correlation is wherever the
    # noise happens to be tallest.
    shared_enough = 0.10
    out, away = [], []
    for i in np.linspace(0, width - window - 1, most).astype(int):
        a = first[i:i + window]
        b = second[i:i + window]
        if max(float(np.sqrt((a ** 2).mean())),
               float(np.sqrt((b ** 2).mean()))) < gate:
            continue
        a = a.astype(np.float64) - float(a.mean())
        b = b.astype(np.float64) - float(b.mean())
        size = math.sqrt(float((a ** 2).sum()) * float((b ** 2).sum()))
        if size <= 0:
            continue
        cc = np.fft.irfft(np.fft.rfft(a, n) * np.conj(np.fft.rfft(b, n)), n)
        band = np.abs(np.concatenate((cc[-reach:], cc[:reach + 1]))) / size
        highest = float(band.max())
        if highest < shared_enough:
            continue
        out.append(float(band[reach - close:reach + close + 1].max())
                   / highest)
        where = int(np.argmax(band)) - reach
        if abs(where) > close:
            away.append(abs(where) * 1000.0 / float(rate))
    if len(out) < 8:
        return 0.0, len(out), 0.0
    return (float(np.median(out)), len(out),
            float(np.median(away)) if away else 0.0)


def channel_facts(file_path, rate=None, stream=0):
    """Measure the channels of one file: how loud, how empty, how alike.

    *level* is the peak per channel in dBFS, -inf for a channel that
    holds nothing at all. *silent* marks the channels that stay far
    enough under the loudest one to be an unused recorder input.

    Every neighbouring pair is measured, not every second one: on a
    mixer, channels 2 and 3 can be the stereo pair just as well as 1 and
    2. So entry k of *pair_same* and *pair_zero* is about channels k and
    k+1, and the lists are one shorter than the channel count.
    *pair_same* is the waveform correlation, *pair_zero* how much of what
    the two share arrives at the same time. Those two are what
    channel_joins judges on.
    """
    if rate is None:
        rate = channel_rate(file_path, channel_count(file_path))
    try:
        rows = channel_levels(file_path, rate, stream)
    except Exception:
        rows = []
    n = len(rows)
    width = min((len(x) for x in rows), default=0)
    if not n or width < rate // 4:
        return {"channels": n, "level": [], "silent": [], "pair_same": [],
                "pair_zero": [], "pair_apart": [], "readable": False}
    rows = [x[:width] for x in rows]
    level = []
    for x in rows:
        top = float(np.percentile(np.abs(x), 99))
        level.append(20.0 * math.log10(top) if top > 0 else float("-inf"))
    highest = max(level)
    # Two rules, and a channel need fail only one. Relative: 45 dB under
    # the loudest is an input nobody plugged anything into. Absolute:
    # under -70 dBFS there is no signal, only the converter's noise, and
    # a pair judged on noise answers differently every time it is
    # measured. The absolute rule applies only where at least one channel
    # is above it, so a recording that is quiet all through is still
    # judged on the relative one.
    floor = QUIET_BELOW_DBFS if highest > QUIET_BELOW_DBFS else float("-inf")
    silent = [not (x > float("-inf"))
              or (highest - x) > SILENT_BELOW_DB or x < floor
              for x in level]
    pair_same, pair_zero, pair_apart = [], [], []
    for a in range(0, n - 1):
        b = a + 1
        if silent[a] or silent[b]:
            pair_same.append(None)
            pair_zero.append(None)
            pair_apart.append(None)
            continue
        with np.errstate(invalid="ignore"):
            r = np.corrcoef(rows[a], rows[b])[0, 1]
        pair_same.append(float(r) if np.isfinite(r) else None)
        share, places, apart = channel_at_zero(rows[a], rows[b], rate)
        pair_zero.append(share if places >= 8 else None)
        pair_apart.append(apart if places >= 8 else None)
    return {"channels": n, "level": level, "silent": silent,
            "pair_same": pair_same, "pair_zero": pair_zero,
            "pair_apart": pair_apart, "readable": True}


def channel_joins(facts):
    """Judge every pair of neighbours: could these two be one stereo track?

    One rule for any channel count, and every neighbour is asked, not
    every second one. On a mixer, channels 2 and 3 can be the pair just
    as well as 1 and 2 -- fixed pairs would ask the wrong question and
    get a confident wrong answer.

    Returns [(k, stereo, certain, reason)], one entry per pair, where k
    is the left channel. A channel can belong to only one pair; picking a
    set that does not overlap is channel_tracks' job.

    What decides is *when* the two channels hear the same thing, not
    how alike they are: level and correlation both fail on material
    with bleed, where the microphones are loud together most of the
    time. See channel_at_zero for what is measured and why.

    Where nothing can be measured no pair is proposed, because that
    error is visible -- two rows with the same content -- while the
    other one is not: two speakers in one track look like one speaker,
    and the camera cut is quietly wrong.
    """
    # Not seen by this: two recordings laid on a common time axis
    # before being put into one file. Aligning them removes the very
    # delay measured here, and the pair then looks like one.
    n = int(facts.get("channels") or 0)
    if not facts.get("readable") or n <= 1:
        return []
    silent = list(facts.get("silent") or [False] * n)
    same = list(facts.get("pair_same") or [])
    zero = list(facts.get("pair_zero") or [])
    apart = list(facts.get("pair_apart") or [])
    out = []
    for k in range(n - 1):
        r = same[k] if k < len(same) else None
        at_zero = zero[k] if k < len(zero) else None
        late = apart[k] if k < len(apart) else None
        # What belongs on a row in the file list is the answer, not the
        # arithmetic behind it. What was measured is in channel_at_zero.
        if silent[k] or silent[k + 1]:
            out.append((k, False, True,
                        T('Channel %d below the noise floor -- unused input')
                        % ((k + 2) if silent[k + 1] else (k + 1))))
        elif r is not None and r >= SAME_SIGNAL:
            out.append((k, True, True,
                        T('both channels identical -- mono laid on both '
                          'sides')))
        elif at_zero is not None and at_zero < PAIR_AT_ZERO:
            # 343 m/s: the delay is the spacing, and giving it in
            # metres is what lets anyone check the answer against the
            # room the recording was made in.
            out.append((k, False, True,
                        T('probably two microphones -- about %.1f m apart')
                        % ((late or 0.0) * 0.343)))
        elif at_zero is not None and at_zero >= PAIR_AT_ZERO:
            # The share is high enough. Two more questions before this
            # is called a pair, because the share alone answers "yes"
            # for every microphone in the same room.
            metres = (late or 0.0) * 0.343
            beside = [zero[j] for j in (k - 1, k + 1)
                      if 0 <= j < len(zero) and zero[j] is not None]
            if metres > PAIR_APART_METRES:
                # Measured apart, so not one place, however well the two
                # agree. Same wording as the plain two-microphone case:
                # it is the same finding, reached the long way round.
                out.append((k, False, True,
                            T('probably two microphones -- about %.1f m '
                              'apart') % metres))
            elif beside and at_zero - max(beside) < PAIR_STANDS_OUT:
                out.append((k, False, False,
                            T('not recognisable -- these two agree no '
                              'better than each does with the channel '
                              'beside it')))
            else:
                out.append((k, True, True,
                            T('probably one stereo track -- both '
                              'microphones in the same place')))
        else:
            out.append((k, False, False,
                        T('not recognisable -- the two channels have too '
                          'little in common')))
    return out


def joined_channels(facts, choice=None):
    """Which neighbours are actually joined, after the ticks.

    A channel belongs to at most one pair, so the answer has to be a set
    that does not overlap. Walking from the left and taking the first
    join that fits is what the interface shows as well: tick a channel
    and the tick on the next one goes away, because it is spoken for.

    Returns {left channel: True} for every pair that is joined.
    """
    judged = {k: stereo for k, stereo, _sure, _why in channel_joins(facts)}
    picked = dict(choice or {})
    n = int(facts.get("channels") or 0)
    silent = list(facts.get("silent") or [])

    def possible(k):
        """An unused input cannot be one side of a stereo track.

        The interface offers no tick where one of the two is silent, but
        a tick made earlier outlives the measurement it was made under:
        take a block away and what carried something may not any more.
        """
        return not ((k < len(silent) and silent[k])
                    or (k + 1 < len(silent) and silent[k + 1]))

    # First what the measurement proposes, on its own: from the left,
    # each pair it found, skipping what is already spoken for.
    out, taken = {}, set()
    for k in range(max(0, n - 1)):
        if k in taken or (k + 1) in taken or not possible(k):
            continue
        if judged.get(k, False):
            out[k] = True
            taken.update((k, k + 1))
    # Then the hand, as a correction of that proposal rather than as an
    # exception inside it. Taking a tick away means one pair fewer and
    # nothing else: rerunning the proposal over the freed channel would
    # join it to its other neighbour, and undoing a pair would create
    # one. Setting a tick means one pair more, and its two neighbours
    # lose theirs -- a channel belongs to one pair at a time.
    for k in sorted(picked):
        if not (0 <= k < n - 1):
            continue
        if not picked[k]:
            out.pop(k, None)
            continue
        if not possible(k):
            continue
        out.pop(k - 1, None)
        out.pop(k + 1, None)
        out[k] = True
    return out


def channel_name(name, channels):
    """What a track cut out of a file is called: "Mixer Channel 1+2".

    "Channel" stays English in every language. It is the word on the
    recorder, on the mixer and in every manual, and translating it would
    mean the name in the interface and the label on the hardware no
    longer match. The plus joins a pair rather than an ampersand: the
    same words end up in a file name, and an ampersand there splits the
    command in two in every shell there is.
    """
    return "%s Channel %s" % (name, "+".join(str(c + 1) for c in channels))


def _level_of(facts, k):
    """Return the level of one channel, a low number where there is none."""
    row = facts.get("level") or []
    if k >= len(row) or row[k] == float("-inf"):
        return -120.0
    return float(row[k])


def pcm_kind(file_path, stream=0):
    """Return the wav sample format to write a copy of this audio in.

    As deep as the original, no deeper: writing a 16 bit recorder file
    as 24 bit costs half again in size and adds nothing.
    """
    try:
        a = next((x for x in ffprobe_json(file_path).get("streams", [])
                  if x.get("codec_type") == "audio"), {})
    except Exception:
        a = {}
    if str(a.get("sample_fmt") or "").startswith(("flt", "dbl")):
        return "pcm_f32le"
    # bits_per_raw_sample is missing for 16 bit files, so
    # bits_per_sample answers as well. Both absent means unknown, and
    # 24 bit is the safe guess: too deep costs space, too shallow
    # throws away what was recorded.
    deep = 0
    for key in ("bits_per_raw_sample", "bits_per_sample"):
        try:
            deep = int(a.get(key) or 0)
        except (TypeError, ValueError):
            deep = 0
        if deep:
            break
    return "pcm_s16le" if 0 < deep <= 16 else "pcm_s24le"


def split_target(file_path, channels, folder):
    """Where the track made of these channels is written.

    The name says which channels are in it -- "Channel1+2", the same
    words the row in the file list uses, so a file on disk and a line on
    screen can be held against each other.

    Two things have to be unique. The channels: "1&2" is not "12", or
    channel 12 would land on the file of channels 1 and 2. And the
    source: every piece of every file goes into one folder, and two cards
    each holding C0001.MP4 would otherwise write over each other --
    silently, because a piece that is already there is not written again.
    So the folder of the source goes into the name as a short
    fingerprint.

    The name ends in a digit, which the search for continuation blocks
    would read as a counter. It does not get the chance: find_continuation
    _files turns away anything carrying this mark.
    """
    stem = os.path.splitext(os.path.basename(file_path))[0]
    tag = "+".join(str(c + 1) for c in channels)
    mark = hashlib.sha1(os.path.abspath(file_path).encode(
        "utf-8", "replace")).hexdigest()[:8]
    return os.path.join(folder, "%s_%s_Channel%s.wav"
                        % (safe_filename(stem)[:60], mark, tag))


def split_channels(file_path, channels, target, stream=0, rate=None):
    """Write one track of a multichannel file into a file of its own.

    *channels* is which channels the track is made of -- one number for
    a mono track, two for a stereo pair. Everything else stays as
    recorded: same rate, same depth, only the channels picked out.

    *rate* forces a sample rate. Needed for camera audio, which is often
    44.1 kHz while everything else in the run is 48 -- two rates in one
    mix would not line up.

    The recording time goes with the piece. Multichannel recorder files
    are exactly the ones that carry it, and everything after this point --
    joining blocks, placing them on the axis, the assignment table -- asks
    the piece, not the file it came out of. Without it a real pause
    between two blocks would be swallowed instead of filled with silence.
    """
    channels = tuple(channels)
    if len(channels) == 1:
        pan = "pan=mono|c0=c%d" % channels[0]
    else:
        pan = "pan=stereo|c0=c%d|c1=c%d" % (channels[0], channels[1])
    os.makedirs(os.path.dirname(target) or ".", exist_ok=True)
    stamp = []
    start = bext_time_reference(file_path)
    if start is not None:
        # Counted in samples, so a changed rate changes the number.
        try:
            was = int(ffprobe_json(file_path)["streams"][stream_index_of(
                file_path, stream)]["sample_rate"])
        except Exception:
            was = SR
        now = int(rate or was)
        stamp = ["-write_bext", "1", "-metadata", "time_reference=%d"
                 % int(round(start * now / float(was or now)))]
    shell_quote(["ffmpeg", "-v", "error", "-i", file_path,
                 "-filter_complex", "[0:a:%d]%s[o]" % (stream, pan),
                 "-map", "[o]"]
                + (["-ar", str(rate)] if rate else [])
                + stamp
                + ["-c:a", pcm_kind(file_path, stream), "-y", target])
    return target


def stream_index_of(file_path, audio_number=0):
    """Return the index in the stream list of this audio stream."""
    every = ffprobe_json(file_path).get("streams", []) or []
    seen = -1
    for i, x in enumerate(every):
        if x.get("codec_type") == "audio":
            seen += 1
            if seen == audio_number:
                return i
    return 0


def tracks_to_split(file_path, facts, choice=None, name=None):
    """Return the tracks a file has to be cut into, as [(channels, label)].

    Empty where nothing has to happen: a single channel, or one pair
    that stays together. Silent channels are not in the answer -- an
    unused recorder input must not become a speaker.

    *name* is what the tracks are called; without it the file name does
    the work. Camera audio passes the camera's name, or the tracks would
    be named after the temporary file it was extracted into.
    """
    rows = channel_tracks(facts, name or os.path.splitext(
        os.path.basename(file_path))[0], choice)
    if len(rows) <= 1 and not any(silent for _c, _l, silent in rows):
        return []
    return [(chs, label) for chs, label, silent in rows
            if not silent and chs]


def expand_chains_to_tracks(chains, split_of):
    """Turn recordings into tracks where one file holds several.

    A recorder writing four channels gives four tracks, and a recording
    made of three blocks gives three blocks per track. So the blocks are
    cut first and the pieces regrouped: piece one of every block is one
    recording, piece two of every block the next.

    Grouped on the original files, never on the pieces: those are named
    after their channel, and the search for continuations would take
    channel two for the continuation of channel one.
    """
    out = []
    for row, discarded in chains:
        pieces = [list(split_of(x) or []) for x in row]
        how_many = max((len(x) for x in pieces), default=0)

        def which(row_of_pieces):
            """The channels each piece is made of, in order.

            Counting the pieces is not enough: one block cut into
            [1][2][3+4] and the next into [1+2][3][4] both give three,
            and zipping them would put two different signals on one row.
            """
            out = []
            for x in row_of_pieces:
                stem = os.path.splitext(os.path.basename(x))[0]
                mark = SPLIT_MARK.search(stem)
                out.append(mark.group(0) if mark else stem)
            return out

        # A recording whose blocks did not all come apart the same way
        # stays whole: two different signals on one row would be worse
        # than not splitting at all.
        if not how_many or any(len(x) != how_many for x in pieces) \
                or any(which(x) != which(pieces[0]) for x in pieces):
            out.append((row, discarded))
            continue
        for k in range(how_many):
            out.append(([x[k] for x in pieces],
                        discarded if k == 0 else []))
    return out


def audio_shape(file_path):
    """Return (channels, sample rate) -- what has to match to join."""
    try:
        a = next((x for x in ffprobe_json(file_path).get("streams", [])
                  if x.get("codec_type") == "audio"), {})
        return (int(a.get("channels") or 0), int(a.get("sample_rate") or 0))
    except Exception:
        return (0, 0)


def shapes_match(first, second):
    """Report whether two files can be laid end to end at all.

    Channel count and sample rate have to be the same. Everything after
    the join treats the blocks as one recording -- the channels are
    judged across all of them, and a channel that is number three in one
    block and number four in the next would make nonsense of that.
    Bit depth may differ; that is only a matter of conversion.
    """
    a, b = audio_shape(first), audio_shape(second)
    if not a[0] or not b[0]:
        return True, ""
    if a == b:
        return True, ""
    if a[0] != b[0]:
        return False, (T('%d channels against %d') % (a[0], b[0]))
    return False, (T('%d Hz against %d Hz') % (a[1], b[1]))


def blocks_facts(paths):
    """Judge the channels over a whole recording, not over one block.

    A recording made of blocks is one recording, and its channels are
    the same in every block. Judging the first block alone can be badly
    wrong: a block holding only the soundcheck reads as one used channel
    pair where the block holding the show reads as ten tracks.

    So each block is measured on its own -- they do not all fit in
    memory at once -- and the answers are combined. A channel counts as
    used where it carries something in any block, and the pair
    judgement is taken from the block where that pair is loudest, since
    that is the block where there is anything to judge.
    """
    rows = [x for x in (paths or []) if x]
    if not rows:
        return {"channels": 0, "level": [], "silent": [], "pair_same": [],
                "pair_zero": [], "pair_apart": [], "readable": False}
    if len(rows) == 1:
        return channel_facts_cached(rows[0])
    return blocks_facts_from([channel_facts_cached(x) for x in rows])


def blocks_facts_from(every):
    """Combine what was measured per block into one answer.

    Apart from blocks_facts so it can be held against made-up numbers:
    building a recording of several 32 channel blocks to test the
    arithmetic would cost gigabytes and prove less.
    """
    every = [f for f in (every or []) if isinstance(f, dict)]
    if not every:
        return {"channels": 0, "level": [], "silent": [], "pair_same": [],
                "pair_zero": [], "pair_apart": [], "readable": False}
    usable = [f for f in every if f.get("readable")]
    if not usable:
        return every[0]
    n = max(int(f.get("channels") or 0) for f in usable)
    usable = [f for f in usable if int(f.get("channels") or 0) == n]
    level = []
    for k in range(n):
        seen = [f["level"][k] for f in usable if k < len(f.get("level") or [])]
        level.append(max(seen) if seen else float("-inf"))
    highest = max(level) if level else float("-inf")
    floor = QUIET_BELOW_DBFS if highest > QUIET_BELOW_DBFS else float("-inf")
    silent = [not (x > float("-inf"))
              or (highest - x) > SILENT_BELOW_DB or x < floor
              for x in level]
    same, zero, apart = [], [], []
    for i, a in enumerate(range(0, n - 1)):
        b = a + 1
        if silent[a] or silent[b]:
            same.append(None), zero.append(None), apart.append(None)
            continue
        # The block where this pair is loudest: judging a pair on the
        # block where it is silent measures the converter's noise.
        best, loudest = None, float("-inf")
        for f in usable:
            measured = f.get("pair_zero") or []
            if i >= len(measured) or measured[i] is None:
                # This block did not measure the pair -- one of the two
                # was silent in it. Taking its answer would mean taking
                # no answer at all.
                continue
            here = min(_level_of(f, a), _level_of(f, b))
            if here > loudest:
                best, loudest = f, here
        def of(name):
            """Entry i of one of the block's lists, or nothing.

            Guarded one by one: hand-made facts are this function's
            documented input, and there the three lists can be of
            different lengths.
            """
            row = (best or {}).get(name) or []
            return row[i] if i < len(row) else None

        same.append(of("pair_same"))
        zero.append(of("pair_zero"))
        apart.append(of("pair_apart"))
    return {"channels": n, "level": level, "silent": silent,
            "pair_same": same, "pair_zero": zero, "pair_apart": apart,
            "readable": True}


def channel_facts_cached(file_path):
    """Measure a file's channels once, not once per redraw.

    Reading every channel of an hour of audio takes seconds; the file
    list is rebuilt on every change. Keyed on size and modification
    time like the other measurements, so a changed file is measured
    again.
    """
    # A name of its own: "channels" already belongs to the plain
    # channel count, and one store holding both would hand an integer
    # to whoever asked for the facts.
    return probe_remember("channelfacts", file_path,
                          lambda: channel_facts(file_path))


def channel_tracks(facts, name="Track", choice=None):
    """Return the tracks one file contributes, after the pair judgement.

    *choice* overrides the proposal per pair, {left channel: joined yes or
    no}, which is what the tick in the file list writes. A channel can
    belong to only one pair, so a tick on channel 2 takes the tick away
    from channel 3 -- see joined_channels.

    Returns [(channels, label, silent)]. *channels* is a tuple of channel
    indices -- two for a stereo pair, one otherwise -- or an empty tuple
    where the file has only one channel and stays as it is.
    """
    n = int(facts.get("channels") or 0)
    if not facts.get("readable") or n <= 1:
        silent = (facts.get("silent") or [False])
        return [((), name, bool(silent and silent[0]))]
    silent = list(facts.get("silent") or [False] * n)
    joined = joined_channels(facts, choice)
    out, k = [], 0
    while k < n:
        if joined.get(k):
            out.append(((k, k + 1), channel_name(name, (k, k + 1)),
                        silent[k] and silent[k + 1]))
            k += 2
            continue
        out.append(((k,), channel_name(name, (k,)), silent[k]))
        k += 1
    # One track left over means the numbering says nothing -- then the
    # file name alone is the better label.
    awake = [t for t in out if not t[2]]
    if len(awake) == 1:
        out = [(t[0], name if t is awake[0] else t[1], t[2]) for t in out]
    return out


def mix_tracks(sources, target, gain=0.0, curve=None, channels=1):
    """Sum several equally long tracks into one.

    The gain is the same for all tracks, and so is the limiter curve above
    it. Without the curve the gain would have to drop far enough for the
    loudest peak to fit, and a single scraping chair would cost the whole
    production several decibels. Because the same curve goes on every track,
    the single tracks add up to exactly the mix again.

    channels=2 asks for two channels. A stereo source raises that on its
    own: what came in stereo goes out stereo, and the sides survive into the
    mix. Two channels is also the form a mix is delivered in, and the only
    form in which the loudness measured here is the loudness measured later.

    The widening happens before the sum, not after, which is the same
    result and the only way a stereo source can keep its sides. Panning a
    mono track to centre on a stereo bus would be an invisible trap:
    depending on the pan law it lands at 0, -3, -4.5 or -6 dB. "c1=c0"
    matters here rather than a plain conversion, which would apply an
    equal-power law and take off 3.01 dB -- measured, not assumed.
    """
    have = [kept_channels(p) for p in sources]
    channels = max(channels, max(have) if have else 1)
    if (len(sources) == 1 and abs(gain) < 0.01 and not curve
            and have[0] == channels):
        return sources[0]
    parts, chains, markers = [], [], []
    for i, path in enumerate(sources):
        parts += ["-i", path]
        chains.append("[%d:a]%s[m%d]"
                      % (i, channel_filter(have[i], channels), i))
        markers.append("[m%d]" % i)
    fc = ";".join(chains) + ";" + "".join(markers) +\
        "amix=inputs=%d:normalize=0" % len(markers)
    if abs(gain) >= 0.01:
        fc += ",volume=%.3fdB" % gain
    if curve:
        # The same gain curve as on all other tracks, hence a second input
        # rather than a limiter of its own. The curve is brought to the
        # channel count by hand: left to ffmpeg, one curve channel against
        # two of signal would come with the equal-power law and quietly take
        # another 3 dB off everything.
        fc += "[both]"
        parts += ["-i", curve]
        fc += ";[both]aformat=sample_fmts=fltp:sample_rates=%d[gm];" % SR
        fc += "[%d:a]%s,aformat=sample_fmts=fltp:sample_rates=%d[gc];" % (
            len(sources), channel_filter(kept_channels(curve), channels), SR)
        fc += "[gm][gc]amultiply[out]"
    else:
        fc += "[out]"
    run_ffmpeg_with_progress(
        ["ffmpeg", "-v", "error"] + parts + ["-filter_complex", fc,
         "-map", "[out]", "-c:a", "pcm_s24le", "-y", target],
        sample_count(sources[0]) / float(SR),
        T('Mixing %s') % (os.path.splitext(os.path.basename(target))[0]
                       .replace("mix_", "").replace("single_", "")
                       .replace("full", "Full-Mix")))
    return target


_SOXR = None


def _have_soxr():
    """Report whether this ffmpeg was built with soxr."""
    try:
        p = subprocess.run(["ffmpeg", "-v", "error", "-f", "lavfi", "-i",
                            "anullsrc=r=48000:cl=mono", "-t", "0.05", "-af",
                            "aresample=resampler=soxr:osr=48001",
                            "-f", "null", "-"], capture_output=True)
        return p.returncode == 0
    except Exception:
        return False


def rate_filter_chain(b):
    """Build a filter chain that compresses a track by factor b.

    The obvious chain rounds to whole sample rates, which at 48 kHz means
    steps of 20.8 ppm. Coarse correction can live with that; the fine
    correction that pulls the tracks together cannot -- 9 ppm would simply
    become 0. So the intermediate rate is a hundred times higher, making the
    steps 0.21 ppm. The built-in resampler sometimes fails at such ratios
    ("Failed to initialize resampler"), soxr does not; without soxr the
    coarse path is used.
    """
    global _SOXR
    if _SOXR is None:
        _SOXR = _have_soxr()
    if _SOXR:
        return ("asetrate=%d,aresample=resampler=soxr:osr=%d,asetrate=%d"
                % (SR * 100, int(round(SR * 100 / b)), SR))
    if abs(b - 1.0) > 1e-7 and not getattr(rate_filter_chain, "warned", False):
        rate_filter_chain.warned = True
        print(T('  Note: this ffmpeg has no soxr -- clock drift can only '
                'be taken out in\n  steps of 21 ppm.'))
    return "asetrate=%d,aresample=%d,asetrate=%d" % (SR, int(round(SR / b)),
                                                     SR)


def place_track_on_axis(source, target, a, b, t0, t1, drift=True):
    """Place an audio track on the reference axis and clip it to [t0, t1].

    Audio time = a + b * reference time. The clock drift is removed first,
    after which audio time is divided by b and so is the offset. The track
    is then cut to the start of the window and padded with silence to the
    full window length. Every track gets the same window so they line up
    sample-exact afterwards -- without that Auphonic cannot remove the
    crosstalk.

    The channel count is the source's. A stereo track stays stereo here and
    all the way into the mix; only a file with more than two channels is
    folded, and by then it should long since have been cut into tracks.
    """
    n_window = int(round((t1 - t0) * SR))
    keep = kept_channels(source)
    af = []
    if drift and abs(b - 1.0) > 1e-7:
        af.append(rate_filter_chain(b))
        start = a / b + t0
    else:
        start = a + t0
    k = int(round(start * SR))
    if k > 0:
        af.append("atrim=start_sample=%d" % k)
        af.append("asetpts=N/SR/TB")
    elif k < 0:
        af.append("adelay=delays=%dS:all=1" % (-k))
    af.append("apad=whole_len=%d" % n_window)
    af.append("atrim=end_sample=%d" % n_window)
    af.append("asetpts=N/SR/TB")
    shell_quote(["ffmpeg", "-v", "error", "-i", source, "-af", ",".join(af),
        "-ac", str(keep), "-c:a", "pcm_s24le", "-y", target])
    return target


def align_cameras(videos):
    """Put all cameras on the time axis of the longest one.

    The longest camera is the reference because it covers the widest range
    and therefore offers the most sample points. The camera microphones are
    compared with each other -- the same computation as audio against video,
    just with two envelopes that are in memory anyway.

    Returns (reference, {path: (a, b, count)}) with
    camera time = a + b * reference time.
    """
    ref_clip = max(videos, key=lambda v: v[1]["duration"])
    position = {ref_clip[0]: (0.0, 1.0, {"points": 0, "reference": True})}
    env_ref = video_envelope(ref_clip[0])
    for v, info in videos:
        if v == ref_clip[0]:
            continue
        env = video_envelope(v)
        # Sample more densely than for audio against video: two cameras often
        # overlap only partly, and what lies outside the overlap drops out as a
        # sample point anyway. Every 30 seconds instead of every two minutes,
        # at least 20 points.
        duration = len(env_ref) * 5.0 / 1000.0
        density = int(max(20, min(120, duration / 30.0)))
        try:
            a, b, st = align_envelopes(env_ref, env, sample_points=density,
                                          distance_s=30.0)
        except Exception as e:
            print(T('  %s cannot be classified: %s')
                  % (os.path.basename(v), e))
            continue
        position[v] = (a, b, st)
    return ref_clip, position


def extract_audio_from_video(file_path, tmpdir):
    """Extract one camera's audio unchanged.

    Unlike the multitrack path nothing is folded to mono here: a single file
    may well carry different material left and right, and that should not be
    lost.
    """
    file_path = os.path.abspath(file_path)
    stem = os.path.splitext(os.path.basename(file_path))[0]
    target = os.path.join(tmpdir, "%s.wav" % safe_filename(stem))
    info = video_facts(file_path)
    if not info["audio"]:
        raise RuntimeError(T('%s has no audio track.') % os.path.basename(file_path))
    channels = int((info["audio"][0] or {}).get("channels") or 1)
    print(as_head(T('NO AUDIO FILE -- USING THE CAMERA AUDIO')))
    print(T('  from %s, %s')
          % (os.path.basename(file_path), channel_text(channels)))
    command = ["ffmpeg", "-v", "error", "-i", file_path, "-map", "0:a:0",
              "-ar", str(SR), "-c:a", "pcm_s24le", "-write_bext", "1"]
    if info.get("tc"):
        # The audio starts where the picture starts. Passing the timecode along
        # saves the alignment from guessing.
        try:
            t0 = parse_timecode(info["tc"], max(1.0, info["fps"]))
            command += ["-metadata",
                       "time_reference=%d" % int(round(t0 * SR))]
            print("  Timecode %s" % info["tc"])
        except Exception:
            pass
    show_progress(T('Camera audio'), 0.0)
    shell_quote(command + ["-y", target])
    show_progress(T('Camera audio'), 1.0)
    print("  %s" % os.path.basename(target))
    return target


def extract_audio_for_plan(plan, tmpdir):
    """Extract the camera audio for a finished plan.

    The names come from the interface, one row per camera. The channels
    are the camera's own: a camera whose two channels carry two clip-on
    microphones has already been cut into two rows by then, and one that
    carries a real stereo pair should keep it. Folding here would undo
    both.
    """
    pending = [e for e in plan if e.get("camera_audio")]
    if not pending:
        return list(plan)
    step_begin("camera audio")
    # Where the interface has already extracted everything there is nothing to
    # show -- the prework belongs in the interface, not in the log of the run.
    to_fetch = [e for e in pending
                if not (e.get("audio_done")
                        and os.path.exists(e["audio_done"]))]
    if to_fetch:
        print(as_head(T('EXTRACTING CAMERA AUDIO')))
    done = []
    for i, e in enumerate(plan):
        if not e.get("camera_audio"):
            # An ordinary audio recording stays as it is.
            done.append(dict(e))
            continue
        # Where the audio is pulled from is the camera it was recorded on,
        # not the camera the speaker is assigned to.
        v = os.path.abspath(e.get("from_camera") or e["camera"] or e["audio"])
        name = e.get("speakers") or guess_camera_name(v)
        # The interface extracts the audio while names are still being typed.
        # Whatever is there is used.
        already = e.get("audio_done")
        if already and os.path.exists(already) and sample_count(already) > 0:
            fresh = dict(e)
            fresh.update({"audio": already, "blocks": [already],
                        "speakers": name, "upfront": True})
            fresh.setdefault("camera", v)
            done.append(fresh)
            continue
        target = os.path.join(tmpdir, "cameraaudio_%s.wav" % safe_filename(name))
        show_progress(T('Camera audio %s') % name, i / float(len(plan)))
        try:
            shell_quote(["ffmpeg", "-v", "error", "-i", v, "-map", "0:a:0",
                "-ac", str(max(1, channel_count(v))), "-ar", str(SR),
                "-c:a", "pcm_s16le", "-y", target])
        except Exception as ex:
            print(T('\n  %s: no audio to extract (%s)')
                  % (os.path.basename(v), ex))
            continue
        pieces = camera_audio_tracks(target, name, tmpdir)
        for piece, label in pieces:
            fresh = dict(e)
            fresh.update({"audio": piece, "blocks": [piece],
                          "speakers": label if len(pieces) > 1 else name})
            fresh.setdefault("camera", v)
            fresh.setdefault("from_camera", v)
            done.append(fresh)
    if to_fetch:
        show_progress(T('Camera audio'), 1.0)
        for e in done:
            if not e.get("camera_audio") or e.get("upfront"):
                continue
            print(T('  %-24s from %s')
                  % (e["speakers"], os.path.basename(e["camera"])))
    if len(done) < 2:
        print(T('  Fewer than two cameras with sound -- too few for '
                'Multitrack.'))
    return done


def camera_audio_tracks(audio, name, folder):
    """Cut a camera's audio into the tracks it holds.

    A camera is not automatically one track. A DJI Osmo records two
    clip-on microphones on one channel each, and those are two people --
    judged by the same measurement as a recorder file, so a real stereo
    pair stays one two channel track and two microphones become two.

    The audio is extracted with every channel it has, not folded first:
    folding four channels to one and then asking what is on them would
    always answer "one voice". Where nothing has to be cut, a file with
    more than two channels is folded later, on the way to the axis.

    Returns [(file, name)], one entry where nothing has to be cut.
    """
    try:
        facts = channel_facts_cached(audio)
        want = tracks_to_split(audio, facts, name=name)
    except Exception:
        want = []
    if not want:
        return [(audio, name)]
    out = []
    for chs, label in want:
        target = split_target(audio, chs, folder)
        try:
            if not os.path.exists(target) or not os.path.getsize(target):
                split_channels(audio, chs, target, rate=SR)
        except Exception as e:
            print(T('  %s: channel %s cannot be cut out (%s)')
                  % (name, "+".join(str(c + 1) for c in chs), e))
            return [(audio, name)]
        out.append((target, label))
    return out


def plan_from_camera_audio(video_paths, tmpdir, cameras=None, title=""):
    """Use each video file's own audio as a track.

    For the case where there are no separate audio recordings at all, only
    cameras with a built-in or clip-on microphone. Auphonic can work with
    that too: each camera becomes a track and the crosstalk from the others
    is removed.

    A camera carrying two microphones on two channels becomes two tracks,
    not one -- the same rule as for a recorder file.
    """
    step_begin("camera audio")
    plan = []
    prefixes = [t + "_" for t in {title, safe_filename(title)} if t]
    named = {os.path.abspath(cam["video"]): cam["name"]
               for cam in (cameras or []) if cam.get("video")}
    taken = set()
    print(as_head(T('NO SEPARATE AUDIO RECORDINGS -- USING THE CAMERA AUDIO')))
    for i, v in enumerate(video_paths, 1):
        v = os.path.abspath(v)
        # The name has to differ per camera: it becomes the track identifier at
        # Auphonic. The file stem serves; nothing is guessed here.
        name = named.get(v) or os.path.splitext(os.path.basename(v))[0]
        for prefix in prefixes:
            if name.startswith(prefix):
                name = name[len(prefix):]
                break
        reason, cam = name, 2
        while name in taken:
            name = "%s %d" % (reason, cam)
            cam += 1
        taken.add(name)
        target = os.path.join(tmpdir, "cameraaudio_%s.wav" % safe_filename(name))
        show_progress(T('Camera audio %s') % name, (i - 1) / float(
            len(video_paths)))
        try:
            shell_quote(["ffmpeg", "-v", "error", "-i", v, "-map", "0:a:0",
                "-ac", str(max(1, channel_count(v))), "-ar", str(SR),
                "-c:a", "pcm_s16le", "-y", target])
        except Exception as e:
            print(T('\n  %s: no audio to extract (%s)')
                  % (os.path.basename(v), e))
            continue
        for piece, label in camera_audio_tracks(target, name, tmpdir):
            plan.append({"audio": piece, "blocks": [piece],
                         "speakers": label, "camera": v,
                         "from_camera": v})
    show_progress(T('Camera audio'), 1.0)
    for e in plan:
        print(T('  %-24s from %s') % (e["speakers"],
                                  os.path.basename(e["camera"])))
    if len(plan) < 2:
        print(T('  Fewer than two cameras with sound -- too few for '
                'Multitrack.'))
    return plan


def clip_to_time_window(args, t0, t1, ref_clip):
    """Apply the In point and the Out point to the measured window.

    The window lives in reference camera time. An absolute value -- a
    timecode -- is converted through the reference timecode; a relative one
    counts from the window start, and a negative one with --out-point
    counts back from the window end.
    """
    start = getattr(args, "in_point", None)
    end = getattr(args, "out_point", None)
    if not start and not end:
        return t0, t1
    fps = max(1.0, ref_clip[1]["fps"]) if ref_clip else 30.0
    tc_ref = None
    if ref_clip and ref_clip[1].get("tc"):
        tc_ref = parse_timecode(ref_clip[1]["tc"], fps)

    def convert(value_text, from_the_end):
        value, absolute = parse_time_point(value_text, fps)
        if value is None:
            return None
        if absolute:
            if tc_ref is None:
                raise RuntimeError(
                    T('%r is a Timecode, but reference camera %s has none. '
                      'Then only a value from the window start works, such '
                      'as +12:30.') % (value_text, os.path.basename(ref_clip[0])
                                      if ref_clip else "?"))
            return value - tc_ref
        if value < 0:
            if not from_the_end:
                raise RuntimeError(
                    T('%r counts from the end -- that only works '
                      'for Out point.') % value_text)
            return t1 + value
        return t0 + value

    try:
        new0 = convert(start, False) if start else t0
        new1 = convert(end, True) if end else t1
    except RuntimeError as e:
        print("\n%s" % e)
        return None, None
    print(T('\n  Time window by hand:'))
    if tc_ref is not None:
        print("    In point   %s   (Timecode %s)"
              % (as_hms(new0), timecode_string(tc_ref + new0)))
        print("    Out point  %s   (Timecode %s)"
              % (as_hms(new1), timecode_string(tc_ref + new1)))
    else:
        print("    In point   %s\n    Out point  %s" % (as_hms(new0), as_hms(new1)))
    if new1 <= new0:
        print(T('    Out point lies before In point -- that does not work.'))
        return None, None
    outside = []
    if new0 < t0 - 0.001:
        outside.append(T('In point is %s before the first frame')
                          % as_hms(t0 - new0))
    if new1 > t1 + 0.001:
        outside.append(T('Out point is %s after the last frame')
                          % as_hms(new1 - t1))
    if outside:
        print(T('    Careful: %s. There is no picture there;') % T(' and ').join(
            outside))
        print(T('    the measured window is therefore kept.'))
        new0, new1 = max(new0, t0), min(new1, t1)
    if new1 - new0 < 5:
        print(T('    The window would be only %s long -- that cannot be '
                'intended.') % as_hms(max(0, new1 - new0)))
        return None, None
    print(T('    Length  %s  (instead of %s)') % (as_hms(new1 - new0), as_hms(t1 - t0)))
    return new0, new1


def merge_plan_entries(plan):
    """Merge plan rows that share a speaker name into one track.

    Stopping the recording in between leaves several files for the same
    person. Their timecodes put the blocks in the right place anyway; as one
    track it stays one person at Auphonic, and the statistics do not count
    them twice.
    """
    combined = []
    after_name = {}
    for e in plan:
        name = (e.get("speakers") or "").strip()
        blocks = list(e.get("blocks") or [e["audio"]])
        if name and name in after_name:
            old = after_name[name]
            old["blocks"] += blocks
            if not old.get("camera") and e.get("camera"):
                old["camera"] = e["camera"]
            elif (e.get("camera") and old.get("camera")
                  and os.path.abspath(e["camera"])
                  != os.path.abspath(old["camera"])):
                print(T('  %s appears twice with different cameras -- %s '
                        'is used')
                      % (name, os.path.basename(old["camera"])))
            continue
        fresh = dict(e)
        fresh["blocks"] = blocks
        fresh["speakers"] = name
        combined.append(fresh)
        if name:
            after_name[name] = fresh
    for e in combined:
        e["blocks"] = sort_by_time(e["blocks"])
        e["audio"] = e["blocks"][0]
    more = [(e["speakers"], len(e["blocks"])) for e in combined
            if len(e["blocks"]) > 1]
    if len(combined) < len(plan):
        print(T('  In summary: %s')
              % ", ".join(T('%s from %d recordings') % (n, k) for n, k in more))
    return combined


def sort_by_time(paths):
    """Sort blocks into recording order.

    The timecode from the bext chunk is the reliable source; without it only
    the file name is left.
    """
    def api_key(p):
        try:
            tr = bext_time_reference(p)
        except Exception:
            tr = None
        return (0, tr, "") if tr is not None else (1, 0, os.path.basename(p))
    return sorted(paths, key=api_key)


def show_multitrack_plan(args, audio_paths, video_paths):
    """Show the detected plan without doing anything yet.

    Better to say what would happen than to write something wrong.
    """
    step_begin("plan")
    plan, cameras, title = [], [], ""
    if args.assign and os.path.exists(args.assign):
        try:
            with open(args.assign, encoding="utf-8") as f:
                d = json.load(f)
        except ValueError as e:
            print(T('Assignment file not readable: %s') % e)
            return 1
        if isinstance(d, dict):
            complaint = format_complaint(d)
            if complaint:
                print(as_bad(T('Abort: %s') % complaint))
                return 1
            plan = d.get("tracks_of") or []
            cameras = d.get("cameras") or []
            # What the window already had taken apart by voice. Carried
            # over rather than computed again: three minutes of the
            # graphics unit for a result that is already there.
            args._speakers_of = d.get("speakers_of") or {}
            title = d.get("production") or ""
            args.production = title
        else:
            plan = d
    print(as_head(T('MULTITRACK -- RECOGNISED PLAN')))
    if title:
        print(T('  Production at auphonic.com:   %s') % title)
    if not plan and audio_paths:
        for row, _ in group_recording_parts(audio_paths,
                                            args.no_follow_ups,
                                            getattr(args, "apart", ()),
                                            getattr(args, "together", ())):
            plan.append({"audio": row[0], "blocks": row,
                         "speakers": guess_speaker_name(row[0]), "camera": ""})
    if any(e.get("camera_audio") for e in plan):
        # The interface sent cameras rather than audio recordings: names and
        # assignment are settled, only the audio is extracted now.
        args._camera_audio = tempfile.mkdtemp(prefix="vpm_camaudio_")
        atexit.register(shutil.rmtree, args._camera_audio, True)
        plan = extract_audio_for_plan(plan, args._camera_audio)
        if len(plan) < 2:
            return 1
    elif not plan:
        # Only video files on the command line: guess the names ourselves.
        args._camera_audio = tempfile.mkdtemp(prefix="vpm_camaudio_")
        atexit.register(shutil.rmtree, args._camera_audio, True)
        plan = plan_from_camera_audio(video_paths, args._camera_audio, cameras, title)
        if len(plan) < 2:
            return 1
        if not cameras:
            # One entry per camera, not per track: a camera whose two
            # channels carry two microphones is still one camera and
            # still writes one file. Both names go into that file name.
            who = {}
            for e in plan:
                who.setdefault(os.path.abspath(e["camera"]), []).append(
                    e["speakers"])
            cameras = [{"video": v, "name": "%s_%s"
                        % (safe_filename(title or 'Production'),
                           "+".join(names))}
                       for v, names in who.items()]
    plan = merge_plan_entries(plan)
    for e in plan:
        blocks = e.get("blocks") or [e["audio"]]
        total = sum(sample_count(b) for b in blocks) / float(SR)
        target = os.path.basename(e["camera"]) if e.get("camera")\
            else label_of(MIX_ONLY)
        print("  %-20s %-34s %s%s"
              % (e.get("speakers") or T('unnamed'),
                 os.path.basename(blocks[0])
                 + ("  (+%d)" % (len(blocks) - 1) if len(blocks) > 1 else ""),
                 as_hms(total), "  ->  " + target))
    combined = {}
    for e in plan:
        combined.setdefault(e.get("camera") or "", []).append(
            e.get("speakers") or "?")
    multiple = {cam: v for cam, v in combined.items() if len(v) > 1 and cam}
    for cam, v in multiple.items():
        print(T('  %s gets %d tracks mixed together: %s')
              % (os.path.basename(cam), len(v), ", ".join(v)))
    if cameras:
        print(T('\n  This produces:'))
        every = [e.get("speakers") or "?" for e in plan]
        for cam in cameras:
            own = combined.get(cam["video"]) or []
            print("    %s  ->  %s" % (os.path.basename(cam["video"]),
                                      cam["name"] + ".mov"))
            for idx, what in enumerate(track_order_for_camera(own, every), 1):
                print(T('        Track %d: %s') % (idx, what))
    return build_common_timebase(args, plan, cameras, video_paths, title)


def build_common_timebase(args, plan, cameras, video_paths, title=""):
    """Put all audio tracks on one common time axis.

    The result is equally long files with the same start point -- what
    Auphonic requires for multitrack, and at the same time the precondition
    for crosstalk removal to be worth anything.
    """
    step_begin("time base")
    videos = []
    for v in video_paths:
        v = os.path.abspath(v)
        try:
            info = video_facts(v, args.fps, args.tc)
        except Exception as e:
            print(T('  %s: %s, skipped') % (os.path.basename(v), e))
            continue
        if not info["audio"]:
            print(T('  %s has no camera sound -- without it nothing can be '
                    'aligned') % os.path.basename(v))
            continue
        videos.append((v, info))
    if not videos:
        print(T('\nNo usable video file -- without camera audio there is no '
                'common time axis.'))
        return 1

    # The nominal rates from the container are compared. The measured ones
    # differ by a few ten-thousandths on every camera; no editor goes by that,
    # and a warning about it would be a false alarm every time.
    rates = sorted({round(i.get("nominal") or i["fps"], 3) for _, i in videos})
    sizes = sorted({"%sx%s" % ((i["video"] or {}).get("width"),
                                  (i["video"] or {}).get("height"))
                       for _, i in videos})
    if len(rates) > 1:
        print(as_head(T('\nDIFFERENT FRAME RATES: %s')
                      % ", ".join("%.3f" % r for r in rates)))
        print(T('  That does not matter here -- each camera is aligned '
                'separately against\n  its own sound, and the picture is '
                'only copied over. But the Timeline in\n  the video '
                'software needs one rate; Resolve converts the rest.'))
    if len(sizes) > 1:
        print(as_head(T('\nDIFFERENT FRAME SIZES: %s') % ", ".join(sizes)))
        print(T('  Of no consequence for the sound.'))

    print(as_head(T('\nMEASURING THE TIME AXIS')))
    ref_clip, position = align_cameras(videos)
    print(T('  Reference: %s (%s, longest running time)')
          % (os.path.basename(ref_clip[0]), as_hms(ref_clip[1]["duration"])))
    for v, info in videos:
        if v == ref_clip[0]:
            continue
        if v not in position:
            continue
        a, b, st = position[v]
        print(T('  %-20s offset %s, clock drift %+.2f ppm (+/- %.2f), '
                'residual spread %.1f ms, %d of %d points')
              % (os.path.basename(v), as_hms(a), st.get("ppm", 0.0),
                 st.get("ppm_error", 0.0), st.get("spread_ms", 0.0),
                 st.get("points", 0), st.get("candidates", 0)))

    tmpdir = tempfile.mkdtemp(prefix="vpm_mt_")
    # A dozen paths leave this function before the folder is removed at the
    # end; without this a failed run keeps gigabytes of WAV.
    atexit.register(shutil.rmtree, tmpdir, True)
    tracks = []
    for e in plan:
        blocks = e.get("blocks") or [e["audio"]]
        name = e.get("speakers") or os.path.basename(blocks[0])
        if len(blocks) > 1:
            source, join_info = join_audio_parts(
                blocks, os.path.join(tmpdir, "raw_%s.wav" % safe_filename(name)))
            hint = T('%d blocks') % join_info["blocks"]
        else:
            source, hint = blocks[0], ""
        try:
            a, b, st = align_audio_to_video(source, ref_clip[0], 0,
                                  sample_points=int(max(20, min(120,
                                      ref_clip[1]["duration"] / 30.0))),
                                  distance_s=30.0)
        except Exception as ex:
            print(T('  %-20s cannot be aligned: %s') % (name, ex))
            continue
        tracks.append({"name": name, "source": source, "a": a, "b": b,
                       "st": st, "camera": e.get("camera") or "",
                       "blocks": list(blocks), "hint": hint})
        print(T('  %-20s offset %s, clock drift %+.2f ppm (+/- %.2f), '
                'residual spread %.1f ms, %d of %d points%s')
              % (name, as_hms(a), st.get("ppm", 0.0), st.get("ppm_error", 0.0),
                 st.get("spread_ms", 0.0), st.get("points", 0),
                 st.get("candidates", 0),
                 "  [" + hint + "]" if hint else ""))
    if len(tracks) < 2:
        print(T('\nFewer than two audio tracks can be aligned -- Multitrack '
                'is not worth it.'))
        return 1

    # Window: whatever any camera saw, limited to what there is audio for.
    # Anything outside would be uploaded silence.
    camera_areas = []
    for v, info in videos:
        if v not in position:
            continue
        a, b, _ = position[v]
        camera_areas.append(((0.0 - a) / b, (info["duration"] - a) / b))
    audio_areas = []
    for track in tracks:
        n = sample_count(track["source"]) / float(SR)
        audio_areas.append(((0.0 - track["a"]) / track["b"],
                             (n - track["a"]) / track["b"]))
    # The window comes from the cameras alone: what has no picture needs no
    # audio. Where audio is missing it is padded with silence -- a silent
    # stretch beats a shifted one.
    t0 = min(x for x, _ in camera_areas)
    t1 = max(y for _, y in camera_areas)
    for track, (b0, b1) in zip(tracks, audio_areas):
        missing_front, missing_back = max(0.0, b0 - t0), max(0.0, t1 - b1)
        # Report only what is really missing inside the chosen window: a camera
        # running before the recorder was switched on is the normal case and
        # irrelevant to the cut.
        track["missing_head"], track["missing_tail"] = missing_front, missing_back

    if t1 - t0 < 30:
        print(T('\nThe common range of sound and picture is only %s long -- '
                'something is wrong.') % as_hms(max(0, t1 - t0)))
        return 1
    print(T('  Common window:       %s to %s (%s)')
          % (as_hms(t0), as_hms(t1), as_hms(t1 - t0)))
    # Remember the measured window: already processed tracks come from a run
    # without In point and Out point and are therefore exactly that long.
    full0, full1 = t0, t1
    t0, t1 = clip_to_time_window(args, t0, t1, ref_clip)
    if t0 is None:
        return 1
    # Only count now: what lies before In point is not missing. Where the
    # window covers only stretches that have audio, nothing appears here -- a
    # message about something that is not missing is noise.
    names = [track["name"] for track in tracks]
    starts = [b0 for b0, _ in audio_areas]
    ends = [b1 for _, b1 in audio_areas]

    def silence_report(missing, points, shape):
        """Report one side, front and back separately.

        Where all tracks are affected equally, one line for the worst case is
        enough. Only a track that stands out is named.
        """
        if max(missing) <= 1:
            return
        def sentence(how_much, point):
            return (T('Missing audio %s filled with silence%s')
                    % (shape % as_hms(point),
                       T(' -- an In or Out point saves the upload')
                       if how_much > 30 else ""))
        if max(missing) - min(missing) < 15:
            print("  %s" % sentence(max(missing), points[missing.index(max(missing))]))
            return
        for name, how_much, point in zip(names, missing, points):
            if how_much > 1:
                print("  %-20s %s" % (name, sentence(how_much, point)))

    silence_report([max(0.0, b - t0) for b in starts], starts, T('up to %s'))
    silence_report([max(0.0, t1 - b) for b in ends], ends,
                   T('from %s'))

    print(as_head(T('\nWRITING TRACKS TO THE AXIS')))
    for track in tracks:
        target = os.path.join(tmpdir, "axis_%s.wav" % safe_filename(track["name"]))
        drift = not args.no_drift and abs(track["b"] - 1.0) > 1e-7
        show_progress("%s" % track["name"], 0.0)
        place_track_on_axis(track["source"], target, track["a"], track["b"], t0, t1, drift)
        show_progress("%s" % track["name"], 1.0)
        print()
        track["axis"] = target
        track["drift"] = drift
        clock_drift = (track["b"] - 1.0) * 1e6
        print("    %s, %s%s" % (as_hms(sample_count(target) / float(SR)),
                                as_data_size(size_in_mb(target)),
                                T(', clock drift %+.1f ppm taken out') % clock_drift
                                if drift else T(', clock drift left in')))
    verify_alignment(tracks, t0, t1,
                     drift_allowed=not getattr(args, "no_drift", False))

    # Who speaks when, before anything is uploaded and before the audio
    # is processed: the axis stands now, so a separation can be placed
    # on it. Computed here it is arithmetic on stored segments.
    args._speakers = separation_for_run(args, tracks, position, t0, t1,
                                        video_paths)

    #--------------------------------------------------- Processing
    if getattr(args, "without_auphonic", False):
        return finish_without_auphonic(args, tracks, cameras, videos, tmpdir,
                                       position, t0, t1, ref_clip)
    if args.auphonic_done:
        # Already processed: the files are there. Saves a second upload and,
        # more to the point, the credit.
        folder = os.path.abspath(args.auphonic_done)
        print(as_head(T('\nALREADY PROCESSED')))
        print(T('  From %s') % folder)
        existing = [f for f in os.listdir(folder)
                     if os.path.splitext(f)[1].lower() in AUDIO_SUFFIXES]
        window = t1 - t0                       # what this run needs
        measured = full1 - full0        # the window without In point/Out point
        trimmed = abs(window - measured) > 0.001
        # Trimming leaves slack at both ends, so nothing is lost even where a
        # jingle was prepended. The return check finds the exact position
        # anyway and trims to the sample.
        MARGIN = 30.0
        shift = t0 - full0
        bad = []
        for track in tracks:
            best = max(existing, key=lambda f: similarity(
                track["name"], os.path.splitext(f)[0])) if existing else None
            quality = similarity(track["name"],
                             os.path.splitext(best)[0]) if best else 0.0
            if not best or quality < 0.6:
                print(T('    %-20s no file with a matching name') % track["name"])
                bad.append(track["name"])
                continue
            file_path = os.path.join(folder, best)
            length = sample_count(file_path) / float(SR)
            # The length may differ by a jingle but not by minutes, or the file
            # belongs to a different run. Two lengths qualify: the window of
            # this run, and the measured window without In point and Out point.
            # The latter is the normal case where a window was only set
            # afterwards -- the file is then simply longer and gets trimmed.
            if abs(length - window) <= 60:
                track["done"] = file_path
                existing.remove(best)
                print(T('    %-20s <- %s  (%s, name similarity %.2f)')
                      % (track["name"], best, as_hms(length), quality))
                continue
            if trimmed and abs(length - measured) <= 60:
                # A prepended jingle lengthens the file; everything sits
                # further back by the same amount.
                front = shift + max(0.0, length - measured)
                target = os.path.join(tmpdir,
                                    "window_%s.wav" % safe_filename(track["name"]))
                place_track_on_axis(file_path, target, front - MARGIN, 1.0, 0.0,
                               window + 2 * MARGIN, drift=False)
                track["done"] = target
                track["edge"] = MARGIN
                existing.remove(best)
                print(T('    %-20s <- %s  (%s, trimmed to the time window, '
                        'name similarity %.2f)')
                      % (track["name"], best, as_hms(length), quality))
                continue
            print(T('    %-20s <- %s  BUT %s -- neither the time window '
                    '(%s) nor the\n    %-20s    whole measured range (%s). '
                    'This belongs to another run.')
                  % (track["name"], best, as_hms(length), as_hms(window), "",
                     as_hms(measured)))
            bad.append(track["name"])
        if bad:
            print(T('\n  Not usable: %s') % ", ".join(bad))
            print(T('  The files in the folder must be named after the '
                    'speakers and belong\n  to this run. Without the folder '
                    'it goes through auphonic.com again.'))
            return 1
        if args.dry_run:
            print(T('\n  (measuring only: nothing written)'))
            return 0
        if not verify_returned_tracks(tracks, t1 - t0, tmpdir):
            return 1
        gain, curve = normalise_loudness(
            tracks, args.lufs, tmpdir,
            find_master_file(folder, args.out, os.path.dirname(video_paths[0])),
            channels=2)
        return distribute_tracks_to_cameras(
            args, tracks, cameras, videos, tmpdir, gain, position, t0,
            ref_clip, t1, curve)

    if args.dry_run and not args.auphonic_key:
        print(T('\n  (measuring only: without an API key it stops here)'))
        return 0
    key = api_key_from_anywhere(args)
    try:
        preset, presetname = choose_preset(
            key, args.auphonic_preset, True, lufs=args.lufs,
            anyway=getattr(args, "anyway", False))
    except Exception as e:
        print(T('\nNo preset chosen: %s') % e)
        return 1
    folder = os.path.abspath(args.out) if args.out else os.path.dirname(
        os.path.abspath(video_paths[0]))
    print()
    try:
        done = run_multitrack_production(
            key, preset, title or 'Production', tracks, folder,
            args.auphonic_wait, args.dry_run, args.auphonic_resume,
            bool(getattr(args, "transcript", False)),
            speech_language_code(getattr(args, "speech_language", "")))
    except Exception as e:
        print(as_bad(T('Processing failed: %s') % e))
        return 1
    for track in tracks:
        track["done"] = done.get(track["name"])
    missing = [track["name"] for track in tracks if not track.get("done")]
    if missing and not args.dry_run:
        print(T('\nEnded without a result: %s') % ", ".join(missing))
        return 1

    if args.dry_run:
        print(T('\n  (measuring only: nothing written)'))
        return 0

    if not verify_returned_tracks(tracks, t1 - t0, tmpdir):
        return 1
    gain, curve = normalise_loudness(
        tracks, args.lufs, tmpdir,
        find_master_file(folder, args.out, os.path.dirname(video_paths[0])),
        channels=2)
    return distribute_tracks_to_cameras(
        args, tracks, cameras, videos, tmpdir, gain, position, t0, ref_clip,
        t1, curve=curve)


def check_written_file(target, items, n_camera, args, fps):
    """Measure in the finished file whether the new audio sits on the picture.

    Compared against the camera track using the overall mix, which carries
    the same voices as the camera microphone. A de-bled single track will
    not do: the other speakers are missing from it while the camera
    microphone still hears them.
    """
    if args.no_camera_audio or not n_camera:
        return
    index_number = next((i for i, (name, _) in enumerate(items)
                   if name.startswith("Full-Mix")), 0)
    try:
        HOP, rate = 5.0, 4000
        duration = float(ffprobe_json(target).get("format", {}).get("duration") or 0)
        env_fresh = envelope(decode_audio_long(target, rate, duration,
                                           T('Check: %s') % items[index_number][0],
                                           stream=index_number), HOP, rate)
        env_cam = envelope(decode_audio_long(target, rate, duration,
                                           T('Check: camera track'),
                                           stream=len(items)), HOP, rate)
        k, g = cross_correlate(env_cam, env_fresh)
    except Exception as e:
        print(T('  Check:           not possible (%s)') % e)
        return
    ms = k * HOP
    off = abs(ms) > 1000.0 / fps
    line = (T('  Check:           %s against the camera track %+.0f ms '
              '(match %.2f)%s')
            % (items[index_number][0], ms, g,
               T('   Caution: more than one frame') if off else ""))
    print(as_warn(line) if off else line)


def write_metrics_csv(file_path, tracks, cut, segment_list, cameras,
                         args, colours=None, gain=0.0):
    """Write the per-episode metrics as CSV, before against after.

    The log is overwritten on the next run; this file is not. Over a few
    months it shows what a single run hides: a recorder drifting, a camera
    looking increasingly unlike the rest, crosstalk rising with a new setup.

    "Before" is the track as it came in, "after" as it goes out. Both are
    measured the same way, otherwise the comparison would not be one.

    Area and Metric stay English in every language: two runs in different
    languages have to end up in the same table.
    """
    lines = []

    def line(area, what, before_value="", after="", unit=""):
        lines.append((area, what, before_value, after, unit))

    def number(x, spots=1):
        # A full stop, always: the file is read by other programs, and
        # what they see must not depend on the language of the run.
        return "" if x is None else "%.*f" % (spots, x)

    # --- audio per track
    for track in tracks:
        before = track.get("axis") or track.get("audio")
        after = track.get("ready")
        i0 = p0 = l0 = i1 = p1 = l1 = None
        if before and os.path.exists(before):
            i0, p0, l0 = measure_loudness(before, None, T('Before: %s') % track["name"])
        if after and os.path.exists(after):
            i1, p1, l1 = measure_loudness(after, None, T('After: %s') % track["name"])
        line('Audio ' + track["name"], 'Loudness', number(i0), number(i1), "LUFS")
        line('Audio ' + track["name"], 'Peak', number(p0), number(p1), "dBTP")
        line('Audio ' + track["name"], 'Loudness range', number(l0), number(l1), "LU")
        if track.get("drift_ppm") is not None:
            line('Audio ' + track["name"], 'Clock drift', number(track["drift_ppm"], 2),
                  "0", "ppm")
        if track.get("offset_ms") is not None:
            line('Audio ' + track["name"], 'Offset', number(track["offset_ms"], 2),
                  number(track.get("residual_ms"), 2), "ms")
    line('Audio', 'Gain on every track', "", number(gain, 2), "dB")
    line('Audio', 'Loudness target', "", number(getattr(args, "lufs", -16.0)),
          "LUFS")

    # --- the cut
    if cut:
        lengths = sorted(b - a for a, b, _n in cut)
        total = sum(lengths)
        line('Cut', 'Shots', "", "%d" % len(cut), "")
        line('Cut', 'Median hold time', "",
              number(lengths[len(lengths) // 2], 2), "s")
        line('Cut', 'shortest', "", number(lengths[0], 2), "s")
        line('Cut', 'longest', "", number(lengths[-1], 2), "s")
        per_camera = {}
        for a, b, n in cut:
            per_camera[n] = per_camera.get(n, 0.0) + (b - a)
        for n in sorted(per_camera, key=lambda x: -per_camera[x]):
            line('Cut', "Share %s" % n, "",
                  number(100.0 * per_camera[n] / total if total else 0), "%")

    # --- Speech time
    for name, segs in (segment_list or []):
        line('Speech time', name, "", number(sum(b - a for a, b in segs), 1), "s")

    # --- Colour
    for name, values, (dy, du, dv) in (colours or []):
        line('Colour ' + name, "Brightness", "", number(values.get("y")), "")
        line('Colour ' + name, 'Distance to mean', "", number(dy), "")
        line('Colour ' + name, "Colour position U / V", "",
              "%s / %s" % (number(du), number(dv)), "")

    try:
        with open(file_path, "w", encoding="utf-8") as f:
            f.write(csv_line(("Area", "Metric", "Before", "After",
                              "Unit")))
            for r in lines:
                f.write(csv_line(r))
    except OSError as e:
        print(T('  Metrics not writable: %s') % e)
        return None
    return file_path


def read_separation_file(file_path):
    """Read a stored separation out of a project or assignment file.

    Returns the dict with source, segments and names, or {}.
    """
    try:
        with open(file_path, encoding="utf-8") as f:
            d = json.load(f)
    except (OSError, ValueError) as e:
        print(T('  %s cannot be read: %s') % (os.path.basename(file_path), e))
        return {}
    if not isinstance(d, dict):
        return {}
    for key in ("speakers_of", "speakers"):
        entry = d.get(key)
        if isinstance(entry, dict) and entry.get("segments"):
            return entry
    return d if d.get("segments") else {}


def separation_on_axis(given, tracks, position, t0, t1):
    """Put a stored separation onto the axis of this run.

    The segments are kept raw, in the time of the file they were
    measured in. Where that file sits on the axis is already known from
    the alignment, so this is arithmetic and never a second
    measurement.

    Returns (segments, "") or ([], why not).
    """
    if not (given or {}).get("source"):
        return [], T('no recording named')
    # Looked up by the real path: /tmp is a link to /private/tmp on
    # macOS, and the same file then carries two names.
    source = os.path.realpath(given["source"])
    where = {}
    for track in tracks:
        blocks = track.get("blocks") or [track.get("source")]
        if blocks and blocks[0]:
            where[os.path.realpath(blocks[0])] = (track["a"], track["b"])
    for v, place in (position or {}).items():
        where[os.path.realpath(v)] = (place[0], place[1])
    if source not in where:
        return [], T('%s is not part of this run') % os.path.basename(source)
    a, b = where[source]
    if not b:
        return [], T('%s has no place on the axis') % os.path.basename(source)
    named = dict((given or {}).get("names") or {})
    out = []
    for label, parts in speaker_segments_polish(
            speaker_segments_group((given or {}).get("segments") or [])):
        kept = []
        for x, y in parts:
            x, y = (x - a) / b - t0, (y - a) / b - t0
            x, y = max(0.0, x), min(y, t1 - t0)
            if y > x:
                kept.append((round(x, 3), round(y, 3)))
        if kept:
            out.append((named.get(label) or label, kept))
    if not out:
        return [], T('nothing of it falls inside the window')
    return out, ""


def separation_source_of_run(args, tracks, video_paths):
    """Which recording a run without a window takes apart by voice.

    The same rule the window follows, on the same function: one
    recording everybody is audible on is the source, several
    microphones are the truth themselves and need no separation, and
    where there is no audio recording at all the camera track carries
    everybody.

    The boundary: which cameras were ticked by hand is not on the
    command line, so where the tracks come out of cameras all of them
    are offered. Returns (path, why) as speaker_source_pick does.
    """
    from_cameras = bool(getattr(args, "_camera_audio", None))
    recordings = []
    for track in tracks or ():
        for p in (track.get("blocks") or [track.get("source")]):
            if p and p not in recordings:
                recordings.append(p)
    return speaker_source_pick([] if from_cameras else recordings,
                               video_paths or (),
                               camera_audio=from_cameras)


def separation_for_run(args, tracks, position, t0, t1, video_paths=()):
    """Work out who speaks when, before the audio is processed.

    Four ways in, in this order: a separation handed over by the
    interface in the assignment file, one named with --speakers-from,
    the recording named with --speakers-local, and otherwise the
    recording this run picks itself. The window and the command line
    pick it by the same rule, so the same folder gives the same cut on
    both ways.

    --no-speakers-local leaves it out. The separation fetches an
    environment of a few hundred megabytes and computes for minutes,
    so both are said before it starts, and a dry run says them instead
    of doing them.

    Returns (segments, where they came from) with ([], "") for nothing.
    """
    given = getattr(args, "_speakers_of", None) or {}
    where_from = T('the interface') if given else ""
    if not given and getattr(args, "speakers_from", None):
        given = read_separation_file(args.speakers_from)
        where_from = os.path.basename(args.speakers_from)
    source = ""
    if not given and not getattr(args, "no_speakers_local", False):
        if getattr(args, "speakers_local", None):
            source = os.path.abspath(args.speakers_local)
        elif not SPEAKER_SPLIT_OFF:
            source = separation_source_of_run(args, tracks, video_paths)[0]
    if source:
        print(as_head(T('\nSEPARATING THE SPEAKERS')))
        print(T('  In %s, on this machine.') % os.path.basename(source))
        how_long = media_seconds(source)
        if how_long:
            print(T('  About %s of computing for %s of audio.')
                  % (as_hms(how_long / SPEAKER_SPLIT_SPEED),
                     as_hms(how_long)))
        if not speaker_split_available():
            print(T('  The environment for it is not here yet: about '
                    '%d MB are fetched now.') % SPEAKER_SETUP_MB)
        if getattr(args, "dry_run", False):
            print(T('  (measuring only: nothing separated)'))
            return [], ""
        if not speaker_split_available():
            trouble = speaker_split_setup(
                report=lambda text, share: show_progress(text, share))
            if trouble:
                print("  %s" % trouble)
                return [], ""
        segments, trouble = speaker_split_run(
            source, int(getattr(args, "speakers_count", 0) or 0),
            report=lambda text, share: show_progress(text, share))
        print()
        if trouble:
            print("  %s" % trouble)
            return [], ""
        given = {"source": source,
                 "segments": [[label, a, b] for label, parts in segments
                              for a, b in parts]}
        where_from = T('the separation in this run')
    if not given:
        return [], ""
    out, why_not = separation_on_axis(given, tracks, position, t0, t1)
    if not out:
        print(as_warn(T('  The speaker separation is not used: %s.')
                      % why_not))
        return [], ""
    return out, where_from


def speakers_for_the_cut(args, tracks):
    """Say who speaks when, and put the origin in the log.

    Either the separation this run carries -- one recording everybody
    is audible on, taken apart by voice -- or the measurement out of
    the separate tracks. The heading names which of the two, because
    the cut cannot be judged without knowing it.
    """
    segments, where_from = getattr(args, "_speakers", None) or ([], "")
    if segments:
        print(as_head(T('\nSPEAKERS -- SEPARATED BY VOICE')))
        print(T('  From %s: %d voices.') % (where_from, len(segments)))
    else:
        print(as_head(T('\nSPEAKERS -- MEASURED HERE')))
        print(T('  From the tracks themselves, one voice per track.'))
        segments = speakers_from_tracks(
            [(track["name"], track.get("ready") or track["axis"], 0.0)
             for track in tracks], note=print)
    for name, segs in segments:
        print(T('  %-20s %s in %d passages')
              % (name, as_hms(sum(b - a for a, b in segs)), len(segs)))
    if not any(segs for _, segs in segments):
        print(T('  Nothing was audible in the tracks -- no camera cut from '
                'this.'))
    return segments


def finish_without_auphonic(args, tracks, cameras, videos, tmpdir, position,
                            t0, t1, ref_clip):
    """Finish a multitrack run without auphonic.com.

    The tracks are aligned and equally long -- that is everything the mix
    and the cameras need. What is missing is what only auphonic.com does:
    taking the bleed out of the audio, the leveler, the noise removal. The
    loudness is set here as always; that computation was never remote.

    Who speaks when comes from the separation where this run carries
    one, otherwise it is measured from the tracks themselves. In that
    measurement the bleed is taken out of the *measurement*, not out of
    the audio -- without that, every microphone would report its
    neighbour as a speaker and the cut would stay on the wide shot.
    """
    step_begin("loudness")
    print(as_head(T('\nWITHOUT AUPHONIC.COM')))
    print(T('  The tracks are used as recorded: aligned, mixed and brought to '
            'the\n  target loudness. No de-bleed, no leveler, no noise '
            'removal -- for\n  those the run needs auphonic.com.'))
    for track in tracks:
        track["ready"] = track["axis"]
    if args.dry_run:
        print(T('\n  (measuring only: nothing written)'))
        return 0
    step_begin("speakers")
    segment_list = speakers_for_the_cut(args, tracks)
    folder = os.path.abspath(args.out) if args.out else os.path.dirname(
        os.path.abspath(videos[0][0]))
    gain, curve = normalise_loudness(tracks, args.lufs, tmpdir, None,
                                     channels=2)
    return distribute_tracks_to_cameras(
        args, tracks, cameras, videos, tmpdir, gain, position, t0,
        ref_clip, t1, curve, segment_list=segment_list)


def distribute_tracks_to_cameras(args, tracks, cameras, videos, tmpdir, gain,
              position, t0, ref_clip=None, t1=None, curve=None,
              segment_list=None):
    """Place the processed tracks onto the cameras.

    Without *segment_list* the speakers are worked out here: the run
    through auphonic.com comes in this way, and its tracks are cleaner
    to measure than the raw ones.
    """
    step_begin("cameras")
    if segment_list is None:
        step_begin("speakers")
        segment_list = speakers_for_the_cut(args, tracks)
    names_every = [track["name"] for track in tracks]
    after_camera = {}
    for track in tracks:
        if track.get("camera"):
            after_camera.setdefault(os.path.abspath(track["camera"]), []).append(track)

    track_names = {}          # output file -> names of its audio tracks
    offsets = {}          # output file -> measured offset in seconds
    print(as_head(T('\nMIXING')))
    # Mixes go out in two channels, single tracks in as many as they were
    # recorded with: the mix is what is delivered and measured, the single
    # track is what is worked with in the edit. A stereo track therefore
    # stays stereo on its own line and puts its sides into the mix.
    full_mix = mix_tracks([track["ready"] for track in tracks],
                        os.path.join(tmpdir, "mix_full.wav"), gain,
                        curve, channels=2)
    print(T('  Full-Mix from %d tracks, two channels') % len(tracks))

    # What is said and when, out of the finished mix. It runs beside
    # the cameras rather than in front of them: on a machine where the
    # recognition is slow it is the cameras that take the longer, and
    # the words are needed only when the cut is built at the end.
    # Without them the cut still happens -- the wide shot then looks
    # for the longest pause instead of the end of a sentence.
    heard = {}

    def listen_to_the_mix():
        """Write down the words of the mix, in a thread of its own."""
        words, _way = recognise_speech(
            full_mix, getattr(args, "speech_language", "") or "")
        heard["words"] = words or []

    listening = None
    if not getattr(args, "no_speech_recognition", False):
        listening = threading.Thread(target=listen_to_the_mix, daemon=True)
        listening.start()

    def heard_words():
        """Wait for the recognition and return what it heard."""
        if listening is not None:
            listening.join()
        return heard.get("words") or []

    single, in_stereo = {}, []
    for track in tracks:
        single[track["name"]] = mix_tracks(
            [track["ready"]],
            os.path.join(tmpdir, "single_%s.wav" % safe_filename(track["name"])),
            gain, curve)
        if kept_channels(single[track["name"]]) == 2:
            in_stereo.append(track["name"])
    if in_stereo:
        print(TN(len(in_stereo), '  %s stays in two channels',
                 '  %s stay in two channels') % ", ".join(in_stereo))
    camera_mix = {}
    for file_path, own in after_camera.items():
        camera_mix[file_path] = mix_tracks(
            [track["ready"] for track in own],
            os.path.join(tmpdir, "mix_%s.wav"
                         % safe_filename(os.path.basename(file_path))), gain,
            curve, channels=2)
        print(T('  %s: %s mixed together, two channels')
              % (os.path.basename(file_path),
                 " + ".join(track["name"] for track in own)))

    output_name = {os.path.abspath(cam["video"]): cam["name"] for cam in cameras}
    # The target names are settled before the threads start. Without a name
    # of its own a camera would write over an original -- its own or another
    # camera's, which a second thread may be reading at that moment -- and
    # two cameras with the same file name would write the same file at once.
    output_path, taken = {}, set()
    sources = set(os.path.abspath(_v).lower() for _v, _i in videos)
    for _v, _info in videos:
        _v = os.path.abspath(_v)
        stem = output_name.get(_v) or os.path.splitext(
            os.path.basename(_v))[0]
        outdir = os.path.abspath(args.out) if args.out else os.path.dirname(_v)
        target = os.path.join(outdir, stem + ".mov")
        count = 1
        while target.lower() in sources or target.lower() in taken:
            count += 1
            tail = args.suffix or "_audio"
            target = os.path.join(outdir, "%s%s%s.mov"
                                  % (stem, tail,
                                     "" if count == 2 else "_%d" % count))
        taken.add(target.lower())
        output_path[_v] = (outdir, target)
    results, error = [], 0
    def one_camera(v, info, share):
        """Finish one camera: measure, write, verify.

        Runs in its own thread. Everything printed here collects in that
        thread's buffer and comes out in one piece once the file is done --
        three interleaved reports would be unreadable. Progress goes to the
        shared bar instead.
        """
        v = os.path.abspath(v)
        own = after_camera.get(v, [])
        print(as_head(T('\nPROCESSING: %s') % os.path.basename(v)))
        items = []
        if own:
            items.append(('Mix ' + " + ".join(track["name"] for track in own)
                          if len(own) > 1 else own[0]["name"],
                          camera_mix[v]))
            if len(own) > 1:
                for track in own:
                    items.append((track["name"], single[track["name"]]))
            if set(track["name"] for track in own) != set(names_every):
                items.append(("Full-Mix", full_mix))
        else:
            items.append(("Full-Mix", full_mix))
        # Where the camera sits on the axis is already known: building the time
        # axis measured every camera against the reference, with the
        # microphones and hundreds of sample points. Repeating that against a
        # de-bled speaker track would be worse, not better: after de-bleeding
        # only one speaker is on the track while the camera microphone hears
        # them all, and the correlation finds little to hold on to.
        if v not in position:
            print(T('  This camera could not be placed -- skipped'))
            return None
        a_cam, b_cam, st = position[v]
        a = -a_cam / b_cam - t0
        b = 1.0 / b_cam
        # Cross-check: the same offset, this time from the overall mix. That is
        # identical on every camera and holds the same voices as the camera
        # microphone. Where the two routes disagree something is wrong, and
        # that should show here rather than on playback.
        share.segment(0.0, 0.30)
        check = next((p for n, p in items if n.startswith("Full-Mix")),
                     items[0][1])
        try:
            HOP, rate = 5.0, 4000
            env_video = video_envelope(v, HOP, rate)
            env_audio = envelope(decode_audio(check, rate=rate), HOP, rate)
            density = int(max(20, min(120, info["duration"] / 30.0)))
            a2, b2, st2 = align_envelopes(env_video, env_audio, HOP, sample_points=density,
                                             distance_s=30.0, points_off="audio")
            deviation = a2 - a
        except Exception as e:
            a2, st2, deviation = None, {}, None
            print(T('  Cross-check:     not possible (%s)') % e)
        fps = max(1.0, info["fps"])
        total = (b - 1.0) * info["duration"]
        uncertainty = st.get("ppm_error", 0.0) / 1e6 * info["duration"]
        threshold = max(0.010, 0.5 / fps)
        drift = (not args.no_drift
                 and abs(total) > 4 * uncertainty and abs(total) > threshold
                 and abs(st.get("ppm", 0.0)) < 500 and info["duration"] >= 120)
        print(T('  Offset:          %s   (from the camera comparison)') % as_hms(a))
        if a2 is not None:
            serious = abs(deviation) > 1.0 / fps
            print(T('  Cross-check:     %s from the Full-Mix, deviation '
                    '%+.0f ms (%d of %d points)%s')
                  % (as_hms(a2), deviation * 1000.0, st2.get("points", 0),
                     st2.get("candidates", 0),
                     T('   Caution: more than one frame') if serious else ""))
        print(T('  Clock drift:     %+.2f ppm (+/- %.2f), residual spread '
                '%.1f ms, %d of %d points')
              % ((b - 1.0) * 1e6, st.get("ppm_error", 0.0),
                 st.get("spread_ms", 0.0), st.get("points", 0),
                 st.get("candidates", 0) or 0))
        print(T('  Drift over the running time: %+.3f s = %.1f frames  -->  %s') % (total, abs(total) * fps,
                             T('is actively taken out') if drift
                             else T('is left in')))
        print()
        outdir, target = output_path[v]
        os.makedirs(outdir, exist_ok=True)
        share.segment(0.30, 0.85)
        try:
            write_camera_file(v, info, items, target, a, b, drift, args)
        except Exception as e:
            print(as_bad(T('  Error while writing: %s') % e))
            return None
        track_names = [name for name, _ in items]
        for i, (name, _) in enumerate(items, 1):
            print(T('  Audio track %d:   %s') % (i, name))
        if not args.no_camera_audio and info["audio"]:
            print(T('  Audio track %d:   %s') % (len(items) + 1,
                                              args.name_camera))
        if info["tc"]:
            print("  Timecode:        %s" % info["tc"])
        share.segment(0.85, 1.0)
        check_colour_survived(v, target)
        # ffmpeg drops what it does not know. For iPhone recordings "logs"
        # holds the recording curve, which is how Resolve recognises Apple Log.
        # It is copied byte for byte from the source.
        try:
            after = copy_mov_atoms(v, target)
        except Exception as e:
            after = []
            print(T('  Camera atoms:    cannot be added (%s)') % str(e)[:60])
        if after:
            print(T('  Camera atoms:    %s added -- %s')
                  % (", ".join(after),
                     log_curve_from_atom(_logs_atom_text(target)) or T('no text')))
        check_camera_metadata(v, target)
        check_written_file(target, items, len(info["audio"]), args, fps)
        return target, track_names, a

    # The expensive part is the cross-check, and that only computes. ffmpeg
    # merely copies the picture and waits on the disk. Together they saturate
    # a machine only with several files running at once.
    how_many = getattr(args, "parallel", 0) or min(
        len(videos), max(1, min(4, how_many_processors() // 2)))
    how_many = max(1, min(how_many, len(videos)))
    progress_bar = SharedProgressBar(T('Processing'), len(videos))

    def one(v, info):
        ident = threading.get_ident()
        THREAD_BUFFER[ident] = []
        THREAD_SHARE[ident] = Share(progress_bar, v)
        try:
            return one_camera(os.path.abspath(v), info, THREAD_SHARE[ident])
        except Exception as e:
            print(T('\n  Stopped: %s') % e)
            return None
        finally:
            THREAD_SHARE[ident].report(1.0)
            THREAD_SHARE.pop(ident, None)
            one_camera.texts[v] = "".join(THREAD_BUFFER.pop(ident, []))

    one_camera.texts = {}
    old_off = sys.stdout
    progress_bar.stream = old_off
    sys.stdout = ThreadOutput(old_off)
    try:
        with futures.ThreadPoolExecutor(max_workers=how_many) as pool:
            job = {pool.submit(one, v, info): v for v, info in videos}
            for done_future in futures.as_completed(job):
                v = job[done_future]
                sys.stdout.write("\n" + one_camera.texts.get(v, ""))
                what = done_future.result()
                if what is None:
                    error += 1
                    continue
                target, names, offset = what
                track_names[target] = names
                offsets[target] = offset   # camera position in the window
                results.append(target)
    finally:
        sys.stdout = old_off
    progress_bar.stop()
    # Back in file order, not in the order of completion.
    order = [os.path.abspath(x) for x, _ in videos]
    results.sort(key=lambda path: order.index(os.path.abspath(path))
                    if os.path.abspath(path) in order else len(order))

    # --- keep the finished tracks, not only hidden inside the videos
    folder = os.path.abspath(args.out) if args.out else os.path.dirname(
        os.path.abspath(videos[0][0]))
    cache = tracks_folder(folder)
    tc_start = None
    if ref_clip and ref_clip[1].get("tc"):
        tc_start = parse_timecode(ref_clip[1]["tc"], max(1.0, ref_clip[1]["fps"]))\
            + t0 if t0 is not None else None
    print(as_head(T('\nSAVING TRACKS')))
    tc_fps = max(1.0, ref_clip[1]["fps"]) if ref_clip else 30.0
    stored = []
    single_files = {}      # speaker name -> stored WAV
    tc_name = ("_" + timecode_string(tc_start, tc_fps).replace(":", "-"))\
        if tc_start is not None else ""
    for name, source in ([(track["name"], single[track["name"]]) for track in tracks]
                         + [("Full-Mix", full_mix)]):
        target = os.path.join(cache,
                            "final_%s%s.wav" % (safe_filename(name), tc_name))
        show_progress(T('Saving %s') % name, 0.0)
        command = ["ffmpeg", "-v", "error", "-i", source, "-c:a", "copy"]
        if tc_start is not None:
            command += ["-write_bext", "1", "-metadata",
                       "time_reference=%d" % int(round(tc_start * SR))]
        shell_quote(command + ["-y", target])
        if tc_start is not None:
            # Resolve reads bext; Premiere and Media Composer read iXML.
            try:
                append_ixml(target, build_ixml(
                    name, int(round(tc_start * SR)), tc_fps, 24, 1,
                    is_drop_frame(ref_clip[1].get("tc") if ref_clip else None)))
            except Exception as e:
                print(T('  iXML for %s not written: %s')
                      % (os.path.basename(target), e))
        stored.append(target)
        single_files[name] = target
        show_progress(T('Saving %s') % name, 1.0)
        print("\r  %-24s %s%s" % (os.path.basename(target),
                                  as_hms(sample_count(target) / float(SR)),
                                  " " * 20))
    if tc_start is not None:
        print(T('  Timecode %s written as bext and iXML (reference: %s)')
              % (timecode_string(tc_start, tc_fps),
                 os.path.basename(ref_clip[0])))

    if results:
        print(as_head(T('\nRESULT')))
        for path in results:
            print("  %s" % path)
        for path in stored:
            print("  %s" % path)

    cut, segment_list = write_cut_list(
        args, segment_list, tracks, cameras, videos, folder, tc_start,
        ref_clip, t1 - t0 if t1 is not None else 0,
        words=heard_words(), sound_source=single_files.get("Full-Mix", ""))
    if not getattr(args, "no_transcript_file", False) and heard_words():
        print(as_head(T('\nTRANSCRIPT')))
        for path in write_transcript_files(
                folder, safe_filename(args.production or 'Production'),
                heard_words(), segment_list):
            print("  %s" % path)
    colours = []
    if not getattr(args, "no_metrics", False):
        try:
            colours = report_picture_comparison(
                [{"track": cam.get("name"), "file": p}
                 for cam, p in zip(cameras, results)]
                if len(results) == len(cameras) else
                [{"track": cam.get("name"), "file": cam.get("video")}
                 for cam in cameras])
        except Exception as e:
            print(T('  Colour comparison not possible: %s') % e)
        print(as_head(T('\nMETRICS')))
        target = write_metrics_csv(
            os.path.join(folder, "%s_metrics.csv"
                         % safe_filename(args.production or 'Production')),
            tracks, cut, segment_list, cameras, args, colours, gain)
        if target:
            print("  %s" % target)
    write_handover(args, tracks, cameras, videos, folder, tc_start,
                      ref_clip, results, cut, segment_list,
                      t1 - t0 if t1 is not None else 0, track_names,
                      single_files, offsets, words=heard_words())
    shutil.rmtree(tmpdir, ignore_errors=True)
    return 1 if error else 0


# ------------------------------------------------------------ Resolve
#
# Everything to do with DaVinci Resolve. The scripting interface has no
# multicam: the word does not appear once in Resolve's own README (version 21).
# Project, import, timelines, track names and markers can be driven remotely;
# converting to a multicam clip stays a right click. The track name becomes the
# name of the angle -- that is in the manual, chapter 49, and this whole part
# rests on it.

MARKER_COLOURS = ["Blue", "Cyan", "Green", "Yellow", "Red", "Pink", "Purple",
                 "Fuchsia", "Rose", "Lavender", "Sky", "Mint", "Lemon",
                 "Sand", "Cocoa", "Cream"]


def resolve_module_paths():
    """Return the possible locations of the Resolve scripting interface."""
    api = os.environ.get("RESOLVE_SCRIPT_API")
    lib = os.environ.get("RESOLVE_SCRIPT_LIB")
    if api and lib:
        return api, lib
    if sys.platform == "darwin":
        api = ("/Library/Application Support/Blackmagic Design/"
               "DaVinci Resolve/Developer/Scripting")
        for app in ("DaVinci Resolve", "DaVinci Resolve Studio"):
            lib = ("/Applications/DaVinci Resolve/%s.app/Contents/Libraries/"
                   "Fusion/fusionscript.so" % app)
            if os.path.exists(lib):
                return api, lib
        return api, lib
    if os.name == "nt":
        pd = os.environ.get("PROGRAMDATA", r"C:\ProgramData")
        pf = os.environ.get("PROGRAMFILES", r"C:\Program Files")
        return (os.path.join(pd, "Blackmagic Design", "DaVinci Resolve",
                             "Support", "Developer", "Scripting"),
                os.path.join(pf, "Blackmagic Design", "DaVinci Resolve",
                             "fusionscript.dll"))
    return ("/opt/resolve/Developer/Scripting",
            "/opt/resolve/libs/Fusion/fusionscript.so")


def resolve_installed():
    """Report whether Resolve is installed.

    Only the files are checked; this says nothing about whether the program
    is running. It is enough to disable the checkbox where there would be
    nothing to reach anyway.
    """
    api, lib = resolve_module_paths()
    return os.path.isdir(api) and os.path.exists(lib)


def connect_to_resolve():
    api, lib = resolve_module_paths()
    if not os.path.isdir(api) or not os.path.exists(lib):
        raise RuntimeError(T('The Resolve interface is not where I expect '
                             'it:\n  %s\n  %s') % (api, lib))
    os.environ["RESOLVE_SCRIPT_API"] = api
    os.environ["RESOLVE_SCRIPT_LIB"] = lib
    modules_path = os.path.join(api, "Modules")
    if modules_path not in sys.path:
        sys.path.append(modules_path)
    try:
        import DaVinciResolveScript as drs
    except ImportError as e:
        raise RuntimeError(T('Module DaVinciResolveScript cannot be loaded: %s') % e)
    r = drs.scriptapp("Resolve")
    if r is None:
        raise RuntimeError(
            T('No connection to Resolve.\n  Is the program running? Is '
              "external scripting set to 'Local'\n  under Preferences > "
              'System > General?'))
    return r


# Why the connection can fail. The third point is uncertain: a statement by
# Blackmagic that external scripting is reserved for the Studio edition appears
# neither in the interface README nor in the official documentation. It is
# reported for version 19.1 and later.
RESOLVE_REASONS = (
    ('Possible reasons:\n  1. Resolve is not running -- the interface '
     'answers only while the program runs.\n  2. Preferences > System > '
     'General: external scripting is set to "None" instead of "Local".\n  '
     '3. Free edition: external scripting is reported to be reserved for '
     'the Studio edition since version 19.1. I found no official '
     'statement -- this check measures it instead of claiming it.'))


def check_resolve():
    """Report what can be reached of Resolve. Returns (works, lines).

    In order: is the interface there, does the program answer, which edition
    is it, which project is open. Each stage reports separately, so the
    result says not just that it failed but how far it got.
    """
    api, lib = resolve_module_paths()
    lines = [T('Interface:      %s%s') % (api, "" if os.path.isdir(api)
                                        else T('   -- not found')),
              T('Library:        %s%s') % (lib, "" if os.path.exists(lib)
                                        else T('   -- not found'))]
    if not (os.path.isdir(api) and os.path.exists(lib)):
        return False, lines + ["", T('Without these two nothing works. Is '
                                     'Resolve installed?')]
    try:
        r = connect_to_resolve()
    except RuntimeError as e:
        return False, lines + ["", str(e), "", T(RESOLVE_REASONS)]

    def ask(how):
        try:
            return str(how()) or ""
        except Exception:
            return ""

    # Where it works, one bracket is enough. The paths only matter where it
    # does not.
    what = " ".join(x for x in (ask(r.GetProductName),
                               ask(r.GetVersionString)) if x)
    return True, [what]


def seconds_to_frames(seconds, fps):
    """Convert a duration to frames using the true rate; 29.97 stays 29.97."""
    return int(round(seconds * fps))


RESOLVE_FRAME_RATES = (23.976, 24.0, 25.0, 29.97, 30.0, 47.952, 48.0, 50.0,
                 59.94, 60.0, 72.0, 95.904, 96.0, 100.0, 119.88, 120.0)


def nearest_known_frame_rate(fps):
    """Round a frame rate to one Resolve knows.

    ffprobe measures 29.994 or 30.001 for some files -- averaged values, not
    real rates. Resolve rejects those and picks something itself, once 29.97
    and once 30. Better to decide here and say what was done.
    """
    if not fps:
        return 30.0
    return min(RESOLVE_FRAME_RATES, key=lambda r: abs(r - fps))


def frames_to_timecode(frames, fps, drop_frame=False):
    """The other way round: a frame number since midnight as a timecode.

    Counts on the timecode clock, like timecode_to_frames -- thirty frames
    per second at 29.97. Dividing by the true rate instead would put the
    result about a minute per hour off.
    """
    full = int(round(nearest_known_frame_rate(fps)))
    n = max(0, int(frames)) % (full * 86400)
    if drop_frame:
        dropped = 2 * full // 30
        per_ten = full * 600 - dropped * 9
        tens, rest = divmod(n, per_ten)
        per_minute = full * 60 - dropped
        # The first minute of every ten drops nothing, the nine after it do.
        n += dropped * 9 * tens
        if rest >= dropped:
            n += dropped * ((rest - dropped) // per_minute)
    f = n % full
    s = n // full
    return "%02d:%02d:%02d%s%02d" % (s // 3600 % 24, s % 3600 // 60, s % 60,
                                     ";" if drop_frame else ":", f)


def timecode_to_frames(tc, fps):
    """Convert a timecode to a frame number since midnight.

    Not with the true rate: a non-drop timecode still counts thirty frames
    per second at 29.97, so its second is not a second of the clock. Drop
    frame skips numbers at regular intervals instead.
    """
    if not tc:
        return 0
    df = ";" in str(tc)
    t = str(tc).replace(";", ":").split(":")
    if len(t) != 4:
        return 0
    h, m, s, f = (int(x) for x in t)
    full = int(round(nearest_known_frame_rate(fps)))          # 30 at 29.97
    n = ((h * 3600 + m * 60 + s) * full) + f
    if df:
        # Two numbers dropped per minute, except every tenth minute.
        dropped = 2 * full // 30
        minutes = h * 60 + m
        n -= dropped * (minutes - minutes // 10)
    return n


def open_or_create_project(pm, name, carry_on=None):
    """Create or open a project, asking if one already exists.

    Returns (project, kind), where kind says what to do with it:
    "created", "update" or "keep".
    """
    existing = pm.GetProjectListInCurrentFolder() or []
    if name not in existing:
        p = pm.CreateProject(name)
        if p is None:
            raise RuntimeError(T('Project %r could not be created. Is the '
                                 'name already in another folder?') % name)
        print(T('  Project %r created.') % name)
        return p, "created"
    print(T('\n  A PROJECT WITH THIS NAME ALREADY EXISTS: %r') % name)
    choice = ask_choice(
        [("update",
          T('bring up to date -- both Timelines are deleted and\n       '
            'rebuilt, the media pool stays as it is')),
         ("keep", T('leave it and put the new Timelines alongside --\n      '
                    ' the existing ones stay')),
         ("new", T('create a new project alongside (name with suffix)')),
         ("abort", T('cancel'))],
        T('What should happen with it?'), T('This Resolve project already exists'),
        carry_on, "--resolve-project")
    if choice == "abort":
        raise RuntimeError(T('Stopped. Nothing was created.'))
    if choice in ("update", "keep"):
        p = pm.LoadProject(name)
        if p is None:
            raise RuntimeError(T('Project %r could not be opened.') % name)
        print(T('  Project %r opened.') % name)
        return p, choice
    for k in range(2, 100):
        fresh = "%s %d" % (name, k)
        if fresh not in existing:
            p = pm.CreateProject(fresh)
            if p is None:
                raise RuntimeError(T('Project %r could not be created.') % fresh)
            print(T('  Project %r created.') % fresh)
            return p, "created"
    raise RuntimeError(T('Too many projects with this name.'))


def same_setting_value(a, b):
    """Report whether two setting values are the same.

    Resolve returns 30.0 when 30 was set. Comparing character by character
    fails -- "30".rstrip("0") is "3" -- so they are compared as numbers, and
    only as text when that is impossible.
    """
    try:
        return abs(float(a) - float(b)) < 1e-6
    except (TypeError, ValueError):
        return str(a).strip() == str(b).strip()


def apply_project_settings(p, d):
    """Set frame rate, drop frame and resolution, then verify they took."""
    value = "%g" % nearest_known_frame_rate(d.get("fps") or 30.0)
    if d.get("fps_measured") and abs(d["fps_measured"]
                                     - nearest_known_frame_rate(d["fps"])) > 0.001:
        print(T('    Measured %g frames/s -- Resolve only knows fixed '
                'rates,\n    %s is used.')
              % (d["fps_measured"], value))
    applied = []
    for api_key, value in (("timelineFrameRate", value),
                          ("timelinePlaybackFrameRate", value),
                          ("timelineDropFrameTimecode",
                           "1" if d.get("drop_frame") else "0"),
                          ("timelineResolutionWidth",
                           str(d.get("width") or "")),
                          ("timelineResolutionHeight",
                           str(d.get("height") or ""))):
        if not value:
            continue
        p.SetSetting(api_key, value)
        now = p.GetSetting(api_key)
        applied.append((api_key, value, now, same_setting_value(now, value)))
    for api_key, value, now, matches in applied:
        print("    %-28s %-10s %s" % (api_key, now,
                                      "" if matches else T('(wanted %s)') % value))
    if any(not x[3] for x in applied):
        print(T('    Not everything could be set. Resolve takes some '
                'values only\n    while the Timeline is still empty -- '
                'please compare above.'))


def set_remote_grades(p, on=False):
    """Turn remote grades off, and keep them off.

    Remote grades ("Use local version for new clips in timeline" unchecked)
    tie every clip of the same source file together: a change on one
    propagates to all.

    Colour groups do the same and do it more finely: in the node editor
    "Group Pre-Clip" applies to every clip of the group, "Clip" only to the
    selected one. Remote grades additionally glue the clip level together,
    and then a single cut can no longer be corrected on its own.

    Set on every run, because a project from an earlier run may still have
    them on. The change only affects clips added to a timeline afterwards,
    hence here, before anything is built.

    The setting's name is not documented, so it is not guessed: all settings
    are fetched and the matching one is picked out.
    """
    try:
        every = p.GetSetting("")
    except Exception:
        every = None
    if not isinstance(every, dict):
        print(T('    Settings not listable -- please set by hand:\n    '
                "Project Settings > General Options > Color > 'Use local "
                "version for new clips' %s.") % (T('off') if on else T('on')))
        return None
    hit = [k for k in every
               if "local" in k.lower() and "version" in k.lower()]
    if not hit:
        print(T('    No setting for the versions found -- please set by '
                'hand:\n    Project Settings > General Options > Color > '
                "'Use local version for new clips' %s.")
              % (T('off') if on else T('on')))
        return None
    api_key = hit[0]
    wanted = "0" if on else "1"
    p.SetSetting(api_key, wanted)
    now = p.GetSetting(api_key)
    matches = same_setting_value(now, wanted)
    print("    %-28s %-10s %s" % (api_key, now,
                                  "" if matches else T('(wanted %s)') % wanted))
    if not matches:
        return matches
    if on:
        print(T('    Remote grades are on: one colour correction per '
                'camera applies\n    to all its cuts -- a single cut can '
                'then no longer be corrected\n    on its own.'))
    else:
        print(T('    Local versions: in the node editor "Group Pre-Clip" '
                'applies to the\n    whole camera, "Clip" only to the one '
                'cut. One does not exclude\n    the other.'))
    return matches


# What YouTube recommends for upload, in kbit/s. For ranges the upper value is
# used: the upload happens once, and what is lost in their re-encode nobody
# gets back. HFR means high frame rates -- 48, 50, 60.
#                    height  SDR    SDR-HFR  HDR    HDR-HFR
RENDER_BITRATE = ((4320, 160000, 240000, 200000, 300000),
                  (2160,  45000,  68000,  56000,  85000),
                  (1440,  16000,  24000,  20000,  30000),
                  (1080,   8000,  12000,  10000,  15000),
                  (720,    5000,   7500,   6500,   9500),
                  (0,      2500,   4000,   3000,   4500))
# Stereo -- and we output two channels, see the mix.
RENDER_AUDIO_KBIT = 384


def bitrate_for(height, fps=30.0, hdr=False):
    """Return the bitrate in kbit/s for height, frame rate and HDR."""
    column = (3 if hdr else 1) + (1 if (fps or 0) > 30.5 else 0)
    for row in RENDER_BITRATE:
        if (height or 0) >= row[0]:
            return row[column]
    return RENDER_BITRATE[-1][column]


# Transfer characteristic codes per ITU-T H.273. 16 is PQ, 18 is HLG, both HDR
# markers. 9 as colour space is BT.2020.
TRC_HDR = {16: "PQ", 18: "HLG"}
# Log is not a display curve but a recording curve: it preserves the dynamic
# range the camera sees and is converted to something else for delivery. For
# output that means the same as HDR -- eight bit is not enough and gradients
# would band. 21 is the code Apple Log carries in the file.
TRC_LOG = {21: "Apple Log"}
PRIMARIES_BT2020 = 9
# Another way to spot log: the cameras write it into their QuickTime keys.
# Searched by word markers rather than by "log", which hides in too many
# harmless words.
LOG_MARKERS = ("apple log", "applelog", "s-log", "slog", "v-log", "vlog",
              "log3", "logc", "c-log", "clog", "f-log", "flog",
              "blackmagic design film", "bmd film", "arri logc",
              "redlogfilm", "log gamma")


# Names for the ITU-T H.273 codes. Anything not in the list is shown as a
# number rather than guessed. 2 means "unspecified" in both lists: the file
# says nothing about its colour.
PRIMARIES_NAMES = {0: 'reserved', 1: "BT.709", 2: 'unspecified',
                   4: "BT.470 M", 5: "BT.470 B/G", 6: "BT.601 (SMPTE 170M)",
                   7: "SMPTE 240M", 8: "Film", 9: "BT.2020", 10: "XYZ",
                   11: "DCI-P3", 12: "Display P3", 22: "EBU 3213-E"}
MATRIX_NAMES = {0: "GBR", 1: "BT.709", 2: 'unspecified', 4: "FCC",
                5: "BT.470 B/G", 6: "BT.601 (SMPTE 170M)", 7: "SMPTE 240M",
                8: "YCgCo", 9: "BT.2020", 10: 'BT.2020 constant',
                11: "SMPTE ST 2085", 14: "ICtCp"}
MATRIX_BT2020 = 9
TRC_NAMES = {0: 'reserved', 1: "BT.709", 2: 'unspecified',
             4: "Gamma 2.2", 5: "Gamma 2.8", 6: "BT.601 (SMPTE 170M)",
             7: "SMPTE 240M", 8: "linear", 11: "xvYCC", 13: "sRGB",
             14: "BT.2020 10 bit", 15: "BT.2020 12 bit", 16: "PQ (HDR10)",
             17: "SMPTE ST 428-1", 18: "HLG", 21: "Apple Log"}


def _log_in_colour_tags(tags):
    """Report whether the colour tags say the source was recorded in log."""
    for api_key, value in (tags or {}).items():
        if not str(api_key).startswith("com."):
            continue
        hay = ("%s %s" % (api_key, value)).lower()
        for label in LOG_MARKERS:
            if label in hay:
                return "%s = %s" % (api_key, value)
    return ""


def _log_gamma_in_metadata(file_path):
    """Report whether the camera metadata says log was recorded."""
    try:
        return _log_in_colour_tags(camera_metadata(file_path))
    except Exception:
        return ""


def bit_depth(v):
    """Return the bits per colour channel of the video track."""
    n = v.get("bits_per_raw_sample")
    if n:
        try:
            return int(n)
        except (TypeError, ValueError):
            pass
    fmt = str(v.get("pix_fmt") or "")
    for k in (16, 14, 12, 10):
        if "p%d" % k in fmt:
            return k
    return 8 if fmt else 0


def colour_text(file_path, v, tags):
    """Describe colour space, curve and bit depth of a video file in one line.

    The numbers come from the colr box, not from ffprobe's names: for Apple
    Log ffprobe reports a curve that is wrong.
    """
    values = mov_colour_tags(file_path)
    # Apple writes the recording curve into the logs atom of the sample
    # description rather than into the colr box. That is the only way Resolve
    # knows Apple Log is present; colr says nothing about it.
    curve = log_curve_from_atom(_logs_atom_text(file_path))
    parts, hdr = [], bool(curve)
    if curve:
        parts.append(curve)
    if values:
        prim, trc, mat, full = values
        if trc != 2:
            parts.append(T(TRC_NAMES.get(trc, ''))
                         or T('Curve number %d') % trc)
        if prim != 2:
            parts.append(PRIMARIES_NAMES.get(prim,
                                             T('Primaries number %d') % prim))
        # Where the matrix says the same as the primaries, once is enough.
        if (mat and mat != 2
                and MATRIX_NAMES.get(mat) != PRIMARIES_NAMES.get(prim)):
            parts.append("Matrix %s"
                         % MATRIX_NAMES.get(mat, T('Number %d') % mat))
        if not parts:
            parts.append(T('Curve and colour space are missing from the file'))
        # The matrix counts too: some cameras write only that and leave curve
        # and primaries empty. BT.2020 as a matrix is still a statement about
        # the range of the material.
        hdr = hdr or (trc in TRC_HDR or trc in TRC_LOG
                      or prim == PRIMARIES_BT2020 or mat == MATRIX_BT2020)
        if full:
            parts.append(T('full range'))
    else:
        for api_key in ("color_transfer", "color_primaries"):
            if v.get(api_key):
                parts.append(str(v[api_key]))
    n = bit_depth(v)
    if n:
        parts.append("%d bit" % n)
    source_text = _log_in_colour_tags(tags)
    if source_text and not hdr:
        parts.append(T('Log according to camera data'))
        hdr = True
    if hdr:
        parts.append("HDR")
    return ", ".join(parts) if parts else T('no information in the file')


def camera_text(tags):
    """Return the device and recording app, as far as the file names them."""
    d = {}
    for api_key, value in sorted((tags or {}).items()):
        short = str(api_key).rsplit(".", 1)[-1].lower()
        if short in ("make", "model", "software", "firmware") and str(value).strip():
            d.setdefault(short, str(value).strip())
    maker, model = d.get("make", ""), d.get("model", "")
    if model.lower().startswith(maker.lower()) and maker:
        device = model           # some write the manufacturer into it as well
    else:
        device = " ".join(x for x in (maker, model) if x)
    software = d.get("software") or d.get("firmware") or ""
    if device and software:
        return "%s  --  Software %s" % (device, software)
    return device or software or T('no information in the file')


# What a finished file has to carry for a player to recognise HDR -- the ITU-T
# H.273 codes. 9 as primaries is BT.2020, 16 is PQ (SMPTE ST 2084), 18 is HLG,
# 9 as matrix is BT.2020 non-constant luminance. 14 looks similar but is SDR in
# the BT.2020 space and does not qualify.
HDR_PRIMARIES = 9
HDR_MATRIX = 9
HDR_CURVES = {16: "PQ (HDR10)", 18: "HLG"}


def hdr_static_metadata(file_path):
    """Return which HDR static metadata a file carries.

    ffprobe attaches mastering display and content light level to the first
    frame rather than to the stream, and depending on the file they appear
    as a container box or as SEI in the bitstream. So the first frame is
    what gets queried.

    Returns the set of kinds found.
    """
    try:
        raw = subprocess.run(
            ["ffprobe", "-v", "error", "-select_streams", "v:0",
             "-read_intervals", "%+#1", "-show_frames",
             "-show_entries", "frame=side_data_list",
             "-print_format", "json", file_path],
            capture_output=True).stdout
        d = json.loads(raw or b"{}")
    except Exception:
        return set()
    out = set()
    for video in (d.get("frames") or []):
        for part in (video.get("side_data_list") or []):
            kind = str(part.get("side_data_type") or "").lower()
            if "mastering display" in kind:
                out.add("mdcv")
            elif "content light" in kind:
                out.add("clli")
    return out


def hdr_findings(file_path):
    """Check whether a finished file carries everything that marks it HDR.

    Checked against the file, not against the intent. Four things have to be
    right -- primaries, curve, matrix and bit depth -- everything else is a
    bonus. Returns a list of Finding.
    """
    out = []
    if not file_path or not os.path.isfile(file_path):
        return [Finding("abort", T('File'), T('does not exist: %s') % file_path)]
    values = mov_colour_tags(file_path)
    if not values:
        out.append(Finding(
            "abort", "colr box",
            T('missing -- the container carries no colour tagging'),
            T('Without it every player has to guess, and all guess SDR. In '
              'Resolve under Deliver > Advanced Settings set the Color '
              'space tag and the Gamma tag instead of leaving them at '
              '"Same as Project".')))
        prim = trc = mat = None
    else:
        prim, trc, mat, full = values
        out.append(Finding(
            "good" if prim == HDR_PRIMARIES else "hint", T('Primaries'),
            "%d (%s)" % (prim, T(PRIMARIES_NAMES.get(prim, 'unknown'))),
            "" if prim == HDR_PRIMARIES else
            T('HDR needs 9 here (BT.2020). In Resolve: Color space tag = '
              'Rec.2020.')))
        out.append(Finding(
            "good" if trc in HDR_CURVES else "hint", T('Curve'),
            "%d (%s)" % (trc, HDR_CURVES.get(trc)
                         or T(TRC_NAMES.get(trc, 'unknown'))),
            "" if trc in HDR_CURVES else
            T('HDR needs 16 here (PQ, that is HDR10) or 18 (HLG). In '
              'Resolve: Gamma tag = ST.2084 or HLG. 14 is not an HDR curve '
              'but SDR in the BT.2020 space.')))
        out.append(Finding(
            "good" if mat == HDR_MATRIX else "hint", "Matrix",
            "%d (%s)" % (mat, T(MATRIX_NAMES.get(mat, 'unknown'))),
            "" if mat == HDR_MATRIX else
            T('HDR needs 9 here (BT.2020, non-constant luminance).')))
        if full is not None:
            out.append(Finding(
                "good", T('Value range'),
                T('full range') if full else T('limited (Video/TV)'),
                "" if not full else
                T('Delivery usually takes the limited range. Full is not '
                  'wrong, but some players misread it.')))
    try:
        d = ffprobe_json(file_path)
    except Exception:
        d = {}
    track = next((x for x in (d.get("streams") or [])
                 if x.get("codec_type") == "video"), {})
    depth = bit_depth(track)
    out.append(Finding(
        "good" if depth >= 10 else "abort", T('Bit depth'),
        "%d bit%s" % (depth, "" if depth else T(' -- not readable')),
        "" if depth >= 10 else
        T('Eight bits are not enough for HDR: every gradient bands, and '
          'YouTube requires ten or twelve.')))
    codec = str(track.get("codec_name") or "").lower()
    profile = str(track.get("profile") or "")
    if codec in ("hevc", "h265"):
        out.append(Finding(
            "good" if "10" in profile else "hint", T('Codec profile'),
            "%s %s" % (codec.upper(), profile or "?"),
            "" if "10" in profile else
            T('For ten bits HEVC needs the Main 10 profile. In Resolve it '
              'sits under Deliver as "Profile".')))
    elif codec:
        out.append(Finding(
            "hint" if depth < 10 else "good", "Codec",
            "%s %s" % (codec.upper(), profile),
            T('For HDR the usual choice is HEVC (Main 10), AV1 or VP9 '
              'Profile 2. YouTube takes H.264 too, but it needs more '
              'bitrate.')))
    static_meta = hdr_static_metadata(file_path)
    if trc == 18:
        out.append(Finding(
            "good", T('Static metadata'),
            T('not needed with HLG'),
            T('HLG is display-referred -- it has no entry for the '
              'mastering display.')))
    else:
        missing = [n for n, k in (("Mastering-Display (ST 2086)", "mdcv"),
                                ("MaxCLL/MaxFALL", "clli")) if k not in static_meta]
        out.append(Finding(
            "good" if not missing else "hint", T('Static metadata'),
            T('complete') if not missing else T('missing: %s') % ", ".join(missing),
            "" if not missing else
            T('Not mandatory -- YouTube then applies default values (Sony '
              'BVM-X300). To get them: in Resolve switch on HDR10+ under '
              'Color Management, run "Analyze All Shots" on the Color page '
              'and tick "Embed HDR10 Metadata" when rendering.')))
    return out


def check_hdr(file_path):
    """Print the HDR report for a finished file. 0 means everything is fine."""
    print(T('\nHDR CHECK  %s') % os.path.basename(file_path))
    findings = hdr_findings(file_path)
    for b in findings:
        print(b.line(20))
        if b.kind != "good" and b.advice:
            for line in textwrap.wrap(b.advice, 74):
                print("      %s" % line)
    serious = [b for b in findings if b.kind == "abort"]
    hints = [b for b in findings if b.kind == "hint"]
    curve = next((b for b in findings if b.field == T('Curve')), None)
    have_hdr = bool(curve and curve.kind == "good") and not serious
    print("\n  %s" % (
        T('The file is tagged as HDR.') if have_hdr and not hints
        else TN(len(hints), 'The file is tagged as HDR, with %d note.',
                'The file is tagged as HDR, with %d notes.')
        % len(hints) if have_hdr
        else T('The file is NOT recognised as HDR.')))
    return 0 if have_hdr else 1


def hdr_from_sources(video_paths):
    """Report whether the source material is HDR. Returns (yes, reason).

    The camera file's colr box is read, not guessed. Three things count as
    HDR: PQ or HLG, the two HDR display curves; log, a recording curve HDR
    is graded from; and BT.2020 as the colour space.

    Log belongs in that list. Ungraded it looks flat and is easily taken for
    harmless SDR, but it carries the camera's full dynamic range -- delivered
    in eight bit it bands in every gradient.

    The reason stays English in every language: it goes into the handover
    file, and a file whose contents change with the language cannot be read
    back by the next run.
    """
    for file_path in video_paths or []:
        name = os.path.basename(file_path)
        values = mov_colour_tags(file_path)
        if values:
            prim, trc, _mat, _full = values
            if trc in TRC_HDR:
                return True, ("transfer function %d (%s) in %s"
                              % (trc, TRC_HDR[trc], name))
            if trc in TRC_LOG:
                return True, ("transfer function %d (%s) in %s"
                              % (trc, TRC_LOG[trc], name))
            if prim == PRIMARIES_BT2020:
                return True, ("BT.2020 in %s" % name)
            if _mat == MATRIX_BT2020:
                return True, ("BT.2020 as matrix in %s" % name)
        # Some cameras write nothing usable into the colr box; for those it is
        # in the QuickTime keys.
        source_text = _log_gamma_in_metadata(file_path)
        if source_text:
            return True, ("log according to camera data: %s (%s)"
                          % (source_text[:60], name))
    return False, ""


# How Resolve writes the two tags in the Deliver tab depends on the version. So
# do not bet on one spelling: try them in turn and read back what arrived.
HDR_TAGS = {
    "pq": (("Rec.2020", "Rec. 2020", "Rec2020"),
           ("ST.2084", "ST2084", "PQ", "SMPTE ST 2084")),
    "hlg": (("Rec.2020", "Rec. 2020", "Rec2020"),
            ("HLG", "Rec.2100 HLG", "ARIB STD-B67")),
}

# The same for a delivery that is not HDR. Without it the render stays at
# "Same as Project", and a project standing at Rec.2100 would put an HDR
# colr box on an eight bit H.264 file -- measured on a machine whose new
# projects start at Rec.2100 ST2084.
# The order of the gamma spellings matters, measured on the finished
# file: Resolve accepts "Gamma 2.4" and then writes transfer function 2
# -- unspecified -- into the colr box, which is worse than no tag at all.
# "Rec.709" writes the 1. So the one that lands right comes first.
SDR_TAGS = (("Rec.709", "Rec. 709", "Rec709"),
            ("Rec.709", "Gamma 2.4", "Rec.709 Gamma 2.4", "Gamma2.4"))


def hdr_kind_from_project(p):
    """Return the HDR curve the project outputs: PQ, HLG or none.

    The output colour space is read as Resolve itself enumerates it. Nothing
    is guessed: with nothing recognisable there the result is None and the
    render stays on "Same as Project".
    """
    try:
        every = p.GetSetting("")
    except Exception:
        return None, ""
    if not isinstance(every, dict):
        return None, ""
    for api_key, value in every.items():
        k = api_key.lower()
        if "color" not in k or "output" not in k:
            continue
        value = str(value)
        wl = value.lower().replace(" ", "").replace(".", "")
        if "st2084" in wl or wl.endswith("pq") or "pq" in wl.split("rec")[-1:]:
            return "pq", "%s = %s" % (api_key, value)
        if "hlg" in wl:
            return "hlg", "%s = %s" % (api_key, value)
    return None, ""


def hdr_from_project(p):
    """Report whether the Resolve project settings say HDR is being output.

    The setting's name is not guessed: Resolve enumerates all settings and
    the output colour space is looked up among them. Finding nothing, the
    function says nothing, and what the material offers decides.
    """
    try:
        every = p.GetSetting("")
    except Exception:
        return None, ""
    if not isinstance(every, dict):
        return None, ""
    for api_key, value in every.items():
        k = api_key.lower()
        if "color" not in k or "output" not in k:
            continue
        value = str(value)
        wl = value.lower()
        if any(x in wl for x in ("2100", "st2084", "pq", "hlg", "hdr")):
            return True, "%s = %s" % (api_key, value)
        if "2020" in wl or any(m in wl for m in LOG_MARKERS):
            return True, "%s = %s" % (api_key, value)
        if wl and wl not in ("", "none"):
            return False, "%s = %s" % (api_key, value)
    return None, ""


def _first_match(pairs, wanted_name):
    """Return the first identifier from {description: identifier} that matches.

    Neither the format names nor the codec names are documented, and they
    change between versions. So they are not guessed: Resolve enumerates
    both and the search runs over that.
    """
    if not isinstance(pairs, dict):
        return None, None
    for search_word in wanted_name:
        hit = [(b, k) for b, k in pairs.items()
                   if search_word.lower() in ("%s %s" % (b, k)).lower()]
        if hit:
            # The shortest name is the plain one: "H.265" before "H.265
            # (NVIDIA)". The variants with a GPU in the name are not available
            # everywhere and produce different results.
            hit.sort(key=lambda x: len(x[0]) + len(x[1]))
            return hit[0]
    return None, None


def audible_range(file_path, rate=8000, block=0.05, below_db=40.0):
    """Return where audible sound starts and ends in a file.

    Returns (start, end) in seconds from the beginning of the file, or
    (None, None).

    This means audible sound, not file length. An eight second jingle can
    sit in a ten second file with black and silence at the end -- and for
    meeting the first spoken word, when the jingle *stops* is what counts.

    The threshold sits 40 dB below the loudest point of the file itself. A
    fixed value fails: a quietly mastered jingle would be silent throughout.
    """
    try:
        x = decode_audio(file_path, rate=rate)
    except Exception:
        return None, None
    if x is None or len(x) < rate // 4:
        return None, None
    nb = max(1, int(block * rate))
    count = len(x) // nb
    if count < 2:
        return None, None
    level = np.sqrt((np.asarray(x[:count * nb], dtype=np.float64)
                     .reshape(-1, nb) ** 2).mean(1))
    highest = float(level.max())
    if highest <= 0:
        return None, None
    loud = np.where(level > highest * (10 ** (-below_db / 20.0)))[0]
    if not len(loud):
        return None, None
    return (float(loud[0]) * block, float(loud[-1] + 1) * block)


def _intro_outro_entry(file_path):
    """Build the intro or outro entry for the handover file."""
    if not file_path or not os.path.exists(file_path):
        return None
    try:
        info = video_facts(file_path)
    except Exception:
        return None
    duration = round(float(info.get("duration") or 0.0), 3)
    has_audio = bool(info.get("audio"))
    audio_from, audio_until = (audible_range(file_path) if has_audio else (None, None))
    return {"source": os.path.abspath(file_path),
            "duration": duration,
            "has_audio": has_audio,
            # When the audible sound starts and stops. The position follows
            # that, not the file length.
            "audio_from": round(audio_from, 3) if audio_from is not None else None,
            "audio_to": round(audio_until, 3) if audio_until is not None else None}


def output_folder_from(d):
    """Return the render target: where the finished files are."""
    for cam in (d.get("cameras") or []):
        for api_key in ("file", "source"):
            file_path = cam.get(api_key)
            if file_path and os.path.isdir(os.path.dirname(file_path)):
                return os.path.dirname(file_path)
    for file_path in (d.get("audio_files") or {}).values():
        if file_path and os.path.isdir(os.path.dirname(file_path)):
            return os.path.dirname(file_path)
    return os.getcwd()


def free_render_name(folder, name, extension=".mp4"):
    """Return a name in this folder that no file carries yet.

    Resolve renders over an existing file without asking. A second run of
    the same episode would replace the delivery of the first, and that is
    the one file nobody keeps a copy of.
    """
    if not os.path.exists(os.path.join(folder, name + extension)):
        return name
    for k in range(2, 1000):
        candidate = "%s_%d" % (name, k)
        if not os.path.exists(os.path.join(folder,
                                           candidate + extension)):
            return candidate
    return name


def hdr_says(value):
    """Report whether a colour space name means HDR.

    Read on the answer Resolve gives, which is its internal name --
    "Rec.2100 ST2084", "Rec.709 (Scene)". The dropdown names carry the
    answer in front ("SDR Rec.2020"), so those are read from the front.
    """
    wl = str(value).strip().lower()
    if wl.startswith("sdr"):
        return False
    if wl.startswith("hdr"):
        return True
    return any(x in wl for x in ("2100", "st2084", "pq", "hlg", "2020"))


def project_colour_to_material(p, hdr):
    """Bring a project we made ourselves to the colour space of the material.

    A project created a minute ago carries whatever this machine
    defaults to -- nobody chose that for this material. One machine
    starts new projects at Rec.709, the next at Rec.2100 ST2084;
    measured on both. A project somebody set up is never touched -- see
    the caller.

    Only the output space is set. The working space of the timeline
    belongs to the project as well: with "use project settings" ticked,
    a timeline's colour settings are a copy of the project's -- measured
    on Resolve 21.0.4.5, every value identical on both. And a wide gamut
    working space under an SDR output is a state Resolve offers on
    purpose.

    `isAutoColorManage` stays untouched: automatic colour management is
    somebody's way of working and is not switched off.

    Returns (what now stands, "") or ("", what stands instead).
    """
    try:
        every = p.GetSetting("")
    except Exception:
        return "", ""
    if not isinstance(every, dict):
        return "", ""
    # Two namespaces, and they exclude each other. Measured on Resolve
    # 21.0.4.5: with automatic colour management on, colorSpaceOutput
    # takes only the names of the dropdown -- "SDR Rec.709", "HDR PQ" --
    # and answers with the internal one, "Rec.709 (Scene)". With it off,
    # only the internal names are taken and the dropdown names refused.
    # So the dropdown name is tried first and the internal ones behind
    # it, and success is judged by what the setting says afterwards, not
    # by whether it echoes what was sent.
    if hdr:
        values = ["HDR PQ", "Rec.2100 ST2084", "HDR HLG", "Rec.2100 HLG"]
    else:
        values = ["SDR Rec.709", "Rec.709 (Scene)", "Rec.709 Gamma 2.4",
                  "Rec.709"]
    done, missed = [], []
    name = "colorSpaceOutput"
    if name in every:
        got = ""
        for value in values:
            try:
                if not p.SetSetting(name, value):
                    continue
                back = str(p.GetSetting(name))
                if hdr_says(back) == hdr:
                    got = back
                    break
            except Exception:
                continue
        if got:
            done.append("%s = %s" % (name, got))
        else:
            missed.append("%s = %s" % (name, every[name]))
    if not hdr and str(every.get("hdr10PlusControlsOn", "")) in ("1", "True"):
        # Only ever off, never on: switching on a delivery feature
        # nobody asked for is not this program's business, while leaving
        # it on in an SDR delivery is a contradiction.
        try:
            p.SetSetting("hdr10PlusControlsOn", "0")
        except Exception:
            pass
    if missed:
        return "", ", ".join(missed)
    return ", ".join(done) or T('already right'), ""


def queue_render_job(p, tl, d, folder, name, project_is_new=False):
    """Set the render profile and queue the job.

    After this only "Render All" is left to press in Resolve. Whatever the
    interface accepts is set; whatever it rejects appears as a line in the
    log so nobody has to hunt for it.

    HDR or SDR is decided by the material and the project, not by
    preference: HDR gets H.265 at ten bit and the higher bitrate, SDR gets
    H.264 at eight. An HDR picture in 8-bit H.264 bands in every gradient.
    """
    print(T('\n  Render job'))
    try:
        p.SetCurrentTimeline(tl)
    except Exception:
        pass
    hdr = bool(d.get("hdr"))
    reason = d.get("hdr_reason") or ""
    off_project, project_reason = hdr_from_project(p)
    if project_is_new and off_project is not None and off_project != hdr:
        # Our own project, and its colour space says something other than
        # the material. Whatever it says was not chosen for this job, so
        # the material decides -- in both directions. Without this an HDR
        # source would be delivered as eight bit SDR on one machine, and
        # an SDR source wrapped in HDR on the next.
        stands, instead = project_colour_to_material(p, hdr)
        if stands:
            print("    %-22s %s" % (T('Colour space'), stands))
        else:
            print(as_warn(T('    Caution: the project stands at %s, the '
                            'material is %s.\n             The delivery '
                            'carries the tags of the material. To bring '
                            'the\n             project along: Project '
                            'Settings > Color Management >\n             '
                            'Output Color Space = %s.')
                          % (instead or project_reason,
                             "HDR" if hdr else "SDR",
                             "HDR PQ" if hdr else "SDR Rec.709")))
    elif off_project is not None and off_project != hdr:
        # The project wins: it says what actually comes out.
        hdr, reason = off_project, project_reason
    elif off_project is not None and project_reason:
        reason = reason or project_reason
    print("    %-22s %s%s" % (T('Dynamic range'), "HDR" if hdr else "SDR",
                              "  (%s)" % reason if reason else ""))

    formats = None
    try:
        formats = p.GetRenderFormats()
    except Exception as e:
        print(T('    Format list not readable: %s') % e)
    fname, format_id = _first_match(formats, ["mp4"])
    if not format_id:
        print(T('    No MP4 format found. Available: %s')
              % ", ".join(sorted(formats or {}))[:200])
        return False
    codecs = None
    try:
        codecs = p.GetRenderCodecs(format_id)
    except Exception as e:
        print(T('    Codec list not readable: %s') % e)
    wanted_name = (["h.265", "h265", "hevc"] if hdr else [])\
        + ["h.264", "h264", "avc"]
    cname, codec_id = _first_match(codecs, wanted_name)
    if not codec_id:
        print(T('    No matching codec found. Available: %s')
              % ", ".join(sorted(codecs or {}))[:200])
        return False
    if hdr and not any(x in ("%s %s" % (cname, codec_id)).lower()
                       for x in ("265", "hevc")):
        print(as_warn(T('    Caution: no H.265 available -- it will be '
                        'H.264 with eight bits.\n             Too little '
                        'for HDR; gradients will show banding.')))
    try:
        if not p.SetCurrentRenderFormatAndCodec(format_id, codec_id):
            print(T('    Format and codec could not be set.'))
            return False
    except Exception as e:
        print(T('    Format and codec could not be set: %s') % e)
        return False
    try:
        p.SetCurrentRenderMode(1)      # 1 = one file, not one per clip
    except Exception:
        pass
    height = int(d.get("height") or 1080)
    width = int(d.get("width") or 1920)
    fps = float(d.get("fps") or 30.0)
    bitrate = bitrate_for(height, fps, hdr)
    taken = free_render_name(folder, name)
    if taken != name:
        print(T('    %-22s %s exists already -- rendered to %s instead, '
                'so the\n%searlier delivery stays.')
              % (T('Target'), name + ".mp4", taken + ".mp4", " " * 28))
        name = taken
    settings = {
        "SelectAllFrames": True,
        "TargetDir": folder,
        "CustomName": name,
        "ExportVideo": True,
        "ExportAudio": True,
        "FormatWidth": width,
        "FormatHeight": height,
        "FrameRate": fps,
        "VideoQuality": bitrate,
        "AudioCodec": "aac",
        "AudioBitDepth": 16,
        "AudioSampleRate": SR,
    }
    # Ten bit has no switch of its own, only the profile. Whether this Resolve
    # knows the name shows only on setting it, so it is tried with and, if
    # rejected, without.
    extra_text = {"EncodingProfile": "Main10"} if hdr else {}
    # And the tagging: without it the finished file carries no HDR however
    # cleanly it was graded. Which curve is what the project says; nothing is
    # guessed.
    kind, kind_reason = hdr_kind_from_project(p)
    tag_pairs = []
    if hdr and kind in HDR_TAGS:
        clear, curves = HDR_TAGS[kind]
        tag_pairs = [{"ColorSpaceTag": r, "GammaTag": g}
                     for r in clear for g in curves]
    elif not hdr:
        clear, curves = SDR_TAGS
        tag_pairs = [{"ColorSpaceTag": r, "GammaTag": g}
                     for r in clear for g in curves]
    if hdr and kind not in HDR_TAGS:
        print(T('    %-22s stays at "Same as Project" -- the project '
                'names\n%sno HDR curve. To check in Resolve under\n%sProject '
                'Settings > Color Management > Output Color Space.') % (T('Tagging'), " " * 28, " " * 28))
    applied, accepted = False, None
    attempts = [dict(settings, **dict(extra_text, **t)) for t in tag_pairs]
    if extra_text:
        attempts.append(dict(settings, **extra_text))
    attempts.append(settings)
    for attempt in attempts:
        try:
            applied = bool(p.SetRenderSettings(attempt))
        except Exception:
            applied = False
        if applied:
            accepted = attempt
            break
    if not applied:
        print(T('    Render settings rejected.'))
        return False
    if extra_text:
        print("    %-22s %s" % (T('Profile'), T('Main10 (ten bit)')
                                if "EncodingProfile" in accepted
                                else T('Main10 rejected -- the default stays')))
    if tag_pairs:
        if "ColorSpaceTag" in accepted:
            print("    %-22s %s / %s  (%s)"
                  % (T('Tagging'), accepted["ColorSpaceTag"],
                     accepted["GammaTag"], kind_reason))
        else:
            print(T('    %-22s rejected -- no spelling was accepted.\n%sSet '
                    'by hand in Resolve under Deliver > '
                    'Advanced\n%sSettings: Color space tag Rec.2020, Gamma '
                    'tag %s.')
                  % (T('Tagging'), " " * 28, " " * 28,
                     "ST.2084" if kind == "pq" else "HLG"))
    print("    %-22s %s / %s" % ("Format", fname or format_id,
                                 cname or codec_id))
    print("    %-22s %dx%d, %g fps" % (T('Video'), width, height, fps))
    print(T('    %-22s %s kbit/s  (YouTube recommendation for %s%s)')
          % ("Bitrate", group_text(bitrate),
             "HDR" if hdr else "SDR", T(' at high frame rates') if fps > 30.5
             else ""))
    # The interface has no key for the audio bitrate. So write down what should
    # be there, and nobody has to look for it.
    print(T('    %-22s AAC, %s Hz, two channel  (bitrate cannot be set '
            'remotely --\n%s%s kbit/s are the recommendation for stereo)')
          % (T('Audio'), group_text(SR), " " * 28,
             RENDER_AUDIO_KBIT))
    print("    %-22s %s" % (T('Target'),
                            os.path.join(folder, name + ".mp4")))
    try:
        job = p.AddRenderJob()
    except Exception as e:
        print(T('    Render job could not be created: %s') % e)
        return False
    if not job:
        print(T('    Render job could not be created.'))
        return False
    print(T('    Queued -- in Resolve only "Render All" is left.'))
    if hdr:
        print(T('    Whether the finished file passes as HDR:\n      '
                'videopodcast-magic.py --hdr-check %s')
              % os.path.join(folder, name + ".mp4"))
    return True


def set_loudness_target(p, target_lufs):
    """Set the loudness meter target to ours.

    Resolve measures against -23 LUFS by default, the broadcast value. We
    deliver for web and podcast and normalise to -16, where the meter would
    permanently read +7. The setting's name is not guessed but looked up
    among all project settings.
    """
    try:
        every = p.GetSetting("")
    except Exception:
        every = None
    if not isinstance(every, dict):
        return None
    hit = [k for k in every
               if "loudness" in k.lower() and ("target" in k.lower()
                                               or "level" in k.lower())]
    # "audioMeterLoudnessScale" is the scale, not the target.
    hit = [k for k in hit if "scale" not in k.lower()]
    if not hit:
        print(T('    Loudness meter target level not found -- please set '
                'it by hand:\n    Project Settings > Fairlight > Target '
                'Loudness Level %g LUFS.') % target_lufs)
        return None
    api_key = hit[0]
    wanted = "%g" % target_lufs
    p.SetSetting(api_key, wanted)
    now = p.GetSetting(api_key)
    matches = same_setting_value(now, wanted)
    print("    %-28s %-10s %s" % (api_key, now,
                                  "" if matches else T('(wanted %s)') % wanted))
    return matches


# =====================================================================
#  Metrics and colour comparison
#  -----------------------------
#  What was measured at the end of an episode belongs in a file, not
#  only in the log, which the next run overwrites. Over months it
#  shows whether a camera increasingly looks unlike the others,
#  whether a recorder is drifting, or whether crosstalk rose with a
#  new setup.
# =====================================================================

def measure_picture_levels(file_path, spots=5, t0=0.0, t1=None):
    """Measure brightness and colour balance of a camera file from samples.

    Returns {"y": ..., "u": ..., "v": ..., "sat": ...} or None. Y is
    brightness, U and V are the colour differences -- 128 is neutral, above
    and below is the cast. Measured on a few frames, which is enough to
    compare cameras without reading the whole file.
    """
    if t1 is None or t1 <= t0:
        try:
            t1 = float(ffprobe_json(file_path).get("format", {}).get("duration") or 0.0)
        except Exception:
            t1 = 0.0
    if t1 <= t0:
        return None
    points = [t0 + (t1 - t0) * (k + 0.5) / spots for k in range(spots)]
    values = {"y": [], "u": [], "v": [], "sat": []}
    for time in points:
        try:
            p = subprocess.run(
                ["ffmpeg", "-v", "error", "-ss", "%.3f" % time, "-i", file_path,
                 "-frames:v", "1", "-vf", "signalstats,metadata=print:file=-",
                 "-f", "null", "-"], capture_output=True, timeout=120)
        except Exception:
            continue
        text = p.stdout.decode("utf-8", "replace")
        for api_key, label in (("y", "YAVG"), ("u", "UAVG"),
                                  ("v", "VAVG"), ("sat", "SATAVG")):
            hit = re.search(r"signalstats\.%s=([\d.]+)" % label, text)
            if hit:
                values[api_key].append(float(hit.group(1)))
    if not values["y"]:
        return None
    return dict((k, sum(v) / len(v)) for k, v in values.items() if v)


def compare_picture_levels(cameras, t0=0.0, t1=None):
    """Report how far the cameras sit apart in colour.

    Each camera is compared with the average of all, not with a target.
    Which brightness is right is for the grade to decide; what matters here
    is the distance between cameras, because that shows in the edit as soon
    as it cuts.

    Returns a list of (name, values, deviations) and the averages.
    """
    measured = []
    for cam in cameras:
        file_path = cam.get("file") or cam.get("source")
        if not file_path or not os.path.exists(file_path):
            continue
        values = measure_picture_levels(file_path, t0=t0, t1=t1)
        if values:
            measured.append((cam.get("track") or cam.get("camera") or
                             os.path.basename(file_path), values))
    if len(measured) < 2:
        return measured, None
    middle = {}
    for api_key in ("y", "u", "v", "sat"):
        every = [values[api_key] for _n, values in measured if api_key in values]
        if every:
            middle[api_key] = sum(every) / len(every)
    return measured, middle


def report_picture_comparison(cameras, t0=0.0, t1=None):
    """Write the colour comparison to the log. Returns the measurements."""
    measured, middle = compare_picture_levels(cameras, t0, t1)
    if not measured:
        return []
    print(as_head(T('\nCAMERA COLOUR COMPARISON')))
    print("  %-24s %8s %8s %8s   %s"
          % (T('Camera'), T('Bright.'), T('Colour U'), T('Colour V'),
             T('Distance to mean')))
    lines = []
    for name, values in measured:
        if middle:
            dy = values.get("y", 0) - middle.get("y", 0)
            du = values.get("u", 0) - middle.get("u", 0)
            dv = values.get("v", 0) - middle.get("v", 0)
            distance = "%+6.1f  %+5.1f  %+5.1f" % (dy, du, dv)
        else:
            dy = du = dv = 0.0
            distance = T('-- only one camera')
        print("  %-24s %8.1f %8.1f %8.1f   %s"
              % (name[:24], values.get("y", 0), values.get("u", 0), values.get("v", 0),
                 distance))
        lines.append((name, values, (dy, du, dv)))
    if middle:
        spread = max(abs(line[2][0]) for line in lines)
        if spread > 12:
            print(as_warn(T('  Caution: %.0f steps of brightness '
                            'difference -- visible when switching.') % spread))
        else:
            print(T('  The cameras lie close together (at most %.0f steps '
                    'of brightness).') % spread)
    return lines


def import_media(mp, paths):
    """Import files and find them again by their path."""
    missing = [p for p in paths if not os.path.exists(p)]
    if missing:
        raise RuntimeError(T('These files do not exist:\n  ')
                           + "\n  ".join(missing))
    fresh = mp.ImportMedia(list(paths)) or []
    print(T('  %d of %d files imported.') % (len(fresh), len(paths)))
    # Two cameras can write C0001.MP4 in two folders. Looked up by name
    # both land on one media pool item, and the second camera then gets the
    # first one's picture without a word. Resolve reports the real path, so
    # that is the key; the name stays as a fallback for versions that do
    # not, and a collision there stops the run instead of wiring it wrong.
    after_path, after_name = {}, {}
    for c in (mp.GetRootFolder().GetClipList() or []):
        try:
            where = c.GetClipProperty("File Path") or ""
        except Exception:
            where = ""
        if where:
            after_path.setdefault(
                os.path.normcase(os.path.abspath(where)), c)
        after_name.setdefault(c.GetName(), c)
    assignment, claimed = {}, {}
    for p in paths:
        c = (after_path.get(os.path.normcase(os.path.abspath(p)))
             or after_name.get(os.path.basename(p)))
        if c is None:
            raise RuntimeError(T('Not found again after import: %s')
                               % os.path.basename(p))
        if id(c) in claimed and claimed[id(c)] != p:
            raise RuntimeError(
                T('%s and %s carry the same file name, and Resolve '
                  'reports no\n  path for them. Rename one of the two.')
                % (claimed[id(c)], p))
        claimed[id(c)] = p
        assignment[p] = c
    return assignment


def create_timeline(mp, name):
    """Create an empty timeline; an existing one of that name gets a suffix."""
    tl = mp.CreateEmptyTimeline(name)
    if tl is None:
        for k in range(2, 100):
            tl = mp.CreateEmptyTimeline("%s %d" % (name, k))
            if tl is not None:
                print(T('  A Timeline %r existed already -- the new one is '
                        'called %r.')
                      % (name, tl.GetName()))
                break
    if tl is None:
        raise RuntimeError(T('Timeline %r could not be created.') % name)
    return tl


def find_timeline(p, name):
    """Find the timeline of this name in the project."""
    for i in range(1, (p.GetTimelineCount() or 0) + 1):
        tl = p.GetTimelineByIndex(i)
        if tl is not None and (tl.GetName() or "") == name:
            return tl
    return None


def refresh_resolve_timelines(p, mp, names):
    """Delete these timelines so they can be built again.

    Everything else stays: the media pool and whatever else is in the
    project. Updating means a fresh cut, not an empty project.

    Returns (what was removed, what stayed).
    """
    existing = {}
    for i in range(1, (p.GetTimelineCount() or 0) + 1):
        tl = p.GetTimelineByIndex(i)
        if tl is not None:
            existing.setdefault(tl.GetName() or "", tl)
    duplicate = [n for n in names if n in existing]
    if not duplicate:
        return [], []
    # The open timeline cannot be deleted, so switch to another one first where
    # there is one.
    other = next((tl for n, tl in existing.items() if n not in names), None)
    if other is not None:
        try:
            p.SetCurrentTimeline(other)
        except Exception:
            pass
    targets = [existing[n] for n in duplicate]
    try:
        mp.DeleteTimelines(targets)
    except Exception:
        # Some versions want them one at a time.
        for tl in targets:
            try:
                mp.DeleteTimelines([tl])
            except Exception:
                pass
    # Check what really went: the interface's answer alone is not enough -- it
    # reports success even where nothing happened.
    gone = [n for n in duplicate if find_timeline(p, n) is None]
    stayed = [n for n in duplicate if n not in gone]
    return gone, stayed


def multicam_timeline_unchanged(p, name, cameras):
    """Report whether the multicam timeline already looks the way it should.

    The cut timeline may be rebuilt every run -- it is cheap and changes
    with every number. The multicam timeline carries manual work: the
    multicam clip is converted from it by hand, so it stays as long as the
    same cameras sit on it in the same order.
    """
    tl = find_timeline(p, name)
    if tl is None:
        return None
    try:
        if tl.GetTrackCount("video") != len(cameras):
            return None
        for i, cam in enumerate(cameras, 1):
            item = tl.GetItemListInTrack("video", i) or []
            want = os.path.basename(cam.get("file") or cam.get("source") or "")
            if len(item) != 1 or (item[0].GetName() or "") != want:
                return None
    except Exception:
        return None
    return tl


def cameras_in_track_order(cameras):
    """Put the camera carrying the overall mix on track one.

    Converting to a multicam clip makes video track 1 angle 1, and its first
    audio track is the one Resolve falls back to. The overall mix belongs
    there -- that is the wide shot, which carries exactly that as its first
    track. The rest keep their order.
    """
    def first_of(cam):
        names = [n.lower() for n in (cam.get("audio_tracks") or [])]
        if names and "full" in names[0]:
            return 0
        return 0 if (cam.get("wide") and not names) else 1
    return sorted(cameras, key=first_of)


# Where a new Resolve timeline starts when nobody says otherwise:
# 01:00:00:00. Material without a timecode is laid down there rather
# than at frame 0, which would be eighteen hours before the beginning.
TIMELINE_START_HOUR = 1


def timeline_origin(d):
    """Return where frame zero of the timeline sits and how fast it runs.

    Resolve counts recordFrame from midnight, not from the start of the
    timeline. Passing zero puts the clip 18 hours before the beginning: it
    is there, but not visible.

    Where the handover carries no timecode, the timeline's own start is
    used. Measured on a screen recording: at frame 0 the clips sit
    outside a timeline that begins at 01:00:00:00, and the delivery is a
    single frame while the log says six seconds.
    """
    fps = nearest_known_frame_rate(d.get("fps") or 30.0)
    if not d.get("start_tc"):
        return fps, int(round(TIMELINE_START_HOUR * 3600 * fps))
    return fps, timecode_to_frames(d.get("start_tc"), fps)


def audio_track_count(cam):
    """Return how many audio tracks this camera file carries.

    Counted in the file, not in the handover, which lists only the processed
    tracks and omits the camera microphone. That difference used to leave no
    room for the last camera, which then vanished along with its picture.
    """
    file_path = cam.get("file") or cam.get("source")
    try:
        d = ffprobe_json(file_path)
        n = len([s for s in (d.get("streams") or [])
                 if s.get("codec_type") == "audio"])
        if n:
            return n
    except Exception:
        pass
    return max(1, len(cam.get("audio_tracks") or [1]) + 1)


def build_camera_timeline(mp, tl, cameras, clips, d, every_tracks=False):
    """Lay all cameras side by side, one per video track, one audio track each.

    With all_tracks every audio track stays instead. That is the single
    camera case: there is nothing to untangle and the individual speakers
    plus the mix belong in the timeline.

    Uncut and at full length -- exactly how a timeline destined to become a
    multicam clip has to look.

    Clips are inserted with all their audio, because there is no way to
    choose which audio track comes along. Then it is cleaned up: unlink
    audio from video, delete all but the first audio track of each camera,
    remove the empty tracks, and link picture and remaining audio again --
    V1 to A1, V2 to A2. Unlinking is required, otherwise deleting an audio
    track takes its picture with it.

    For these files the first audio track is the right one: it holds this
    camera's speaker, with the overall mix and the camera microphone behind
    it.
    """
    if d.get("start_tc"):
        tl.SetStartTimecode(d["start_tc"])
    fps, origin = timeline_origin(d)
    while tl.GetTrackCount("video") < len(cameras):
        # Checked like the audio loop below it: an AddTrack that refuses
        # would otherwise be asked again for ever, and every ask is a call
        # into Resolve. The window would look frozen with nothing said.
        if not tl.AddTrack("video"):
            print(as_warn(T('  Resolve refuses more video tracks -- '
                            '%d of %d cameras fit.')
                          % (tl.GetTrackCount("video"), len(cameras))))
            break
    # Room for the audio: the cameras run simultaneously, so their audio tracks
    # all need room side by side. Otherwise Resolve places only what fits and
    # silently drops the rest. With some slack: what Resolve actually occupies
    # is not known in advance, and the cleanup removes empty tracks afterwards.
    needed = sum(audio_track_count(cam) for cam in cameras) + len(cameras)
    while tl.GetTrackCount("audio") < needed:
        if not tl.AddTrack("audio"):
            break
    print(T('  %d video tracks, %d audio tracks created (%s)')
          % (tl.GetTrackCount("video"), tl.GetTrackCount("audio"),
             " + ".join("%s %d" % (cam["track"], audio_track_count(cam))
                        for cam in cameras)))

    # This timeline starts at the earliest camera, not at In point. Otherwise
    # every camera would lie before the timeline start -- a negative position
    # Resolve sometimes accepts and sometimes silently discards.
    early = earliest_offset(cameras)
    # Where the timeline really begins. The report further down measures
    # against it, and once the start has moved the In point is no longer that
    # point -- a distance counted from there would send the search for a
    # missing camera after the wrong number.
    start_frame, begin = origin, d.get("start_tc") or "?"
    if early < 0:
        start_frame = origin + seconds_to_frames(early, fps)
        begin = frames_to_timecode(start_frame, fps,
                                   bool(d.get("drop_frame")))
        tl.SetStartTimecode(begin)
        print(T('  Start %s (earliest camera) -- otherwise everything '
                'would lie before the Timeline start.') % begin)
    entry = {}
    for i, cam in enumerate(cameras, 1):
        c = clips.get(cam["file"])
        if c is None:
            continue
        # Each camera at its measured position in the window, not all at the
        # same point. They started at different times.
        entry[cam["track"]] = {
            "mediaPoolItem": c, "trackIndex": i,
            "recordFrame": origin + seconds_to_frames(cam.get("offset") or 0.0, fps)}
    # One after another, not all at once. Given a batch, Resolve places what
    # fits and drops the rest without a word -- and the audio tracks the
    # skipped camera would have needed are then taken by the next.
    for cam in cameras:
        if cam["track"] not in entry:
            continue
        e = entry[cam["track"]]
        mp.AppendToTimeline([e])
        if timeline_items_per_camera(tl, cameras).get(cam["track"]):
            continue
        # Without mediaType Resolve puts picture *and* audio on the same track
        # number. The second camera should go to V2, but the first camera's
        # second audio channel is long since there, and Resolve refuses without
        # a word. So separately: picture to its video track, audio to the first
        # free audio track.
        free = first_free_audio_track(tl)
        mp.AppendToTimeline([dict(e, mediaType=1)])
        mp.AppendToTimeline([{"mediaPoolItem": e["mediaPoolItem"],
                              "trackIndex": free,
                              "recordFrame": e["recordFrame"],
                              "mediaType": 2}])
        if timeline_items_per_camera(tl, cameras).get(cam["track"]):
            print(T('    %s: picture and audio inserted separately (audio '
                    'from A%d).')
                  % (cam["track"], free))
    present = timeline_items_per_camera(tl, cameras)
    absent = [cam["track"] for cam in cameras if not present.get(cam["track"])]
    if absent:
        # When Resolve inserts nothing it does not say why. So write down the
        # numbers it was called with; that shows afterwards what it was.
        print(T('    For checking -- Timeline starts at frame %d (%s):')
              % (start_frame, begin))
        for cam in cameras:
            if cam["track"] not in entry:
                print(T('      %-24s no file in the media pool') % cam["track"])
                continue
            rf = entry[cam["track"]]["recordFrame"]
            print(T('      %-24s track V%d, from frame %d (%+.1f s to the '
                    'start), %s%s') % (cam["track"], entry[cam["track"]]["trackIndex"], rf,
                            (rf - start_frame) / max(1.0, fps),
                            T('Duration %s') % as_hms(cam.get("duration") or 0.0),
                            T('   NOT INSERTED')
                            if cam["track"] in absent else ""))
            print("        %s" % clip_signature(clips.get(cam["file"])))

    for i, cam in enumerate(cameras, 1):
        if not tl.SetTrackName("video", i, cam["track"]):
            print(T('    Video track %d could not be renamed.') % i)
    print(T('  %d video tracks, named after the speakers:') % len(cameras))
    for i, cam in enumerate(cameras, 1):
        print("    V%-3d %-30s %s%s"
              % (i, cam["track"], os.path.basename(cam["file"] or cam["source"]),
                 T('   MISSING') if cam["track"] in absent else ""))
    if absent:
        print(as_warn(TN(len(absent),
                         '  Caution: %s not inserted. Without this angle the'
                         '\n  Timeline is no good for converting.',
                         '  Caution: %s not inserted. Without these angles '
                         'the\n  Timeline is no good for converting.')
                      % ", ".join(absent)))

    if every_tracks:
        # Nothing to untangle with one camera: every audio track stays.
        remove_empty_audio_tracks(tl)
        names = (cameras[0].get("audio_tracks") or []) if cameras else []
        for track in range(1, tl.GetTrackCount("audio") + 1):
            if track <= len(names):
                tl.SetTrackName("audio", track, names[track - 1])
        print(TN(tl.GetTrackCount("audio"),
                 '  %d audio track stays: %s',
                 '  %d audio tracks stay: %s')
              % (tl.GetTrackCount("audio"),
                 ", ".join(names[:tl.GetTrackCount("audio")]) or T('unnamed')))
    else:
        trim_audio_tracks(tl, cameras, present)
    return tl


def cameras_by_file_name(cameras):
    """Map file name to camera, and say so where two names collide.

    A timeline item reports its name, never its path, so the file name is
    the only key there is. Two cameras writing C0001.MP4 in different
    folders would land on one entry, and the second would quietly take
    over the first one's clips.
    """
    after_file = {}
    for cam in cameras:
        api_key = os.path.basename(cam["file"] or cam["source"])
        if api_key in after_file:
            print(as_warn(T('  Caution: %s and %s are both called %s. On '
                            'the Timeline\n  Resolve reports only the '
                            'name, so their clips cannot be told\n  apart '
                            '-- rename one of the two files.')
                          % (after_file[api_key]["track"], cam["track"],
                             api_key)))
        after_file[api_key] = cam
    return after_file


def audio_tracks_per_camera(tl, cameras):
    """Return which audio items belong to which camera, in track order."""
    after_file = cameras_by_file_name(cameras)
    assignment = {}
    for track in range(1, tl.GetTrackCount("audio") + 1):
        for item in (tl.GetItemListInTrack("audio", track) or []):
            try:
                name = item.GetName() or ""
            except Exception:
                continue
            cam = after_file.get(name)
            if cam:
                assignment.setdefault(cam["track"], []).append((track, item))
    return assignment


def trim_audio_tracks(tl, cameras, video_items):
    """Keep only the first audio track per camera and link it to its picture.

    Conversion turns every track into an angle. Leaving the overall mix and
    the camera microphone in place creates angles without picture, and
    SmartSwitch then hears every speaker on every camera.
    """
    audio = audio_tracks_per_camera(tl, cameras)
    if not audio:
        print(T('  No audio on the Timeline -- nothing to clean up.'))
        return
    print(T('\n  CLEAN UP AUDIO TRACKS'))
    kept = {}
    for cam in cameras:
        # By the track number alone. The entries are (track, item), and
        # two cameras whose files carry the same name put two items on
        # the same track -- then Python compares the items themselves,
        # and two Resolve objects cannot be put in an order. Measured
        # against the running Resolve: it raised there and took the
        # whole Resolve part down after the collision had been
        # reported.
        entries = sorted(audio.get(cam["track"]) or [],
                         key=lambda pair: pair[0])
        if not entries:
            print(T('    %-24s no audio inserted') % cam["track"])
            continue
        video = (video_items.get(cam["track"]) or [None])[0]
        every = [p for _, p in entries]
        # Unlink first, otherwise deleting an audio track takes the linked
        # picture with it.
        separate = False
        try:
            separate = bool(tl.SetClipsLinked(
                ([video] if video else []) + every, False))
        except Exception as e:
            print(T('    %-24s could not be unlinked: %s') % (cam["track"], e))
        gone = every[1:]
        if gone and not separate:
            # Resolve reports failure only as False. Deleting now would take
            # the linked picture along -- exactly the damage unlinking
            # prevents.
            print(T('    %-24s Unlinking had no effect -- the surplus '
                    'audio tracks\n    %-24s stay in place.')
                  % (cam["track"], ""))
            gone = []
        if gone:
            try:
                if not tl.DeleteClips(gone):
                    print(T('    %-24s Deleting failed.') % cam["track"])
                    gone = []
            except Exception as e:
                print(T('    %-24s Deleting failed: %s') % (cam["track"], e))
                gone = []
        kept[cam["track"]] = (video, every[0], entries[0][0])
        print(T('    %-24s audio from A%d kept, %d more deleted')
              % (cam["track"], entries[0][0], len(gone)))

    remove_empty_audio_tracks(tl)

    # Link them again: picture and its audio belong together, otherwise editing
    # moves only half of it.
    linked = 0
    for cam in cameras:
        entry = kept.get(cam["track"])
        if not entry or not entry[0]:
            continue
        video, audio_item, _ = entry
        try:
            if tl.SetClipsLinked([video, audio_item], True):
                linked += 1
            else:
                print(T('    %-24s could not be linked again')
                      % cam["track"])
        except Exception as e:
            print(T('    %-24s Linking failed: %s') % (cam["track"], e))
    if linked:
        print(TN(linked, '    Picture and audio linked again: %d angle',
                 '    Picture and audio linked again: %d angles') % linked)
    # Name the audio tracks like the video tracks; the order is right now.
    n = tl.GetTrackCount("audio")
    row = []
    for track in range(1, n + 1):
        item = tl.GetItemListInTrack("audio", track) or []
        name = ""
        if item:
            for cam in cameras:
                if os.path.basename(cam["file"] or cam["source"]) ==\
                        (item[0].GetName() or ""):
                    name = cam["track"]
                    break
        if name:
            tl.SetTrackName("audio", track, name)
        row.append((track, name or (tl.GetTrackName("audio", track) or ""),
                      len(item)))
    print(TN(n, '  %d audio track remains:',
             '  %d audio tracks remain:') % n)
    for track, name, count in row:
        print("    A%-3d %-30s %s" % (track, name,
                                       TN(count, '%d clip', '%d clips')
                                       % count))


def remove_empty_audio_tracks(tl):
    """Remove audio tracks while they are empty.

    A new timeline brings one along, and that too would become an angle on
    conversion.
    """
    gone = 0
    for i in range(tl.GetTrackCount("audio"), 0, -1):
        if tl.GetItemListInTrack("audio", i):
            continue
        try:
            if tl.DeleteTrack("audio", i):
                gone += 1
        except Exception:
            pass
    if gone:
        print(TN(gone, '    %d empty audio track removed',
                 '    %d empty audio tracks removed') % gone)


def source_channel_count(clip):
    """Return how many audio tracks this media pool clip carries.

    The mapping is read from the clip properties rather than from the file,
    so a clip reduced to one track shows as one. Resolve answers like this:

        {"embedded_audio_channels": 4,
         "linked_audio": {},
         "track_mapping": {"1": {"channel_idx": [1], "mute": false,
                                 "type": "mono"}}}

    So: four channels embedded, one track used, from channel 1. Returns
    (tracks, embedded channels).
    """
    try:
        raw = clip.GetAudioMapping()
    except Exception:
        return None, None
    if not raw:
        return None, None
    try:
        m = json.loads(raw) if isinstance(raw, str) else raw
    except ValueError:
        return None, None
    if isinstance(m, list):
        return len(m), None
    if not isinstance(m, dict):
        return None, None
    channels = m.get("embedded_audio_channels")
    if not isinstance(channels, int):
        channels = None
    # Do not rely on the name "track_mapping" alone -- it appears in no
    # description I know of, only in the response itself.
    for api_key, value in m.items():
        s = str(api_key).lower()
        if "linked" in s or not any(word in s for word in ("track", "mapping")):
            continue
        if isinstance(value, (dict, list)) and len(value):
            return len(value), channels
    # Or the mapping is already the outermost level: {"1": ..., "2": ...}
    if m and all(str(k).strip().isdigit() for k in m):
        return len(m), channels
    return None, channels


def find_handover_file(*places, deeper=False):
    """Find the newest usable ..._resolve.json in these folders.

    *deeper* includes subfolders: the result of an earlier run often sits in
    a subfolder next to the raw material.

    A file an older version wrote is skipped rather than returned: the
    caller would read it, find none of the keys it expects and report the
    material as empty instead of the file as old.
    """
    look = []
    for place in places:
        if not place or not os.path.isdir(place):
            continue
        place = os.path.abspath(place)
        if place not in look:
            look.append(place)
        if not deeper:
            continue
        try:
            for name in sorted(os.listdir(place)):
                below = os.path.join(place, name)
                if os.path.isdir(below) and not name.startswith("."):
                    if below not in look:
                        look.append(below)
        except OSError:
            pass
    hit = []
    for place in look:
        try:
            names = os.listdir(place)
        except OSError:
            continue
        for name in names:
            if name.lower().endswith("_resolve.json"):
                file_path = os.path.join(place, name)
                try:
                    with open(file_path, encoding="utf-8") as f:
                        if format_complaint(json.load(f)):
                            continue
                    hit.append((os.path.getmtime(file_path), file_path))
                except (OSError, ValueError):
                    pass
    return max(hit)[1] if hit else None


def print_audio_track_mapping():
    """Print what Resolve reports about the audio tracks, changing nothing.

    For the open project: the raw channel mapping of every media pool clip,
    plus each timeline with its tracks. Enough to check whether a change in
    the clip attributes arrived.
    """
    print(as_head(T('\nRESOLVE -- INSPECT ONLY')))
    r = connect_to_resolve()
    print("  %s %s" % (r.GetProductName(), r.GetVersionString()))
    p = r.GetProjectManager().GetCurrentProject()
    if p is None:
        raise RuntimeError(T('No project open.'))
    print(T('  Project %r') % p.GetName())

    print(T('\n  CLIPS IN THE MEDIA POOL'))
    mp = p.GetMediaPool()
    folder = [mp.GetRootFolder()]
    seen = 0
    while folder:
        f = folder.pop(0)
        if f is None:
            continue
        folder += list(f.GetSubFolderList() or [])
        for c in (f.GetClipList() or []):
            try:
                kind = (c.GetClipProperty("Type") or "").lower()
            except Exception:
                kind = ""
            if "timeline" in kind:
                continue
            seen += 1
            print("\n    %s" % (c.GetName() or "?"))
            for api_key in ("Audio Ch", "Audio Codec", "Audio Bit Depth",
                               "Sample Rate", "Type"):
                try:
                    value = c.GetClipProperty(api_key)
                except Exception:
                    value = None
                if value not in (None, ""):
                    print("      %-16s %s" % (api_key, value))
            try:
                raw = c.GetAudioMapping()
            except Exception as e:
                print(T('      GetAudioMapping   fails: %s') % e)
                continue
            if not raw:
                print(T('      GetAudioMapping   empty (%r)') % raw)
                continue
            print("      GetAudioMapping   %s" % type(raw).__name__)
            text = raw if isinstance(raw, str) else json.dumps(raw)
            try:
                pretty = json.dumps(json.loads(text), indent=2,
                                    ensure_ascii=False)
            except (ValueError, TypeError):
                pretty = text
            for line in pretty.splitlines():
                print("        %s" % line)
            n, channels = source_channel_count(c)
            print(TN(n if isinstance(n, int) else 0,
                     '      --> interpreted as %s audio track%s',
                     '      --> interpreted as %s audio tracks%s')
                  % (n if n is not None else T('not readable'),
                     TN(channels, ' of %d embedded channel',
                        ' of %d embedded channels') % channels
                     if channels else ""))
    if not seen:
        print(T('    No clips found.'))

    print("\n  TIMELINES")
    for i in range(1, (p.GetTimelineCount() or 0) + 1):
        tl = p.GetTimelineByIndex(i)
        if tl is None:
            continue
        nv, na = tl.GetTrackCount("video"), tl.GetTrackCount("audio")
        print(T('\n    %s  --  %s, %s')
              % (tl.GetName(),
                 TN(nv, '%d video track', '%d video tracks') % nv,
                 TN(na, '%d audio track', '%d audio tracks') % na))
        for s in range(1, nv + 1):
            item = tl.GetItemListInTrack("video", s) or []
            print("      V%-3d %-24s %s"
                  % (s, (tl.GetTrackName("video", s) or "")[:24],
                     TN(len(item), '%d clip', '%d clips') % len(item)))
        for s in range(1, na + 1):
            item = tl.GetItemListInTrack("audio", s) or []
            first_one = ""
            if item:
                try:
                    first_one = item[0].GetName() or ""
                except Exception:
                    first_one = "?"
            print("      A%-3d %-24s %-10s %s"
                  % (s, (tl.GetTrackName("audio", s) or "")[:24],
                     TN(len(item), '%d clip', '%d clips') % len(item),
                     first_one[:40]))
    print(T('\n  Nothing was changed.'))
    return 0


def first_free_audio_track(tl):
    """Return the first audio track with nothing on it."""
    for i in range(1, tl.GetTrackCount("audio") + 1):
        if not (tl.GetItemListInTrack("audio", i) or []):
            return i
    return tl.GetTrackCount("audio") + 1


def clip_signature(c):
    """Return the properties Resolve might reject a file for.

    Resolve does not say why it refuses to insert something. The only way
    left is to put the cameras side by side and see how the rejected one
    differs from the accepted ones.
    """
    if c is None:
        return T('not in the media pool')
    try:
        p = c.GetClipProperty() or {}
    except Exception:
        return T('no information')
    if not isinstance(p, dict):
        return str(p)[:120]
    parts = []
    for name in ("Format", "Video Codec", "Resolution", "FPS", "Audio Codec",
                 "Audio Ch", "Frames", "Duration", 'Start TC', "End TC"):
        if p.get(name):
            parts.append("%s %s" % (name, p[name]))
    return ", ".join(parts) or T('no information')


def timeline_items_per_camera(tl, cameras):
    """Return which timeline clip belongs to which camera.

    Returns {camera track name: [TimelineItem, ...]}.

    Where two cameras write the same file name the name cannot tell them
    apart, and the last one read would take both. What can tell them
    apart here is the video track: every camera gets one of its own, in
    the order they were inserted -- the same order the renaming below
    goes by. Without that the first of the two was reported as not
    inserted although its clip was on the timeline, so the collision
    arrived twice: once correctly, and once as a false alarm.
    """
    after_file = cameras_by_file_name(cameras)
    doubled = {}
    for cam in cameras:
        doubled.setdefault(
            os.path.basename(cam["file"] or cam["source"]), []).append(cam)
    by_track = dict(enumerate(cameras, 1))
    assignment = {}
    for track in range(1, tl.GetTrackCount("video") + 1):
        for item in (tl.GetItemListInTrack("video", track) or []):
            try:
                name = item.GetName() or ""
            except Exception:
                continue
            cam = after_file.get(name)
            if cam is not None and len(doubled.get(name) or []) > 1:
                cam = by_track.get(track, cam)
            if cam:
                assignment.setdefault(cam["track"], []).append(item)
    return assignment


# Resolve's clip colours, sorted by distinguishability. With two speakers the
# first two should lie as far apart as possible; a third should stand out from
# both, and so on.
#
# Which names Resolve accepts appears in no documentation I know of. So nothing
# is guessed: SetClipColor reports whether it worked, and one pass establishes
# the usable list.
CLIP_COLOURS = ["Blue", "Orange", "Green", "Pink", "Yellow", "Violet",
              "Teal", "Brown", "Lime", "Navy", "Apricot", "Purple",
              "Olive", "Chocolate", "Beige", "Tan"]
# The wide shot is not a voice but the fallback, so it gets a calm colour that
# stays out of the speakers' way. In Resolve that remains "Tan": the clip
# colour should not shift under already graded projects. On a dark background
# the interface uses a different shade -- see CLIP_COLOURS_RGB_DARK.
COLOUR_WIDE_SHOT = "Tan"
# Approximations of the clip colours for the cut band in the interface. They
# should be recognisable, not exact -- what Resolve makes of them is what
# counts.
CLIP_COLOURS_RGB = {
    "Blue": "#3f7fbf", "Cyan": "#3fbfbf", "Green": "#3fbf5f",
    "Yellow": "#d9c23a", "Red": "#bf3f3f", "Pink": "#d98fbf",
    "Purple": "#8f5fbf", "Fuchsia": "#bf3f8f", "Rose": "#d99f9f",
    "Lavender": "#a89fd9", "Sky": "#7fbfd9", "Mint": "#7fd9a8",
    "Lemon": "#d9d97f", "Sand": "#d9bf8f", "Cocoa": "#8f6f4f",
    "Cream": "#e8dfc0", "Orange": "#d98f3f", "Violet": "#7f5fbf",
    "Teal": "#3f8f8f", "Brown": "#8f5f3f", "Lime": "#9fd93f",
    "Navy": "#3f4f8f", "Apricot": "#e8b07f", "Olive": "#7f8f3f",
    "Chocolate": "#6f4f3f", "Beige": "#ddd0b0", "Tan": "#c8b088"}
# On a dark background the dark shades all but vanish. These are lightened far
# enough to sit at least 50 CIE76 from the sheet -- computed, not by feel. All
# others stay as they are.
#
# "Tan" is there for a different reason: as a warm sand brown it sits too close
# to the orange of the second camera (34.9 CIE76), and that shows even more on
# dark than on light. The pale sage keeps at least 52.9 from every speaker
# colour and still stays calm. In Resolve the clip is still called Tan; this is
# only the display.
CLIP_COLOURS_RGB_DARK = {
    "Brown": "#9d6945", "Chocolate": "#a57760", "Cocoa": "#9d7a57",
    "Navy": "#4c5fac", "Teal": "#429696", "Tan": "#b5c9b1"}
# And the other way round: on white the lightest shade disappears.
CLIP_COLOURS_RGB_LIGHT = {"Beige": "#ccb989"}
# Set by the interface when the system is in dark mode.
ON_DARK = [False]


def colours_pick(dark):
    """Fill COLOURS with the set this desktop asks for.

    Refilled in place rather than replaced: every module and every
    style sheet holds on to this one dictionary, and a new object
    would leave all of them reading the old one. Called again when the
    desktop switches while the program runs.
    """
    COLOURS.clear()
    COLOURS.update(COLOURS_DARK if dark else COLOURS_LIGHT)
    ON_DARK[0] = bool(dark)


def clip_colour_rgb(name):
    """Return the RGB approximation of a clip colour for this background."""
    exception = (CLIP_COLOURS_RGB_DARK if ON_DARK[0]
                else CLIP_COLOURS_RGB_LIGHT)
    if name in exception:
        return exception[name]
    return CLIP_COLOURS_RGB.get(name, "#888888")


def usable_clip_colours(item, wanted):
    """Return the clip colour names this Resolve accepts.

    Tried on a single clip whose original colour is restored afterwards.
    Better to look once than to guess a list that changes between versions.
    """
    try:
        before_value = item.GetClipColor()
    except Exception:
        return list(wanted)
    good = []
    for name in wanted:
        try:
            if item.SetClipColor(name):
                good.append(name)
        except Exception:
            pass
    try:
        if before_value:
            item.SetClipColor(before_value)
        else:
            item.ClearClipColor()
    except Exception:
        pass
    return good or list(wanted)


def colour_per_camera(cameras, colours):
    """Assign a colour to each camera.

    The wide shot colour is set aside first so no speaker gets the same one,
    which would make the fallback look like a person. The rest are handed
    out in order, and that order is sorted so the first two lie furthest
    apart.
    """
    if not colours:
        return {}, 0
    wide_shot_colour = COLOUR_WIDE_SHOT if COLOUR_WIDE_SHOT in colours else colours[-1]
    rest = [f for f in colours if f != wide_shot_colour] or [wide_shot_colour]
    row = [cam for cam in cameras if not cam.get("wide")]
    assigned = {}
    for i, cam in enumerate(row):
        assigned[cam["track"]] = rest[i % len(rest)]
    for cam in cameras:
        if cam.get("wide"):
            assigned[cam["track"]] = wide_shot_colour
    # More angles than colours means the sequence repeats. That should not
    # happen silently.
    duplicate = max(0, len(row) - len(rest))
    return assigned, duplicate


def colour_clips_by_camera(tl, cameras):
    """Colour every cut in the colour of its camera.

    The edit window then shows at a glance who is on screen when and how the
    rhythm runs, without a single marker.
    """
    assignment = timeline_items_per_camera(tl, cameras)
    if not assignment:
        return
    first_one = next(iter(next(iter(assignment.values()))), None)
    if first_one is None:
        return
    colours = usable_clip_colours(first_one, CLIP_COLOURS)
    assigned, duplicate = colour_per_camera(cameras, colours)
    applied, failed = {}, 0
    for track, item in assignment.items():
        colour = assigned.get(track)
        if not colour:
            continue
        for x in item:
            try:
                if x.SetClipColor(colour):
                    applied[track] = applied.get(track, 0) + 1
                else:
                    failed += 1
            except Exception:
                failed += 1
    if not applied:
        print(T('    Clip colours could not be set.'))
        return
    print(T('    Colours per angle:'))
    for track in sorted(applied, key=lambda s: -applied[s]):
        print("      %-28s %-10s %s"
              % (track, assigned.get(track) or "?",
                 TN(applied[track], '%d clip', '%d clips') % applied[track]))
    if duplicate:
        print(TN(duplicate,
                 '      More angles than colours -- %d colour occurs twice.',
                 '      More angles than colours -- %d colours occur twice.')
              % duplicate)
    if failed:
        print(TN(failed, '      %d clip left without a colour.',
                 '      %d clips left without a colour.') % failed)


def create_colour_groups(p, tl, cameras):
    """Create one colour group per camera and put all its clips in.

    That means grading once per camera instead of once per cut: switch the
    node editor to "Group Pre-Clip" and the correction applies to every clip
    of the group. Switched to "Clip" it applies to that one cut only -- both
    side by side, computed in that order. This is why remote grades stay
    off: they would glue the clip level together as well.

    Groups can still be changed later, unlike remote grades, which would
    have to be set before inserting.
    """
    existing = {}
    try:
        for g in (p.GetColorGroupsList() or []):
            existing[g.GetName()] = g
    except Exception:
        pass
    assignment = timeline_items_per_camera(tl, cameras)
    if not assignment:
        print(T('  No clips found for colour groups.'))
        return
    done = {}
    for name in sorted(assignment):
        group = existing.get(name)
        if group is None:
            try:
                group = p.AddColorGroup(name)
            except Exception as e:
                print(T('  Colour group %r cannot be created: %s') % (name, e))
                continue
        if not group:
            print(T('  Colour group %r cannot be created.') % name)
            continue
        existing[name] = group
        good = 0
        for item in assignment[name]:
            try:
                if item.AssignToColorGroup(group):
                    good += 1
            except Exception:
                pass
        done[name] = (good, len(assignment[name]))
    # One line is enough: the clip counts are already with the colours.
    incomplete = [n for n, (g, total) in done.items() if g < total]
    if done and not incomplete:
        print(T('    Colour groups: %s -- all clips assigned')
              % ", ".join(sorted(done)))
    for n in incomplete:
        print(T('    Colour group %-24s only %d of %d clips')
              % (n, done[n][0], done[n][1]))


def mix_file_from_handover(d):
    """Return the file carrying the overall mix.

    Preferably the separate file, which is unambiguous. Otherwise the wide
    shot, where the mix is the first audio track. Otherwise any camera with
    a track of that name.
    """
    for name, file_path in (d.get("audio_files") or {}).items():
        if "full" in name.lower() and file_path and os.path.exists(file_path):
            return file_path, T('stored file %s') % os.path.basename(file_path)
    for cam in (d.get("cameras") or []):
        if cam.get("wide") and cam.get("file") and os.path.exists(cam["file"]):
            return cam["file"], (T('wide shot %s, the mix is its first audio '
                                 'track') % cam["camera"])
    for cam in (d.get("cameras") or []):
        names = [n.lower() for n in (cam.get("audio_tracks") or [])]
        if any("full" in n for n in names) and os.path.exists(
                cam.get("file") or ""):
            idx = [i for i, n in enumerate(names, 1) if "full" in n][0]
            return cam["file"], (T('%s, audio track %d') % (cam["camera"], idx))
    return None, ""


def first_and_last_word(d):
    """Return when the first word falls and when the last one ends.

    Taken from the speaker statistics already in the handover file -- the
    same source the camera cut was computed from. Returns (first, last) in
    seconds from the start of the timeline, or (None, None) without
    statistics.
    """
    starts, ends = [], []
    for speaker in (d.get("speakers") or []):
        for a, b in (speaker.get("sections") or []):
            starts.append(float(a))
            ends.append(float(b))
    if not starts:
        return None, None
    return min(starts), max(ends)


def _meeting_point(entry, kind):
    """Return the point in the clip that should meet the word.

    For the intro that is the end of its audible audio, where the first word
    should start. For the outro the start of its audio, by which the last
    word should have died away. A clip without audio uses its end for the
    intro and its start for the outro.

    Nothing is cut: both clips keep their full length and only their
    position moves. The picture overlap is intended -- the dissolve sits
    in it, and where exactly is decided in Resolve.
    """
    entry = entry or {}
    duration = float(entry.get("duration") or 0.0)
    if kind == "intro":
        value = entry.get("audio_to")
        return float(value) if value is not None else duration
    value = entry.get("audio_from")
    return float(value) if value is not None else 0.0


def lead_in_offset(mp, tl, d, clips, fps, origin):
    """Place intro and outro on the second video and audio track.

    The intro sits over the beginning: its end falls on the first spoken
    word and its audio continues on its own track under the first words. The
    outro starts where the last word ends.

    The scripting interface cannot make the dissolve -- it knows no
    transitions. So the intro lies *over* the content rather than beside it:
    one drag on the clip corner and the dissolve is there.

    Returns by how many frames the content has to move back.
    """
    intro = d.get("intro")
    if not intro:
        return 0
    word0, _word1 = first_and_last_word(d)
    W = word0 if word0 is not None else 0.0
    # The content moves only as far as the intro reaches past the start --
    # measured at the point its audio stops, not at its file length. Where
    # someone starts speaking late, nothing moves.
    return seconds_to_frames(max(0.0, _meeting_point(intro, "intro") - W), fps)


def insert_intro_and_outro(mp, tl, d, clips, fps, origin, lead_in):
    """Insert the two clips, after the content.

    The content has to be in place first, otherwise the second track they
    belong on does not exist yet.
    """
    applied = []
    # The second video track does not appear by itself. Without it
    # AppendToTimeline accepts the clip and puts it nowhere.
    needs_audio = any((d.get(a) or {}).get("has_audio")
                      for a in ("intro", "outro"))
    for kind_track, at_least in (("video", 2), ("audio", 2 if needs_audio
                                                else 0)):
        try:
            while at_least and tl.GetTrackCount(kind_track) < at_least:
                if not tl.AddTrack(kind_track):
                    print(T('    %s track %d could not be created.')
                          % (kind_track, at_least))
                    break
        except Exception as e:
            print(T('    %s track could not be created: %s') % (kind_track, e))
    for kind, where_to in ((TYPE_INTRO, label_of(TYPE_INTRO)),
                           (TYPE_OUTRO, label_of(TYPE_OUTRO))):
        entry = d.get(kind)
        if not entry:
            continue
        clip = clips.get(entry["source"])
        if clip is None:
            print(T('    %s could not be imported.') % where_to)
            continue
        L = float(entry.get("duration") or 0.0)
        meeting_point = _meeting_point(entry, kind)
        word0, word1 = first_and_last_word(d)
        if kind == "intro":
            W = word0 if word0 is not None else 0.0
            # The end of the intro audio meets the first word.
            spot = seconds_to_frames(max(0.0, W - meeting_point), fps)
        else:
            # The start of the outro audio meets the end of the last word.
            end = word1 if word1 is not None else float(d.get("length_s") or 0)
            spot = max(0, lead_in + seconds_to_frames(end - meeting_point, fps))
        item = [{"mediaPoolItem": clip, "trackIndex": 2,
                   "recordFrame": origin + spot, "mediaType": 1}]
        if entry.get("has_audio"):
            item.append({"mediaPoolItem": clip, "trackIndex": 2,
                           "recordFrame": origin + spot, "mediaType": 2})
        if not mp.AppendToTimeline(item):
            print(T('    %s could not be inserted.') % where_to)
            continue
        applied.append((kind, where_to, spot, L, bool(entry.get("has_audio")),
                        meeting_point))
    if not applied:
        return
    try:
        tl.SetTrackName("video", 2, "Intro / Outro")
        tl.SetTrackName("audio", 2, "Audio Intro / Outro")
    except Exception:
        pass
    # Check rather than trust: the interface reports success even when the clip
    # lands somewhere else.
    try:
        up_v2 = tl.GetItemListInTrack("video", 2) or []
        print(TN(len(up_v2), '    V2 now holds %d clip: %s',
                 '    V2 now holds %d clips: %s')
              % (len(up_v2),
                 ", ".join((x.GetName() or "?") for x in up_v2) or T('none')))
    except Exception as e:
        print(T('    V2 could not be read back: %s') % e)
    for kind, where_to, spot, L, having_audio, meeting_point in applied:
        print(T('    %-10s from %s, %s long%s')
              % (where_to, as_hms(spot / float(fps)), as_hms(L),
                 T(', audio on A2') if having_audio else T(', no audio')))
        if having_audio:
            print(T('               Audio %s at %s -- there it meets the '
                    '%s word.')
                  % (T('ends') if kind == TYPE_INTRO else T('begins'),
                     as_hms((spot / float(fps)) + meeting_point),
                     T('first') if kind == TYPE_INTRO else T('last')))
    print(T('      Both clips stay uncut; they overlap the content.\n      '
            'The dissolve sits in the overlap -- exactly where is your '
            'decision in Resolve.\n      (The Resolve scripting interface '
            'cannot create transitions.)'))


def build_cut_timeline(mp, tl, cut, cameras, clips, d, mix=None,
                             lead_in=0):
    """Build the finished camera cut.

    Picture comes from the cameras, audio from the mix. The picture pieces
    go onto the timeline without their audio, otherwise a different audio
    track would sit under every cut and the sound would jump. The overall
    mix runs underneath in one piece.
    """
    if d.get("start_tc"):
        tl.SetStartTimecode(d["start_tc"])
    fps, origin = timeline_origin(d)
    after_camera = {}
    for cam in cameras:
        c = clips.get(cam["file"])
        if c is not None:
            after_camera[cam["camera"]] = (c, cam.get("offset") or 0.0,
                                        cam.get("duration") or 0.0)
    # Fallback order: the wide shot first, then the rest.
    fallback = cameras_in_track_order(cameras)
    item, skipped, replaced = [], set(), 0

    def piece(name, t0, length):
        """Return the piece if it fits this camera, otherwise nothing.

        The length comes from the timeline, not from the source. Rounding both
        separately mostly works and is occasionally one frame off, and then
        the cut has a gap.
        """
        entry = after_camera.get(name)
        if entry is None:
            return None
        c, offset, duration = entry
        start_frame = seconds_to_frames(t0 - offset, fps)
        end_frame = start_frame + length
        if length <= 0 or start_frame < 0:
            return None
        if duration and end_frame > seconds_to_frames(duration, fps):
            return None
        # endFrame counts exclusively -- with end_frame - 1 exactly one frame
        # was missing at the end of every cut and a gap opened between them.
        return {"mediaPoolItem": c, "startFrame": start_frame, "endFrame": end_frame}

    for e in cut:
        a, b = seconds_to_frames(e["start"], fps), seconds_to_frames(e["end"], fps)
        if b <= a:
            continue
        length = b - a
        # In the timeline: from the window start. In the file: later by as much
        # as this camera started later. Where it was not yet or no longer
        # running, the wide shot takes the place, otherwise a gap would open.
        part = piece(e["camera"], e["start"], length)
        if part is None:
            for cam in fallback:
                if cam["camera"] == e["camera"]:
                    continue
                part = piece(cam["camera"], e["start"], length)
                if part is not None:
                    replaced += 1
                    break
        if part is None:
            skipped.add(T('%s (%s to %s)')
                              % (e["camera"], as_hms(e["start"]), as_hms(e["end"])))
            continue
        part.update({"trackIndex": 1, "recordFrame": origin + lead_in + a,
                     "mediaType": 1})
        item.append(part)
    if replaced:
        print(T('    %dx the intended camera was not running -- a '
                'different one is there.') % replaced)
    for e in sorted(skipped):
        print(T('    Left without picture: %s') % e)
    if not item:
        print(T('  No cut left -- the Timeline stays empty.'))
        return tl
    put = mp.AppendToTimeline(item)
    tl.SetTrackName("video", 1, "Camera cut")
    # Counted from what is on the timeline, not from what was sent. The
    # camera timeline checks every insert; this one used to report the
    # length of the whole cut list even where Resolve had taken nothing,
    # so a timeline that was black for its whole length was announced as
    # finished.
    landed = tl.GetItemListInTrack("video", 1) or []
    if not landed:
        print(as_warn(T('  Resolve took no picture at all -- the Timeline '
                        'is empty. Nothing\n  else is built on it.')))
        return tl
    if len(landed) < len(item):
        print(as_warn(T('  Only %d of %d shots are on the Timeline.')
                      % (len(landed), len(item))))
    on_it = sum(float(x.GetDuration() or 0) for x in landed) / max(
        1.0, float(nearest_known_frame_rate(d.get("fps"))))
    print(T('  %d shots, %.1f s in total, without their audio.')
          % (len(landed), on_it))

    if mix is None:
        print(T('  No Full-Mix found -- the Timeline stays silent.'))
        return tl
    file_path, source_text = mix
    c = clips.get(file_path)
    if c is None:
        print(T('  The Full-Mix could not be imported.'))
        return tl
    # Only the stored mix begins at the In point. The two fallbacks are camera
    # files, and a camera that was already rolling carries that much extra
    # sound at its head; laid down untrimmed the whole mix would run
    # against the picture by exactly that camera's offset.
    mix_cam = next((cam for cam in (d.get("cameras") or [])
                    if cam.get("file") == file_path), None)
    head = (seconds_to_frames(-(mix_cam.get("offset") or 0.0), fps)
            if mix_cam else 0)
    place = {"mediaPoolItem": c, "trackIndex": 1,
             "recordFrame": origin + lead_in, "mediaType": 2}
    if head > 0:
        # endFrame counts exclusively, as for the picture pieces above.
        last = seconds_to_frames(mix_cam.get("duration") or 0.0, fps)
        place["startFrame"] = head
        if last > head:
            place["endFrame"] = last
    applied = mp.AppendToTimeline([place])
    if not applied:
        print(T('  The Full-Mix could not be inserted.'))
        return tl
    tl.SetTrackName("audio", 1, "Audio-Full-Mix")
    print(T('  Audio: Full-Mix in one piece on A1 (%s).') % source_text)
    return tl


def earliest_offset(cameras):
    """Return how far before the In point the earliest camera starts (<= 0)."""
    return min([cam.get("offset") or 0.0 for cam in (cameras or [])] + [0.0])


def add_speaker_markers(tl, speaker, d, from_s=0.0):
    """Add the speaker segments as markers, one colour per person.

    *from_s* is the start of the timeline relative to the In point; negative on
    the multicam timeline, which begins at the earliest camera.
    """
    fps, _origin = timeline_origin(d)
    # Markers count differently from clips: from the start of the timeline
    # rather than from midnight, so no offset here. Resolve allows only one
    # marker per frame. Two speakers starting at once would be a silent loss,
    # so they are collected first, the names merged, and moved on by a frame
    # where necessary.
    on_spot, colour_of = {}, {}
    for idx, s in enumerate(speaker):
        colour_of[s["name"]] = MARKER_COLOURS[idx % len(MARKER_COLOURS)]
        for a, b in s["sections"]:
            e = on_spot.setdefault(seconds_to_frames(a - from_s, fps),
                                     {"names": [], "length": 1})
            e["names"].append(s["name"])
            e["length"] = max(e["length"], seconds_to_frames(b - a, fps))
    applied, lost = 0, 0
    for frames in sorted(on_spot):
        e = on_spot[frames]
        colour = colour_of.get(e["names"][0], MARKER_COLOURS[0])
        for shift in range(0, 10):
            if tl.AddMarker(frames + shift, colour, " + ".join(e["names"]),
                            "", max(1, e["length"])):
                applied += 1
                break
        else:
            lost += 1
    print(TN(applied, '  %d marker set%s.', '  %d markers set%s.')
          % (applied, T(', %d not (no free picture)') % lost
             if lost else ""))
    return applied


class Transcript(object):
    """Write everything printed to a file as well.

    A lot goes wrong in the Resolve part that only shows afterwards: which
    timeline was created, which settings Resolve accepted, which file was
    not found again.
    """

    def __init__(self, file_path):
        self.file = open(file_path, "w", encoding="utf-8")
        self.old = sys.stdout

    def write(self, text):
        self.old.write(text)
        # The kind marker is for the screen; the file gets plain text.
        self.file.write(strip_marks(text))

    def flush(self):
        self.old.flush()
        self.file.flush()

    def __enter__(self):
        sys.stdout = self
        return self

    def __exit__(self, *_):
        sys.stdout = self.old
        self.file.close()


HINT_MULTICAM = ('\n  To convert: in the media pool right-click "%s '
                 'Multicam" >\n  "Convert Timeline to Multicam Clip" > '
                 '"Use Source Audio Channels".\n  One way only -- but a '
                 'new run rebuilds the Timeline at any time.\n  Angles:%s\n '
                 ' Everything else -- audio choice, colour groups, '
                 'framing -- is in the\n  manual, docs/resolve.md.\n')



# How the command line switch is named and how the field behind it. All others
# are named alike, with an underscore instead of a hyphen.
SLIDER_TO_DEST = {"edit-change-delay": "delay"}


def cut_slider_defaults():
    """Return the camera cut sliders with their defaults.

    Derived from CUT_FIELDS so there is a single source. The same number in
    three places drifts apart, and then the same data yields a different cut
    depending on which path produced it.
    """
    out = []
    for api_key, _b, default_value, _e, _k, _l in CUT_FIELDS:
        field = SLIDER_TO_DEST.get(api_key, api_key.replace("-", "_"))
        try:
            out.append(("--" + api_key, field, float(default_value)))
        except ValueError:
            continue
    out.append(("--lufs", "lufs", -16.0))
    return out


def _sliders_from_command_line(call, production):
    """Recover the sliders from the stored command line.

    A stand-in for the command line, complete enough for write_cut_list.
    """
    class Sliders(object):
        pass
    e = Sliders()
    e.production = production
    e.no_wide_edges = "--no-wide-edges" in (call or [])
    for switch, field, default_value in cut_slider_defaults():
        value = default_value
        if call and switch in call:
            i = call.index(switch)
            if i + 1 < len(call):
                try:
                    value = float(call[i + 1])
                except ValueError:
                    pass
        setattr(e, field, value)
    for switch, _caption, default_value, values, _k, _l in CUT_CHOICES:
        value = default_value
        if call and "--" + switch in call:
            i = call.index("--" + switch)
            if i + 1 < len(call) and call[i + 1] in values:
                value = call[i + 1]
        setattr(e, switch.replace("-", "_"), value)
    return e


def _read_project_file(folder):
    for file_path in sorted(glob.glob(os.path.join(folder,
                                              "videopodcast-magic_*.json"))):
        try:
            with open(file_path, encoding="utf-8") as f:
                return json.load(f)
        except (OSError, ValueError):
            continue
    return {}


def refresh_cut_list(d, file_path):
    """Check the cut list is still valid before building.

    Who speaks when is in the handover file already, so turning the cut
    values afterwards costs no run and no measurement. What only a new
    run can mend: In point or Out point changed since, and then the
    audio inside the videos belongs to a different window. The return
    value is that reason as text.
    """
    folder = os.path.dirname(os.path.abspath(file_path))
    project = _read_project_file(folder)
    speakers = [(x.get("name") or "", [tuple(v) for v in
                                       (x.get("sections") or [])])
                for x in (d.get("speakers") or [])]
    if not speakers or not project or d.get("start_s") is None:
        return None
    fps = max(1.0, float(d.get("fps_measured") or d.get("fps") or 30.0))
    call = project.get("call") or []

    # Does the project file now hold a different time window from the handover?
    # Then the audio files no longer match it.
    def tc_value(switch):
        if switch not in call:
            return None
        i = call.index(switch)
        if i + 1 >= len(call):
            return None
        try:
            return parse_timecode(call[i + 1], fps)
        except Exception:
            return None
    in_point, out_point = tc_value("--in-point"), tc_value("--out-point")
    length = float(d.get("length_s") or 0.0)
    if in_point is not None and abs(in_point - float(d["start_s"])) > 0.5:
        return (T('In point is now %s, but the existing files belong to %s.\n '
                  ' The audio in the videos is cut to the old window -- '
                  'press Start\n  above again.')
                % (timecode_string(in_point, fps), d.get("start_tc") or "?"))
    if (in_point is not None and out_point is not None and length
            and abs((out_point - in_point) - length) > 0.5):
        return (T('Out point is now %s; the window would be %s long, the '
                  'existing\n  files are %s -- press Start above again.') % (timecode_string(out_point, fps), as_hms(out_point - in_point),
                            as_hms(length)))

    print(T('\n  REFRESH THE CUT LIST'))
    # The sliders come from the interface where they were sent along, otherwise
    # from the project file. Otherwise the button would carry on with the
    # values of the last run while something else is set above.
    command_line = [a for a in sys.argv[1:]]
    own_measure = any(a.startswith("--wide-")
                 or a in ("--min-edit-duration", "--edit-change-delay")
                 for a in command_line)
    settings = _sliders_from_command_line(command_line + call,
                                          d.get("production"))
    if own_measure:
        settings.no_wide_edges = "--no-wide-edges" in command_line
    cameras = [{"video": cam["source"], "name": cam["camera"]}
               for cam in (d.get("cameras") or []) if cam.get("source")]
    videos = [(cam["video"], None) for cam in cameras]
    tracks = [{"name": n, "camera": cam["source"]}
              for cam in (d.get("cameras") or [])
              for n in (cam.get("speakers") or [])]
    ref_clip = (cameras[0]["video"] if cameras else "",
                {"fps": fps, "tc": d.get("start_tc")})
    # The handover file carries what was said and where the sound is:
    # the cut points come from those two, not from the clock.
    cut, segs = write_cut_list(
        settings, speakers, tracks, cameras, videos, folder,
        float(d["start_s"]), ref_clip, length,
        words=words_from_handover(d),
        sound_source=(d.get("audio_files") or {}).get("Full-Mix", ""))
    if not cut:
        return T('That produced no cut -- press Start above again.')
    before_value = d.get("cut") or []
    d["cut"] = [{"start": round(a, 3), "end": round(b, 3), "camera": n}
                    for a, b, n in cut]
    if d["cut"] == before_value:
        print(T('  The cut stays as it was.'))
    else:
        print(T('  The cut has changed: %d shots instead of %d.')
              % (len(d["cut"]), len(before_value)))
    d["speakers"] = [{"name": n, "sections": [[round(a, 3), round(b, 3)]
                                                for a, b in segs2]}
                     for n, segs2 in segs]
    d["created_by"] = ('videopodcast-magic.py %s (cut list refreshed)'
                       % VERSION)
    # Written beside it and moved into place. This file is the whole
    # product of a long run -- the measured offsets, the cut, the speaker
    # statistics -- and writing straight onto it means a failure half way
    # leaves a fragment that the next run silently skips.
    beside = file_path + ".new"
    try:
        with open(beside, "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=1)
        os.replace(beside, file_path)
    except OSError as e:
        try:
            os.unlink(beside)
        except OSError:
            pass
        print(T('  %s could not be rewritten: %s')
              % (os.path.basename(file_path), e))
    return None


def build_resolve_project(source, project_carry_on=None, project_name=None,
                  sources=False, log=None):
    """Build a Resolve project from the handover file.

    *source* is the path to the ..._resolve.json or its parsed contents.
    """
    d = source
    source_path = None
    if not isinstance(d, dict):
        source_path = source
        with open(source, encoding="utf-8") as f:
            d = json.load(f)
        if log is None:
            log = os.path.splitext(source)[0] + "_log.txt"
        complaint = format_complaint(d)
        if complaint:
            print(as_bad(T('Abort: %s') % complaint))
            return 1
        d["_source_path"] = source_path
    if log:
        # Only opening the file may fail here. Wrapping the build itself
        # would run it a second time on any disk error.
        try:
            written = Transcript(log)
        except OSError as e:
            written = None
            print(T('  Transcript not possible (%s) -- it runs anyway.')
                  % e)
        if written is not None:
            with written:
                code = build_resolve_project(d, project_carry_on, project_name,
                                     sources, "")
            print(T('  Transcript: %s') % log)
            return code
    source_path = d.pop("_source_path", None)
    if source_path:
        bad = refresh_cut_list(d, source_path)
        if bad:
            print(T('\n  STOPPED: %s') % bad)
            return 1
    name = project_name or d.get("production") or 'Production'
    cameras = []
    for cam in (d.get("cameras") or []):
        file_path = cam.get("source") if sources else (cam.get("file")
                                                or cam.get("source"))
        if not file_path:
            continue
        e = dict(cam)
        e["file"] = file_path
        cameras.append(e)
    if not cameras:
        print(T('  No cameras in the handover -- nothing to build.'))
        return 1

    print(as_head("\nRESOLVE"))
    r = connect_to_resolve()
    print("  %s %s" % (r.GetProductName(), r.GetVersionString()))
    pm = r.GetProjectManager()
    p, kind = open_or_create_project(pm, name, project_carry_on)
    # Held under its own name: the loop over intro and outro further down
    # binds "kind" again, and the render job still has to know whether this
    # project is one from a minute ago or one somebody set up.
    project_is_new = kind == "created"
    if kind == "update":
        # Only the cut timeline. The multicam one is not touched here: it
        # carries manual work -- the multicam clip is converted from it by
        # hand -- and further down there is a check that leaves it alone
        # when the same cameras still sit on it in the same order. Deleting
        # it up here made that check unreachable and threw the work away.
        gone, stayed = refresh_resolve_timelines(
            p, p.GetMediaPool(), ["%s Cut" % name])
        if gone:
            print(T('  Deleted: %s -- being rebuilt now.')
                  % ", ".join(repr(n) for n in gone))
        if stayed:
            print(as_warn(T('  Caution: %s could not be deleted -- the new '
                            'Timeline therefore gets\n  an addition to its '
                            'name.')
                          % ", ".join(repr(n) for n in stayed)))
        if not gone and not stayed:
            print(T('  No such Timeline existed yet -- it is only built.'))
        print(T('  The media pool stays as it is.'))

    print(T('\n  Settings'))
    apply_project_settings(p, d)
    set_loudness_target(p, d.get("lufs") or -16.0)
    # Always set, never skipped: a project from an earlier run would still have
    # remote grades on.
    set_remote_grades(p)
    if kind == "keep":
        # The setting only takes effect for clips added afterwards. What is
        # already there keeps its remote grade.
        print(T('    Clips from an earlier run are still tied to their '
                'remote grades. On the\n    colour page right-click a '
                'thumbnail > '
                '"Copy Remote Grades to Local"\n    (takes the correction '
                'along) or "Use Local Grades". New Timelines\n    do not '
                'need this.'))

    print("\n  Import")
    mp = p.GetMediaPool()
    # The overall mix comes along as its own file where it exists, so nobody
    # has to guess which audio track in which camera is the right one.
    mix = mix_file_from_handover(d)
    to_insert = [cam["file"] for cam in cameras]
    if mix[0] and mix[0] not in to_insert:
        to_insert.append(mix[0])
    for kind in ("intro", "outro"):
        entry = d.get(kind)
        if entry and entry.get("source") not in to_insert:
            to_insert.append(entry["source"])
    clips = import_media(mp, to_insert)

    # What gets built depends on what is there. A camera cut needs the speaker
    # statistics; a multicam clip needs more than one camera. Missing either,
    # that timeline is not created at all -- an empty one helps nobody.
    only_one = len(cameras) < 2
    tl = None
    if d.get("cut"):
        print(T('\n  Timeline with the finished cut'))
        tl = create_timeline(mp, "%s Cut" % name)
        # No speaker markers here: the cut is already made and the markers
        # would only sit around under the clips.
        _fps, _origin = timeline_origin(d)
        lead_in = lead_in_offset(mp, tl, d, clips, _fps, _origin)
        build_cut_timeline(mp, tl, d["cut"], cameras, clips, d,
                                 mix if mix[0] else None, lead_in)
        colour_clips_by_camera(tl, cameras)
        insert_intro_and_outro(mp, tl, d, clips, _fps, _origin, lead_in)
        create_colour_groups(p, tl, cameras)
        queue_render_job(p, tl, d, output_folder_from(d), name,
                         project_is_new)
    elif only_one:
        # One camera, one audio track: nothing to switch between. The straight
        # timeline is then the right one -- picture in one piece, mix beneath.
        print(T('\n  Timeline: the camera in one piece, the mix below'))
        tl = create_timeline(mp, "%s Cut" % name)
        length = float(d.get("length_s") or 0.0) or float(
            cameras[0].get("duration") or 0.0)
        _fps, _origin = timeline_origin(d)
        lead_in = lead_in_offset(mp, tl, d, clips, _fps, _origin)
        build_cut_timeline(
            mp, tl, [{"start": 0.0, "end": length,
                      "camera": cameras[0]["camera"]}],
            cameras, clips, d, mix if mix[0] else None, lead_in)
        colour_clips_by_camera(tl, cameras)
        insert_intro_and_outro(mp, tl, d, clips, _fps, _origin, lead_in)
        create_colour_groups(p, tl, cameras)
        queue_render_job(p, tl, d, output_folder_from(d), name,
                         project_is_new)
    else:
        print(T('\n  No camera cut in the handover -- without speaker '
                'statistics there is none.\n  Only the Timeline for the '
                'multicam clip is built.'))

    if only_one:
        print(T('\n  Only one camera -- a multicam clip would be pointless.'))
        if tl is not None:
            p.SetCurrentTimeline(tl)
        return 0

    print(T('\n  Timeline for the multicam clip: all cameras, uncut'))
    ordered = cameras_in_track_order(cameras)
    existing = multicam_timeline_unchanged(p, "%s Multicam" % name, ordered)
    if existing is not None:
        print(T('  It already exists, with the same cameras in the same '
                'order -- it stays\n  untouched. Whoever wants a new one '
                'deletes it in Resolve.'))
        if tl is not None:
            p.SetCurrentTimeline(tl)
        print(T(HINT_MULTICAM)
              % (name, "".join("\n    V%-3d %s" % (i, cam["track"])
                               for i, cam in enumerate(ordered, 1))))
        return 0
    if find_timeline(p, "%s Multicam" % name) is not None:
        # It is there but holds other cameras. It is not deleted: whatever
        # was done to it by hand is worth more than a tidy name, and the
        # multicam clip made from it would be gone with it.
        print(as_warn(T('  A Timeline of this name is there with other '
                        'cameras on it. It stays;\n  the new one is built '
                        'beside it under a name of its own.')))
    tl2 = create_timeline(mp, "%s Multicam" % name)
    if ordered and ordered[0] is not cameras[0]:
        print(T('  %s goes on video track 1 -- there the first audio track '
                'carries the\n  Full-Mix, and video track 1 becomes angle 1.')
              % ordered[0]["camera"])
    build_camera_timeline(mp, tl2, ordered, clips, d)
    colour_clips_by_camera(tl2, ordered)
    create_colour_groups(p, tl2, ordered)
    # Converting to a multicam clip is a one-way operation; a new run
    # rebuilds this timeline from the handover file.
    if d.get("speakers"):
        add_speaker_markers(tl2, d["speakers"], d, from_s=earliest_offset(ordered))

    p.SetCurrentTimeline(tl if tl is not None else tl2)
    print(T(HINT_MULTICAM)
          % (name, "".join("\n    V%-3d %s" % (i, cam["track"])
                           for i, cam in enumerate(ordered, 1))))
    return 0


def handover_for_single_track(args, videos, results, cameras, offsets, track_names,
                    folder, audio):
    """Prepare a Resolve handover for the simple path too.

    What comes of it depends on the material: with several cameras a
    timeline holding all of them side by side, ready to become a multicam
    clip, with speaker and picture analysis then running in Resolve. With a
    single camera a straight timeline of picture and audio. There can be no
    camera cut here; that needs the speaker statistics, which only the
    multitrack path produces.
    """
    if not cameras:
        return
    if not getattr(args, "production", None):
        args.production = guess_production_name(cameras[0]["video"])
    # The longest recording is the reference; the axis hangs off its timecode.
    reference = max(videos, key=lambda x: x[1].get("duration") or 0.0)
    fps = max(1.0, float(reference[1].get("fps") or 30.0))
    tc_start = (parse_timecode(reference[1]["tc"], fps) if reference[1].get("tc") else None)
    # Refer all offsets to the reference so it sits at zero itself.
    reference_target = None
    for cam in cameras:
        if os.path.abspath(cam["video"]) == os.path.abspath(reference[0]):
            for path in results:
                if os.path.splitext(os.path.basename(path))[0] == cam["name"]:
                    reference_target = path
    origin = offsets.get(reference_target, 0.0) if reference_target else 0.0
    offsets = dict((name, round(value - origin, 4)) for name, value in offsets.items())
    length = max((float(e.get("duration") or 0.0) for _, e in videos), default=0.0)
    write_handover(args, [], cameras, videos, folder, tc_start,
                      reference, results, None, None, length, track_names,
                      {"Full-Mix": os.path.abspath(audio)}, offsets)


def widest_frame(sizes):
    """Pick the largest frame that a camera really recorded.

    Not the largest width beside the largest height: a landscape and a
    portrait camera in one production would then give a square frame that
    no camera has, and Resolve scales everything into it.
    """
    if not sizes:
        return (None, None)
    return max(sizes, key=lambda wh: (wh[0] * wh[1], wh[0]))


def write_handover(args, tracks, cameras, videos, folder, tc_start,
                      ref_clip, results=None, cut=None, segment_list=None,
                      length=0.0, track_names=None, single_files=None,
                      offsets=None, words=()):
    """Write everything Resolve needs: the handover file and instructions.

    The Resolve scripting interface has no multicam: the word does not
    appear once in the bundled README (version 21), and the manual lists the
    conversion only as a menu command. Project, import, timeline, track
    names and markers can be driven remotely, and that is what
    build_resolve_project does from the file written here. The last step --
    right-click on the timeline -- stays manual.
    """
    if not cameras:
        return
    fps = ref_clip[1]["fps"] if ref_clip else 30.0
    stem = os.path.join(folder, safe_filename(args.production or 'Production'))
    done = {}
    for p in (results or []):
        done[os.path.splitext(os.path.basename(p))[0]] = os.path.abspath(p)

    resolutions, rates = set(), set()
    for _, e in videos:
        if e.get("width"):
            resolutions.add((e["width"], e["height"]))
        rates.add(round(float(e.get("fps") or 0), 3))
    takes = {os.path.abspath(v): (e.get("duration") or 0.0)
              for v, e in videos}
    speaker_of = {}
    for track in tracks:
        if track.get("camera"):
            speaker_of.setdefault(os.path.abspath(track["camera"]),
                                    []).append(track["name"])

    #----------------------------------------------------- Handover file
    _hdr_flag = hdr_from_sources([cam["video"] for cam in cameras])
    items = []
    unmeasured = []
    for cam in cameras:
        v = os.path.abspath(cam["video"])
        who = speaker_of.get(v) or []
        file = done.get(cam["name"], "")
        # The offsets are kept under the rendered file. A camera without a
        # render has no such key, and 0.0 as a fallback would put it at the
        # start of the axis instead of where it was measured -- so the
        # source is tried too, and what stays unknown gets said out loud.
        shift = (offsets or {}).get(file)
        if shift is None:
            shift = (offsets or {}).get(v)
        if shift is None:
            shift = 0.0
            if offsets:
                unmeasured.append(cam["name"])
        items.append({
            "file": file,
            "source": v,
            "camera": cam["name"],
            # The track name is a key further along -- the clips of a
            # camera, its audio tracks and its place on the timeline are
            # all looked up by it, so it has to be unique. The camera's
            # own name is: one word for every camera without a speaker
            # would put two of them on one key, and the second would
            # take the first one's place on the timeline while the table
            # still listed both.
            "track": (" + ".join(who) if who else cam["name"]),
            "speakers": who,
            "audio_tracks": (track_names or {}).get(file, []),
            # Where this camera starts in the shared window: measured, not
            # guessed from the timecode. Without it the cut timeline would hold
            # the wrong piece of every camera.
            "offset": round(shift, 4),
            "duration": round(takes.get(v, 0.0), 3),
            "wide": not who})
    if unmeasured:
        print(as_warn(T('  No measured offset for %s -- placed at the '
                        'start of the axis.') % ", ".join(unmeasured)))
    handover = {
        "format": FILE_FORMAT,
        "created_by": "videopodcast-magic.py %s" % VERSION,
        "production": args.production or 'Production',
        "fps": nearest_known_frame_rate(fps),
        "fps_measured": round(fps, 4),
        "drop_frame": is_drop_frame(ref_clip[1].get("tc") if ref_clip else None),
        "width": widest_frame(resolutions)[0],
        "height": widest_frame(resolutions)[1],
        "start_tc": (timecode_string(tc_start,
                                     nearest_known_frame_rate(fps))
                     if tc_start is not None else None),
        "start_s": tc_start,
        "length_s": round(length, 3),
        "lufs": getattr(args, "lufs", -16.0),
        # How the render job decides between HDR and SDR: from the colr box of
        # the camera files. The Resolve project wins later, but without a
        # project this is the truth.
        "hdr": _hdr_flag[0],
        "hdr_reason": _hdr_flag[1],
        # Intro and outro are finished clips: they are not aligned, not
        # processed and not copied -- they only go into the timeline.
        "intro": _intro_outro_entry(getattr(args, "intro", None)),
        "outro": _intro_outro_entry(getattr(args, "outro", None)),
        "cameras": items,
        "cut": [{"start": round(a, 3), "end": round(b, 3), "camera": n}
                    for a, b, n in (cut or [])],
        "speakers": [{"name": n,
                      "sections": [[round(a, 3), round(b, 3)]
                                     for a, b in segs]}
                     for n, segs in (segment_list or [])],
        # The stored single tracks: the audio of the cut timeline comes from
        # them, regardless of the order the audio tracks sit in inside the
        # camera files.
        "audio_files": dict(single_files or {}),
        # What was said and when. Three values a word rather than an
        # object with three named keys: an hour of speech is around
        # twelve thousand words, and the key names alone would be the
        # larger half of the file.
        "words": words_for_handover(words or []),
    }
    js = stem + "_resolve.json"
    # Beside it, then moved into place: a run that dies while writing
    # would otherwise replace a usable handover file with a fragment,
    # and the next run skips a broken one without a word.
    try:
        with open(js + ".new", "w", encoding="utf-8") as f:
            json.dump(handover, f, ensure_ascii=False, indent=1)
        os.replace(js + ".new", js)
    except OSError as e:
        try:
            os.unlink(js + ".new")
        except OSError:
            pass
        print(T('\n  Could not write %s: %s') % (js, e))
        js = None

    # -------------------------------------------------------- instructions
    #
    # Keep it short: where the Resolve part is included, it says everything
    # needed itself. Only what can be known without it is written here.
    stem_p = safe_filename(args.production or 'Production')
    lines = [as_head(T('FOR RESOLVE')), ""]
    if not js:
        lines.append(T('  The handover file could not be written.'))
    else:
        lines.append("  %s" % os.path.basename(js))
        lines.append("")
        # What actually gets built depends on the material -- the text should
        # not promise two timelines when only one arrives.
        has_cut = bool(cut)
        several = len(cameras) > 1
        lines.append(T('  This produces the project, the import and %s:')
                      % (T('two Timelines') if has_cut and several
                         else T('one Timeline')))
        if has_cut:
            lines.append(T('    %-26s picture from the camera cut, audio '
                           'in one piece')
                          % (stem_p + ' Cut'))
        elif not several:
            lines.append(T('    %-26s the camera in one piece, the mix below')
                          % (stem_p + ' Cut'))
        if several:
            lines.append(T('    %-26s all cameras side by side -- becomes '
                           'the multicam clip') % (stem_p + " Multicam"))
        if not getattr(args, "resolve", False):
            lines.append("")
            lines.append(T('  Create it with "Create Resolve project" in '
                           'the interface. Resolve must be running.'))

    print("\n" + "\n".join(lines))
    if js:
        print("")
        for p in (js, stem + "_speakers.csv", stem + "_speakers.edl",
                  stem + "_cameracut.csv",
                  stem + "_cameracut.edl"):
            if os.path.exists(p):
                print("  %s" % p)
    if js and getattr(args, "resolve", False):
        try:
            build_resolve_project(handover, args.resolve_project,
                          log=stem + "_resolve_log.txt",
                          )
        except Exception as e:
            print(T('\n  Resolve part stopped: %s') % e)
            print(T('  %s is ready -- with --resolve-json it can be done '
                    'later.') % os.path.basename(js))


def write_cut_list(args, segment_list, tracks, cameras, videos, folder,
                           tc_start, ref_clip, length, words=(),
                           sound_source=""):
    """Write the speaker list, markers and camera cut.

    Returns (camera cut, speaker segments) so the Resolve handover uses the
    same result instead of recomputing it.

    *segment_list* says who speaks when; the caller works that out and
    says in the log where it came from. *words* and *sound_source* say
    where the cut points come from: the text says roughly where a cut
    belongs, the sound says exactly where.
    """
    fps = max(1.0, ref_clip[1]["fps"]) if ref_clip else 30.0
    if not any(segs for _, segs in (segment_list or ())):
        print(as_head(T('\nSPEAKERS\n  Nobody was heard -- no camera '
                        'cut from this.')))
        return [], []
    length = length or max((b for _n, segs in segment_list
                            for _a, b in segs), default=0.0)
    tc0 = tc_start if tc_start is not None else 0.0

    # Who belongs to which camera, and which one is the wide shot?
    output_name = {os.path.abspath(cam["video"]): cam["name"] for cam in cameras}
    camera_of = {}
    taken = set()
    for track in tracks:
        if track.get("camera"):
            v = os.path.abspath(track["camera"])
            camera_of[track["name"]] = output_name.get(v,
                                                     os.path.basename(v))
            taken.add(v)
    free = [v for v, _ in videos if os.path.abspath(v) not in taken]
    wide_shot = (output_name.get(os.path.abspath(free[0]),
                              os.path.basename(free[0])) if free
              else (output_name.get(os.path.abspath(ref_clip[0]))
                    if ref_clip else "Wide"))

    stem = os.path.join(folder, safe_filename(args.production or 'Production'))
    lines = sorted((a, b, n) for n, segs in segment_list for a, b in segs)
    with open(stem + "_speakers.csv", "w", encoding="utf-8") as f:
        f.write(csv_line(("Speaker", "Start TC", "End TC",
                          "Time from start", "Duration s")))
        for a, b, n in lines:
            f.write(csv_line((n, timecode_string(tc0 + a, fps),
                              timecode_string(tc0 + b, fps),
                              as_hms(a, "."), "%.2f" % (b - a))))
    write_edl(stem + "_speakers.edl", "Speakers", lines, tc0, fps)

    print(as_head(T('\nCAMERA CUT')))
    # The interface shows the whole cut as a band, so the closing line is
    # enough here.
    rules = rules_from_settings(args)
    rules["words"] = list(words or ())
    rules["levels"] = sound_levels(sound_source) if sound_source else []
    edges_on = not getattr(args, "no_wide_edges", False)
    cut = camera_cut(
        segment_list, length, camera_of, wide_shot,
        args.min_edit_duration, getattr(args, "delay", 0.3),
        args.wide_after, args.wide_length,
        getattr(args, "wide_latest", 120.0), edges_on, rules,
        faint=GUI_RUNNING)
    before_value = len(cut)
    if args.wide_after > 0 and not GUI_RUNNING:
        before_value = len(camera_cut(
            segment_list, length, camera_of, wide_shot,
            args.min_edit_duration, getattr(args, "delay", 0.3),
            0.0, args.wide_length, getattr(args, "wide_latest", 120.0),
            edges_on, rules))
    if args.wide_after > 0 and len(cut) > before_value and not GUI_RUNNING:
        print(T('  %dx away from the speaker because a shot ran '
                'longer than %.0f s') % ((len(cut) - before_value) // 2,
                                    args.wide_after))
    # One camera for everybody: the cut is then a single long shot and
    # says nothing. Cut again at the change of speaker -- the picture
    # stays the same, but Resolve gets one clip per speaker, which can
    # be grouped, coloured and zoomed into there.
    detail = split_shots_by_speaker(cut, segment_list, args.min_edit_duration)
    alone = one_camera_only(camera_of)
    if alone and len(detail) > len(cut):
        cut = [(a, b, who) for a, b, who, _speaking in detail]
        print(T('  One camera for everybody: cut into %d shots at the '
                'change of speaker, so Resolve can group them.')
              % len(cut))
    with open(stem + "_cameracut.csv", "w", encoding="utf-8") as f:
        f.write(csv_line(("Shot", "Camera", "Speaker", "Start TC",
                          "End TC", "Duration s")))
        for i, (a, b, n, speaking) in enumerate(detail, 1):
            f.write(csv_line((i, n, " + ".join(speaking),
                              timecode_string(tc0 + a, fps),
                              timecode_string(tc0 + b, fps),
                              "%.2f" % (b - a))))
    write_edl(stem + "_cameracut.edl", "Camera cut",
              [(a, b, " + ".join(speaking) or n)
               for a, b, n, speaking in detail] if alone else cut,
              tc0, fps)

    # The individual numbers are in the interface and in the files; what came
    # of them is enough here.
    print(T('  %d speakers, %d shots, shortest %.1f s')
          % (len(segment_list), len(cut),
             min((b - a) for a, b, _ in cut) if cut else 0))
    return cut, segment_list


